INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('LEYES', ' ', 'El documento entregado en el Registro Civil cuando dos personas se casan o nace el primer hijo de una pareja de hecho o familia monoparental se llama…', 'Libro de familia', ' ', 'https://www.exteriores.gob.es/Consulados/caracas/es/ServiciosConsulares/Paginas/index.aspx?scca=Familia&scco=Venezuela&scd=45&scs=Libro+de+Familia', 'LEANDRO', 'LUIS', ' ', 'REVISAR
