INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('HISTORIA', 'MITOLOGÍA', 'En la mitología yoruba, ¿quién es la diosa del Mar y la Fertilidad?', 'Yemayá/Yemanyá', 'Isabel Pantoja tiene una canción dedicada a Yemanyá:
Yemanyá, está en el cielo la luna llena
