INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('GEOGRAFÍA', ' ', '¿En qué país encontramos la "Ciudad de los Muertos"?', 'En Egipto', 'Esta necrópolis está en El Cairo y fue declarada Patrimonio de la Humanidad por la UNESCO. Casi un millón y medio de personas viven aquí, entre tumbas y mausoleos, por las demoliciones y presiones urbanísticas de la ciudad. Es un sitio peligroso y no se aconseja visitarlo', 'https://www.britannica.com/place/City-of-the-Dead
https://viajes.nationalgeographic.com.es/ubicacion-exacta/muy-poblada-ciudad-muertos-cairo-que-es-patrimonio-humanidad_20107#:~:text=De%20hecho%2C%20la%20gran%20mayor%C3%ADa,en%20la%20d%C3%A9cada%20de%201950.', 'LEANDRO', 'LUIS', ' ', 'Sara: es un poco chungui porque son chabolas en un cementerio, hay malos rollos…', 'borrador', '_5LS', NOW(), 0);
