INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('NATURALEZA', ' ', '¿Qué cetáceo puede presumir de tener los dientes más grandes del mundo marino?', 'El cachalote', '"Dientes, dientes, que eso es lo que les jode". Los dientes pueden medir entre 10 y 20 cm de largo y pesar hasta 1 kg cada uno.', 'https://iwc.int/about-whales/whale-species/sperm-whale
