INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('NATURALEZA', ' ', '¿A qué pescado llamamos pescadilla cuando pesa menos de dos kilos?', 'A la merluza', 'La merluza es un pescado blanco que pertenece a la familia de los gádidos, como el bacalao o el abadejo.', 'https://www.mapa.gob.es/ca/ministerio/servicios/informacion/pescadilla_tcm34-102845.pdf
