INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('NATURALEZA', ' ', 'Si te digo que me he comprado un asiento de suegra para el jardín, ¿de qué tipo de planta estamos hablando?', 'De un cactus', 'Es un cactus enorme con forma de barril, originario de México. Qué mala leche, llamarle asiento de suegra. ¡Un beso a las suegras!', 'https://fertinagrovida.com/el-rincon-de-tus-plantas/ornamental/asiento-de-suegra
