INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('NATURALEZA', ' ', '¿Qué parte de su cuerpo agita la serpiente de cascabel en señal de advertencia o amenaza?', 'La cola', 'Agita la punta de la cola cuando se siente amenazada, aunque si la escuchas, el que está amenazado eres tú.', 'https://www.nationalgeographic.es/animales/2021/08/como-enganan-las-serpientes-de-cascabel-a-los-humanos-sobre-donde-estan-exactamente', 'LEIVA', 'LUIS', 'COMENTARIO
