INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('LITERATURA', ' ', 'Nació en Córdoba en el siglo XII y fue clave en la historia del pensamiento medieval. ¿Cómo se llama el filósofo?', 'Averroes', 'Fue el filósofo, astrónomo y escritor árabe más avanzado de su tiempo.', 'https://filco.es/averroes/
https://www.turismodecordoba.org/averroes
https://www.bne.es/es/autores/averroes
https://www.march.es/es/madrid/conferencia/maimonides-averroes-dos-sabios-que-iluminaron-pensamiento-medieval-ii-averroes', 'LEIVA', 'LUIS', 'ACOTAR
