INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('HISTORIA', ' ', '¿Durante qué califato Córdoba alcanzó su máximo esplendor en la Edad Media?', 'Omeya', 'El Califato Omeya de Córdoba fue una era dorada del Al-Ándalus que situó a Córdoba entre las grandes capitales del mundo. Tenía mezquitas, bibliotecas, baños públicos y calles iluminadas.', 'https://www.arqueocordoba.com/historia/medieval/califal/
https://historia.nationalgeographic.com.es/a/mezquita-cordoba-esplendor-al-andalus_16265
https://historia.nationalgeographic.com.es/a/califato-cordoba-esplendor-al-andalus_19598', 'LEIVA', 'LUIS', 'ACOTAR
