INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('ARTE', ' ', 'Tiene más de 20.000 bloques de piedra, fue construido por los romanos y no lleva ni una gota de cemento. ¿Qué monumento es?', 'El acueducto de Segovia', 'Y luego hay gente que no sabe ni colgar un cuadro.', 'https://www.spain.info/es/lugares-interes/acueducto-segovia/', 'LEIVA', 'LUIS', 'ACOTAR
