INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('TRADICIONES', ' ', '¿Cuántas piezas tiene el tablero de ajedrez al inicio de la partida? #PreguntaMolona de @lomin98_miguel por Instagram.', '32 piezas', 'Un tablero de ajedrez tiene 64 casillas con 32 piezas, 16 para cada bando. Y en cada lado hay un rey, una dama, dos torres, dos alfiles, dos caballos y ocho peones.', 'https://ajedrez.pro/piezas
