INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('MÚSICA', 'CUESTIONARIO MUSICAL', '¿Qué término en inglés se refiere al procesador que se usa para corregir o alterar la voz en grabaciones o actuaciones musicales?', 'Autotune', ' ', 'https://www.fundeu.es/recomendacion/autotune-termino-valido/#:~:text=Derivado%20de%20la%20marca%20registrada,en%20grabaciones%20o%20actuaciones%20musicales.', 'SARA', 'LUIS', 'REVISAR
