INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('CULTURA POP', '', '¿Qué peinado comparten Miércoles Addams, Pippi Långstrump y Dorothy de "El mago de OZ"?', 'Las trenzas', 'Sinónimos: crineja, crizneja, clineja, soguillas.  Son muy socorridas. También las llevaba Daenerys en "Juego de tronos", la princesa Leia antes de los moños de fallera...', 'https://www.fotogramas.es/famosos-celebrities/g3677191/protagonistas-con-trenzas/', 'SARA', 'LUIS', 'DUDA
