INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('NATURALEZA', ' ', '¿Qué tipo de ser vivo es un coral marino?', 'Un animal', 'Aunque parezcan algas o incluso rocas, los corales son animales coloniales formados por cientos o incluso miles de individuos.', 'https://www.nationalgeographic.com.es/animales/coral', 'SARA', 'LUIS', 'ACOTAR
