INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('CULTURA POP', ' ', '¿Cómo se llamaba la humorista que ponía voz a los personajes de Doña Rogelia, el león Rodolfo, el pato Nicol y la niña Daisy? #PreguntaMolona de @maitebonetferrandiz por Instagram.', 'Mari Carmen', 'María del Carmen Martínez, más conocida como Mari Carmen y sus muñecos, una famosa ventrílocua.', 'https://www.elespanol.com/corazon/famosos/20240616/ano-sin-mari-carmen-munecos-vida-unico-hijo-miguel-homenaje-prepara-cuenca/862914107_0.html', 'SARA', 'LUIS', 'MISMA PREGUNTA que la 2214 de Lean
DUDA
