INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('CIENCIAS', ' ', '¿En qué articulación del brazo está el túnel carpiano?', 'En la muñeca / Articulación radiocarpiana', 'Es una abertura entre los huesos de la muñeca y el ligamento que los mantiene unidos. De ahí el nombre de túnel.', 'https://medlineplus.gov/spanish/carpaltunnelsyndrome.html#:~:text=El%20t%C3%BAnel%20carpiano%20es%20una,y%20los%20tres%20primeros%20dedos.', 'SARA', 'LUIS', 'AÑADIR
