INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('', '', 'Los "grillz" son un complemento que se originó en la cultura hip-hop de los años 80 en Estados Unidos. ¿En qué parte del cuerpo se ponen?', 'En los dientes / en la boca / en la dentadura', 'Son accesorios dentales que se colocan sobre los dientes para decorar la sonrisa. Ahora están  muy de moda. La mismísima Rosalía los ha llevado varias veces.', 'https://smile2impress.com/es/blog/grillz-dientes', 'SARA', 'LUIS', 'AÑADIR
También valdría dentadura y jachamenta
https://dle.rae.es/dentadura#5McDAyW', '', 'usada', '_2NLS', NOW(), 0);
