INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('LENGUAJE', 'CURIOSIDADES', '¿A qué institución española corresponde el lema "limpia, fija y da esplendor"?', 'A la RAE/Real Academia de la Lengua Española', ' ', ' ', 'SARA', 'LUIS', 'https://www.rae.es/la-institucion/historia', ' ', 'usada', '_5LS', NOW(), 0);
