INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('DEPORTE', 'FÚTBOL', 'Los futbolistas Iñaki y Nico Williams son hermanos, pero juegan en selecciones distintas. Nico juega con España. ¿Con qué país juega Iñaki?', 'Con Ghana', 'Ambos son nacidos en España, pero de procedencia ghanesa. A pesar de que Iñaki empezó a jugar con la selección española, el sueño de su abuelo era verle jugar con Ghana y él lo cumplió tras una oferta del mismísimo preseidente del país.', ' ', 'SARA', 'LUIS', ' ', ' ', 'usada', '_5LS', NOW(), 0);
