INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('MÚSICA', ' ', '¿Qué grupo dosmilero formado por seis chicas cantaba "aunque parezca mentira me pongo colorada cuando me miras, me pongo colorada"?', 'Papá Levante', 'Fue su primer y casi único gran éxito.', ' ', 'SARA', 'LUIS', ' ', ' ', 'usada', '_2NLS', NOW(), 0);
