INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('CINE', 'Terror, Halloween (TEMÁTICO)', 'Según la Iglesia Católica, si un demonio o un espíritu maligno nos posee, tenemos que llamar a un…', '…exorcista', '"¡Vade retro, Satanás!"', 'https://es.catholic.net/op/articulos/63288/cat/13/quien-puede-hacer-exorcismos-en-la-iglesia-catolica.html#google_vignette', 'FER', 'LUIS', '', 'Sara: OJO FER Y LUIS. Es ambigua, un exorcista no deja de ser un cura. La respuesta podría ser cura, párroco, sacerdote… Además, la veo un poco problemática y no queremos demanda de Abogados Cristianos. El tema de los exorcismos es polémico. Llevémosla por el mundo cinéfilo, please.', 'borrador', '_1LS', NOW(), 0);
INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('LITERATURA', 'Terror, Halloween (TEMÁTICO)', 'Edgar Allan Poe escribió "El Cuervo", un poema narrativo terrorífico. En su traducción al español, ¿qué dos palabras repite este animal parlante?', '"Nunca más"', 'Hasta ''Los Simpson'' han homenajeado esta historia en una de sus ''Casa Árbol de Terror''. TRAS RESOLVER: En gallego "nunca mais", Cuervo anti chapapote.', 'https://revistacontrapunto.com/nunca-mas-el-cuervo-de-edgar-allan-poe/#:~:text=%E2%80%9CEl%20Cuervo%E2%80%9D%20es%20un%20poema,progresivo%20declive%20hacia%20la%20locura.', 'FER', 'LUIS', '', 'Sara: OJO FER,  Los Simpsons no existen en Telecinco…En los títulos usaremos siempre comillas dobles. Las cambio yo misma. FER: gracias!', 'usada', '_5LS', NOW(), 0);
INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('CINE', 'Terror, Halloween (TEMÁTICO)', 'Actriz protagonista de ''El Orfanato'', película de terror del director J. A. Bayona.

¿Qué conocida actriz protagoniza la película de terror "El orfanato" de J. A. Bayona?', 'Belén Rueda', 'XUSO: La película da tanto miedo, que solo con hacer esta pregunta ya estoy temblando. / XUSO tras desvelar la respuesta: Belén Rueda muchas películas.', 'https://www.imdb.com/title/tt0464141/', 'FER', 'LUIS', '', 'Sara: Títulos siempre comillas dobles. Títulos en español solo llevan mayúscula la primera letra y nombres propios. FER: gracias!', 'usada', '_2NLS', NOW(), 0);
