-- Inserción de relaciones cuestionario-pregunta
-- Buscar ID de pregunta para: ¿Qué significan las siglas DNI en España?...
SET @pregunta_id = (SELECT id FROM preguntas WHERE pregunta = '¿Qué significan las siglas DNI en España?' COLLATE utf8mb4_unicode_ci AND respuesta = 'Documento Nacional de Identidad' COLLATE utf8mb4_unicode_ci LIMIT 1);
-- Si no existe la pregunta, mostrar un mensaje de error
SELECT IF(@pregunta_id IS NULL, CONCAT('ERROR: No se encontró la pregunta: ¿Qué significan las siglas DNI en España?...'), CONCAT('Pregunta encontrada con ID: ', @pregunta_id)) AS mensaje;
-- DEBUG: Verificar si se encontró la pregunta ID 1
SELECT IF(@pregunta_id = 1, CONCAT('¡¡¡ ALERTA: Se encontró la pregunta ID 1 para: ¿Qué significan las siglas DNI en España?... !!!'), 'OK') AS debug_id_1;
-- Si no existe la pregunta, insertarla
INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, autor, estado, nivel, fecha_creacion, version, estado_disponibilidad, creacion_usuario_id)
SELECT 'GENERAL', NULL, '¿Qué significan las siglas DNI en España?', 'Documento Nacional de Identidad', 'Especificamos “en España” porque resulta que en EEUU son las del “Director/a Nacional de Inteligencia”.', 'IMPORTADO', 'borrador', '_1LS', NOW(), 0, 'disponible', 1
WHERE (SELECT @pregunta_id) IS NULL;

-- Obtener el ID de la pregunta recién insertada si fue necesario
SET @pregunta_id = IFNULL(@pregunta_id, LAST_INSERT_ID());
-- Insertar relación si se encontró la pregunta y no existe ya la relación (ID Excel: 1 -> Nuevo ID: 1)
INSERT INTO cuestionarios_preguntas (cuestionario_id, pregunta_id, factor_multiplicacion)
SELECT 1, @pregunta_id, 1
