-- Si no existe la pregunta, mostrar un mensaje de error
SELECT IF(@pregunta_id IS NULL, CONCAT('ERROR: No se encontró la pregunta: ¿Qué cocinero español ha sido nombrado Mejor Chef ...'), CONCAT('Pregunta encontrada con ID: ', @pregunta_id)) AS mensaje;
-- DEBUG: Verificar si se encontró la pregunta ID 1
SELECT IF(@pregunta_id = 1, CONCAT('¡¡¡ ALERTA: Se encontró la pregunta ID 1 para: ¿Qué cocinero español ha sido nombrado Mejor Chef ... !!!'), 'OK') AS debug_id_1;
-- Si no existe la pregunta, insertarla
INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, autor, estado, nivel, fecha_creacion, version, estado_disponibilidad, creacion_usuario_id)
SELECT 'GENERAL', NULL, '¿Qué cocinero español ha sido nombrado Mejor Chef del Mundo en los Best Chef Awards tres veces consecutivas, en 2021, 2022 y 2023?', 'Dabiz Muñoz', 'Convirtiéndose así en el primer chef en ganar este galardón en tres ocasiones consecutivas.', 'IMPORTADO', 'borrador', '_3LS', NOW(), 0, 'disponible', 1
WHERE (SELECT @pregunta_id) IS NULL;

-- Obtener el ID de la pregunta recién insertada si fue necesario
SET @pregunta_id = IFNULL(@pregunta_id, LAST_INSERT_ID());
-- Insertar relación si se encontró la pregunta y no existe ya la relación (ID Excel: 717 -> Nuevo ID: 717)
INSERT INTO cuestionarios_preguntas (cuestionario_id, pregunta_id, factor_multiplicacion)
SELECT 717, @pregunta_id, 1
WHERE @pregunta_id IS NOT NULL
AND NOT EXISTS (SELECT 1 FROM cuestionarios_preguntas WHERE cuestionario_id = 717 AND pregunta_id = @pregunta_id);

-- Actualizar nivel de la pregunta si es diferente
UPDATE preguntas SET nivel = '_3LS'
WHERE id = @pregunta_id AND nivel != '_3LS';

-- Actualizar estado de la pregunta a 'usada' al asignarla al cuestionario
UPDATE preguntas SET estado = 'usada', estado_disponibilidad = 'usada'
WHERE id = @pregunta_id;

