-- Inserción de relaciones combo-pregunta
-- Buscar ID de pregunta para: Entre los casi doscientos países reconocidos por l...
SET @pregunta_id = (SELECT id FROM preguntas WHERE pregunta = 'Entre los casi doscientos países reconocidos por la ONU, ¿cuál es el único que empieza por la letra “O”?' COLLATE utf8mb4_unicode_ci AND respuesta = 'Omán' COLLATE utf8mb4_unicode_ci LIMIT 1);
-- Si no existe la pregunta, mostrar un mensaje de error
SELECT IF(@pregunta_id IS NULL, CONCAT('ERROR: No se encontró la pregunta: Entre los casi doscientos países reconocidos por l...'), CONCAT('Pregunta encontrada con ID: ', @pregunta_id)) AS mensaje;
-- Si no existe la pregunta, insertarla
INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, autor, estado, nivel, fecha_creacion, version, estado_disponibilidad, creacion_usuario_id)
SELECT 'GENERAL', NULL, 'Entre los casi doscientos países reconocidos por la ONU, ¿cuál es el único que empieza por la letra “O”?', 'Omán', 'Situado en la Península arábiga. Entre los no reconocidos está Osetia del Norte.', 'IMPORTADO', 'borrador', '_5LS', NOW(), 0, 'disponible', 1
WHERE (SELECT @pregunta_id) IS NULL;

-- Obtener el ID de la pregunta recién insertada si fue necesario
SET @pregunta_id = IFNULL(@pregunta_id, LAST_INSERT_ID());
-- Insertar relación si se encontró la pregunta y no existe ya la relación (ID Excel: 1 -> Nuevo ID: 1)
INSERT INTO combos_preguntas (combo_id, pregunta_id, factor_multiplicacion)
SELECT 1, @pregunta_id, 'X2'
WHERE @pregunta_id IS NOT NULL
AND NOT EXISTS (SELECT 1 FROM combos_preguntas WHERE combo_id = 1 AND pregunta_id = @pregunta_id);

-- Actualizar nivel de la pregunta si es diferente
UPDATE preguntas SET nivel = '_5LS'
WHERE id = @pregunta_id AND nivel != '_5LS';

-- Actualizar estado de la pregunta a 'usada' al asignarla al combo
UPDATE preguntas SET estado = 'usada', estado_disponibilidad = 'usada'
WHERE id = @pregunta_id;

