SET @pregunta_id = (SELECT id FROM preguntas WHERE pregunta = '¿Qué día se celebra la fiesta de la Hispanidad?' COLLATE utf8mb4_unicode_ci AND respuesta = 'El 12 de octubre' COLLATE utf8mb4_unicode_ci LIMIT 1);
-- Si no existe la pregunta, mostrar un mensaje de error
SELECT IF(@pregunta_id IS NULL, CONCAT('ERROR: No se encontró la pregunta: ¿Qué día se celebra la fiesta de la Hispanidad?...'), CONCAT('Pregunta encontrada con ID: ', @pregunta_id)) AS mensaje;
-- Si no existe la pregunta, insertarla
INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, autor, estado, nivel, fecha_creacion, version, estado_disponibilidad, creacion_usuario_id)
