INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, ocupacion, cuestionario_id, combo_id, resultado, notas_grabacion, guionista, valoracion_guionista, duracion, valoracion_final) VALUES (32, @jornada_id_10, '2024-08-02', 'MÁLAGA', 'MARTA
