INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, cuestionario_id, combo_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (535, @jornada_id_146, '2025-06-11', 'PALENCIA', 'JULIO', 67, 'JUBILADO', 532, 435, 2000, 'TC IN: 10:00   TC OUT: 10:47
 ARRANCAMOS CON XUSO SENTADO AL LADO DEL MONUMENTO A LOS MAYORES Y LES PONE NOMBRE A LAS FIGURAS: ENCARNI Y CHENCHO. HABLA CON ELLOS Y VAN COMENTANDO SOBRE LA GENTE QUE PASA DELANTE DE ELLOS,Y SIMULA QUE ENCARNI LE DICE QUE COJA A UN SEÑOR QUE ESTÁ PASANDO, YA QUE PARECE JUBILADO Y ES LO QUE ESTÁN BUSCANDO. EFECTIVAMENTE, JULIO DICE QUE ESTÁ JUBILADO Y VA DE RECADOS, PERO ES TAN FAN DEL PROGRAMA QUE NO SE RESISTE A CONCURSAR. SUPERAMOS LA PRIMERA PREGUNTA Y JULIO NOS MATIZA QUE ESTÁ JUBILADO DESDE HACE 7 MESES Y TODA LA VIDA HA SIDO PROFESOR DE EDUCACIÓN FÍSICA, INCLUSO NOS CUENTA QUE VIVIÓ UNA ETAPA EN MADRID. LA SEGUNDA TAMBIÉN- LA SUPERA Y XUSO LE PREGUNTA SOBRE SU- ETAPA MADRILEÑA. SE VINO A LA CAPITAL A ESTUDIAR Y ALLÍ VIVIÓ LA MOVIDA MADRILEÑA, ALLÍ CONOCIÓ A SU MUJER Y SE LA TRAJO A PALENCIA PORQUE PREFERÍA VIVIR EN TRANQUILIDAD. CON LA TERCERA NO TIENE TANTA SUERTE Y TIENE QUE LLAMAR PRECISAMENTE A SU MUJER PARA QUE LO AYUDE Y LO CONSIGUE (LA LLAMADA ES GRACIOSA, HABLAN DE QUE COMO ÉL AHORA ESTÁ JUBILADO SE ENCARGA DE HACER LA COMIDA) NOS CUENTA QUE CON EL DINERO SE IRÍA DE LUNA DE MIEL A FORMENTERA CON SU MUJER, PORQUE CUANDO SE CASARON NO PUDIERON HACERLA YA QUE TODO FUE DEMASIADO RÁPIDO.- SUPERA LA CUARTA CON UNA SEÑORA MAYOR QUE ES BRUTAL DE GRACIOSA (LE OFR-ECEMOS CONCURSAR PERO NO PODÍA POR TIEMPO) Y JULIO ACUMULA 1000 EUROS. SE LA JUEGA PERO LE SALE EL X2 Y ENCUENTRA A UNA CHICA QUE NO SABE LA RESPUESTA. JULIO SE VA DANDO SALTOS CON SU FAJO DE BILLETES', 'Leandro', '2+', 'Mecánica corta', '23:57', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (536, @jornada_id_146, '2025-06-11', 'PALENCIA', 'CRIS', 46, 'DIETISTA', '@cristilievana', 556, 423, 13800, 'TC IN: 11:08    TC OUT: 11:54 EMPEZAMOS HACIENDO ACTING DE XUSO REPORTERO PARA QUE ALGUIEN NOS DIGA CUÁNTAS COLUMNAS TIENE LA CALLE MAYOR DE PALENCIA. TRAS VARIOS INTENTOS FALLIDOS, CRIS ES LA CHICA QUE NOS DA LA RESPUESTA CORRECTA Y SE LLEVA EL PREMIO DE CONCURSAR CON NOSOTROS. NO SUPERA LA PRIMERA Y TIENE QUE HACER LA LLAMADA A UN AMIGO SUYO QUE LE HACE GANAR LOS PRIMEROS 200 EUROS. NOS CUENTA QUE ES PLURIEMPLEADA PORQUE TIENE DOS HIJAS Y EL PADRE DE LAS NIÑAS FALLECIÓ HACE POCO, ASÍ QUE CON DOS ADOLESCENTES A SU CARGO NECESITA TRABAJAR MUCHO. LA SEGUNDA NO LA SUPERA PERO TIENE MÁS SUERTE CON LA TERCERA. -CRIS HACE HINCAPIÉ EN LA NECESIDAD DE DINERO, YA QUE LAS NIÑAS QUIEREN IR A LA UNIVERSIDAD Y MENCIONA LO QUE QUIERE ESTUDIAR CADA UNA, PERO PARA ESO SE NECESITA UN BUEN COLCHÓN ECONÓMICO. CRIS SE EMOCIONA HABLANDO DEL TEMA Y DE LO DIFÍCIL QUE ES PARA ELLA LLEVAR SOLA TODA ESA RESPONSABILIDAD, AUNQUE CUENTA CON LA AYUDA DE SUS PADRES. SUPERA LA CUARTA GRACIAS A UNA SEÑORA MAYOR Y DECIDE JUGÁRSELA. ABRIMOS LOS SOBRES, SALE EL X2 Y EL X3 Y EN EL ELEGIDO HAY NI MÁS NI MENOS QUE UN X23. CRIS SE EMOCIONA MUCHÍSIMO Y ELIGE A LA PROFESORA DE MÚSICA DE SU HIJA PEQUEÑA. LA ELEGIDA NO DUDA LA RESPUESTA NI UN MOMENTO Y DA EN EL CLAVO, AUNQUE NO CONOCÍA CUÁL ERA LA PALABRA. CRIS ROMPE A LLORAR Y XUSO TAMBIÉN, MUY EMOCIONADO PORQUE LA CONCURSANTE HAYA CONSEGUIDO ESA CANTIDAD TAN ELEVADA.', 'Leandro', '3', 'Mecánica corta 
Chica con necesidades económicas
Apertura de sobres
Final emocionante', '24:47', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (537, @jornada_id_146, '2025-06-11', 'PALENCIA', 'ROCÍO', 60, 'JUBILADA', '@rociomangas1', 481, 378, 2000, '*CUESTIONARIO MUSICAL*   TC IN: 12:34     TC OUT: 13:18  ARRANCAMOS EN UNA MESA SENTADOS COMIÉNDONOS UNOS DULCES TÍPICOS PALENTINOS Y TENEMOS UNA CAJA DE DULCES CON FORMA DE P DE PALENCIA. XUSO NOS DICE QUE DIGAMOS "PALENCIA" CON EL DULCE EN LA BOCA Y XUSO SE ROMPE UN TROZO DE DIENTE AL DARLE EL BOCADO (YA L-O TENÍA ROTO PERO ÉL QUERÍA HACERLO) NOS DA UN ATAQUE DE RISA Y A GONZALO SE LE CAE LA COMIDA DE LA BOCA Y SE TIENE QUE LEVANTAR DE LA MESA PORQUE CASI SE AHOGA. DESPUÉS DE LA MERIENDA ACCIDENTADA, NOS LEVANTAMOS PARA BUSCAR CONCUR Y OFRECEMOS DULCES A LA GENTE DE LA CALLE (CORTAR POEMA DEL SEÑOR MAYOR, ES MUY PESADO). VEMOS A UNA SEÑORA PASAR Y LE OFRECEMOS CONCURSAR, ELLA SE MUERE DE ILUSIÓN. LE HACEMOS EL CUESTIONARIO MUSICAL, SUPERA LA PRIMERA PREGUNTA Y XUSO IMITA A KIKO RIVERA CON LA ELEGIDA DURANTE EL CONCIERTO DE LA PANTOJA EN EL QUE LO SACA AL ESCENARIO (BUENÍSIMO). ROCÍO ESTÁ JUBILADA POR UN PROBLEMA DE SALUD DE LA ESPALDA PERO SIEMPRE HA TENIDO VARIOS NEGOCIOS, AUNQUE SU VIDA AHORA ES MÁS TRANQUILA. LA SEGUNDA LA SUPERA Y TAMBIÉN LA TERCERA, GRACIAS A UNA CHICA JOVENCITA QUE ENTIENDE DEL POP ACTUAL. XUSO LE DICE QUE HEMOS HABLADO DEL HIJO DE LA PANTOJA PERO NO SABE SI ELLA TIENE HIJOS Y LE RESPONDE QUE SÍ, QUE TIENE UNA VIVIENDO EN MADRID Y EL DINERO LO QUERRÍA PARA IR A VISITARLA Y DARLE CAPRICHOS. PARA LA CUARTA ELIGE A UNA SEÑORA DE 92 AÑOS Y GRACIAS A ELLA CONSIGUE EL PLENO. ROCÍO DECIDE MULTIPLICAR, LE SALE EL X2 Y ENCUENTRA A UNA CHICA QUE CREE QUE ES LA APROPIEDA. EFECTIVAMENTE, NO SABE LA RE-SPUESTA Y LA -HACE GANAR LOS 2000 EUROS.', 'Leandro', '2+', 'Mecánica corta
