INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (539, @jornada_id_147, '2025-06-12', 'VALLADOLID', 'JUDITH Y BENI', 'PUBLICISTA Y JUBILADO', '@chocochannel_', 568, 1000, 'TC IN: 9:40 TC OUT: 10:39  XUSO ARRANCA EN LA ESTATUA DE MGUEL DE CERVANTES EN LA QUE PONE QUE ES VECINO DE HONOR DE LA CIUDAD Y DICE QUE A VER SI ENCUENTRA UN VECINO QUE TENGA EL HONOR DE CONCURSAR CON ÉL. SE CRUZA CON JUDITH Y ELLA ALUCINA PORQUE LE DICE QUE VE EL PROGRAMA TODAS LAS TARDES CON SU ABUELO. XUSO LE PROPONE QUE LO LLAME PARA DECIRLE SI QUIERE CONCURSAR CON ELLA. LLAMAMOS A BENI, JUDITH LE TRANSMITE LO OCURRIDO Y ÉL DICE QUE VA PARA ALLÁ. ENTRA DIRECTAMENTE EN EL CLIP DE MICROFONADO. EMPEZAMOS EL CONCURSO Y SUPERAN LA PRIMERA PREGUNTA. XUSO LE PREGUNTA A JUDITH LOS RECUERDOS QUE TIENE DE LA INFANCIA CON SU ABUELO Y JUDITH CONFIESA: NO ES SU ABUELO DE SANGRE, SINO EL DE SU MARIDO. BENI TAMBIÉN LO EXPLICA, PERO JUDITH MATIZA TODO MEJOR SOBRE ESTE TEMA Y XUSO HACE ÉNFASIS EN QUE LA SANGRE NO ES DETERMINANTE PARA CONSIDERAR A ALGUIEN ABUELO. LA SEGUNDA LA SUPERA Y BENI NOS HABLA DE SUS TRABAJOS Y NOS E-XPLICA LA- DIFERENCIA ENTRE SER BANQUERO Y BANCARIO, QUE ES BASTANTE IMPORTANTE. JUDITH HABLA DE SUS ESTUDIOS COMO PUBLICISTA. PASAMOS A LA TERCERA Y, CASI POR SUERTE, CONSIGUE SUPERARLA. CUANDO XUSO LE PREGUNTA PARA QUÉ QUIEREN EL DINERO Y CUENTAN QUE, PARA LOS 50 AÑOS DE CASADOS DE BENI Y SU MUJER, HICIERON UN CRUCERO PARA CELEBRARLO PERO JUDITH NO ESTABA TODAVÍA EN LA FAMILIA, PERO AHORA QUIEREN HACER OTRO POR LAS BODAS DE PLATINO CON LAS NUEVAS INCORPORACIONES. XUSO LE PREGUNTA SI QUIERE MÁS AL ABUELO O LA ABUELA, Y ELA DICE QUE NO PUEDE ELEGIR. LA CUARTA NO LA SUPERAN, LLAMAN A UNA HIJA DE BENI Y LA SUPERAN. LLEGADOS ESTE PUNTO, DECIDEN PLANTARSE AUNQUE NO LES DÉ PARA CRUCERO, PERO SÍ PARA IRSE DE CENA.', 'Leandro', '3', 'Especial abuelos.
No son abuelo y nieta realmente, pero lo explican muy bien. 
Mecánica corta', '23:30', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (540, @jornada_id_147, '2025-06-12', 'VALLADOLID', 'JUDITH', 27, 'ENFERMERA', '@juudith_mu', 573, 1000, 'TC IN: 11:02    TC OUT: 11:36ARRANCAMOS EN EL PASAJE GUTIÉRREZ Y XUSO DICE QUE PARECEN LAS GALERÍAS VITTORIO EMANUELLE DE MILÁN. (NO HABÍA NADIE, ERA BELLO POR IMAGEN PERO NO PUDIMOS HABLAR CON NADIE) PASA UNA PAREJA QUE DICE QUE VA A HACER UNAS GESTIONES Y ELLA LE CUENTA QUE ES DE VALLADOLID Y ÉL DE MADRID, Y VINO AQUÍ- -POR AMOR. XUSO LES PROPONE CONCURSAR PERO ÉL LE DICE QUE NO, QUE LA ACOMPAÑA PERO QUE CONCURSE ELLA. ARRANCAMOS EL CONCURSO Y EMPEZAMOS MAL, PERO LA LLAMADA DE EMERGENCIA DE SU TÍO LA SALVA Y ACUMULA LOS PRIMEROS 200. NOS CUENTA EL TIEMPO QUE LLEVA CON SU CHICO Y SE CONOCIERON EN EL PUEBLO DE VALLADOLID DEL QUE SON LOS DOS, Y YA ÉL DECIDIÓ DEJAR 
MADRID PARA VIVIR CON ELLA EN VALLADOLID. TAMBIÉN NOS CUENTA QUE ES ENFERMERA. PASAMOS A LA SEGUNDA PREGUNTA Y PARA LA- TERCERA TENEMOS QUE HACER UNA TRANSI PORQUE TENÍAMOS UNA RADIAL AL LADO. ACUMULA LOS 600 EUROS Y NOS CUENTA QUE EL DINERO LO QUERRÍA PARA VIAJAR Y TAMBIÉN PARA PAGAR TODAS LAS BODAS QUE TIENE ESTE AÑO. PARA LA CUARTA ELIGE A UNA SEÑORA MAYOR QUE SE PIENSA QUE FERNANDO ALONSO HA NACIDO EN CANARIAS Y LUEGO DICE MALLORCA, ASÍ QUE JUDITH CONSIGUE HACER PLENO DE 1000 EUROS.- LLEGADOS A ESTE PUNTO TIENE CLARO QUE SE VA A PLANTAR Y SU CHICO ENTRA PARA COGERLA EN BRAZOS Y DARLE UN BESO. SE VAN TAN CONTENTOS CON EL DINERO.', 'Leandro', '1', 'Mecánica corta
Captación en Pasaje Gutiérrez
Nos saltamos una pregunta', '17:30', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (541, @jornada_id_147, '2025-06-12', 'VALLADOLID', 'RUBÉN', 20, 'CAMARERO', '@pumuqui_.5', 570, 318, 'X14 SG', 14000, 'TC IN:12:08   TC OUT: 12:51
 ESTAMOS EN LOS PUESTOS DEL MERCADO Y XUSO PREGUNTA DE DÓNDE SON LOS MELOCOTONES Y LE DICEN QUE DE CIEZA. LLAMA A LEANDRO A ESCENA Y ENSALZA EL MEJOR PRODUCTO QUE TIENE SU PUEBLO. COGEMOS CADA UNO UN MELOCOTÓN Y LOS PROBAMOS Y XUSO DICE QUE HOY LE AYUDARÉ A ESCOGER CONCURSANTE. -VAMOS ANDANDO Y ME FIJO EN UN CHICO CON UNA MOCHILA, LO SALUDAMOS Y ES LEANDRO EL QUE HACE LA CAPTACIÓN EXPLICÁNDOLE EL -CONCURSO Y TAL. XUSO ESTÁ DE ACUERDO Y SE LLEVAN A RUBÉN A CONCURSAR.SUPERA LA PRIMERA Y RUBÉN NOS CUENTA QUE IBA A CASA DE SU MADRE Y QUE SE DEDICA A LA HOSTELERÍA DESDE HACE CINCO AÑOS. LA SEGUNDA TAMBIÉN LA SUPERA Y LE PREGUNTAMOS POR SUS HOBBIES. NOS DICE QUE JUGABA AL FÚTBOL EN VALLADOLID, PERO UNA ROTURA LE HIZO RETIRARSE DEL CAMPO Y YA NO PUEDE HACER DEPORTE DEBIDO A LAS SECUELAS. CASUALMENTE, LA TERCERA PREGUNTA VA SOBRE DEPORTE Y EL SEÑOR AL QUE ELIGE LA SABE. -EN CUANTO AL DINERO, RUBÉN DICE QUE LO QUERRÍA PARA COMPRARSE UNA CASA CON SU CHICA Y TAMBIÉN PARA AYUDAR ECONÓMICAMENTE A SU HERMANA, YA QUE SUS PADRES ESTÁN SEPARADOS Y ELLA TIENE QUE ESTAR CONTINUAMENTE CAMBIANDO DE CASA. LLEGAMOS A LA CUARTA, HACE
PLENO Y RUBÉN DECIDE ARRIESGAR A LA PREGUNTA MULTIPLICADORA, SACANDO EL MÚLTIPLO X14. AVANZAMOS Y VE A UN SEÑOR MAYORCETE QUE TIENE CLARA LA RESPUESTA DESDE EL PRIMER MOMENTO. RUBÉN SE QUEDA ATÓNITO Y SIN PALABRAS, DICE QUE ES UN SUEÑO CUMPLIDO Y LE MANDA UN BESO EMOCIONADO A SU HERMANA MARTA, ASEGURANDO QUE ESO ES PARA ELLA TAMBIÉN.', 'Leandro', '2+', 'Mecánica corta
Arranque con Leandro ensalzando los melocotones de Cieza.', '22:39', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (542, @jornada_id_147, '2025-06-12', 'VALLADOLID', 'JULIO CÉSAR', 53, 'POLICÍA MUNICIPAL', 'FB: Julio César Gómez Lorenzo', 572, 425, 2000, 'TC IN: 13:22   TC OUT: 14:13 HACEMOS ACTING DE IMÁN DE VALLADOLID QUE TODAVÍA NO LO TENÍAMOS. VAMOS CAMINANDO Y XUSO SE CRUZA CON UN SEÑOR QUE ESTÁ PASEANDO Y DICE QUE VA A VISITAR A LOS VECINOS DEL BARRIO APROVECHANDO QUE NO ESTÁ TRABAJANDO, PUES ES POLICÍA LOCAL Y SUELE PATRULLAR POR AHÍ. XUSO LE PREGUNTA SU NOMBRE Y SE LLAMA JULIO CÉSAR, COMO EL POLÍTICO ROMANO (QUE NO EMPERADOR). JUGAREMOS TODO EL CONCURSO LA BROMA DE DEDO ARRIBA (LO SABE) Y ABAJO (NO LO SABE) COMO EN EL COLISEO. JULIO CONCURSA Y SUPERA LA PRIMERA PREGUNTA. HABLA CON ENTUSIASMO DE SU TRABAJO, LLEVA 25 AÑOS DEDICÁNDOSE A ELLO Y ESTE AÑO LO VAN A CONDECORAR POR ELLO. ADEMÁS NOS CUENTA QUE FUNDÓ E-L MUSEO DE LA POLICÍA QUE ES REFERENCIA EN CASTILLA Y LEÓN. SUPERA TAMBIÉN LA SEGUNDA Y XUSO LE -PREGUNTA POR AFICIONES Y AQUÍ ES DONDE NOS H-ABLA -DE SU GUSTO POR BUSCAR LOS ÁRBOLES GENEALÓGICOS Y QUE EL PRIMERO QUE HIZO FUE EL DE SU MADRE A MODO DE REGALO (JUSTO LO CUENTA PASANDO POR LA CATEDRAL QUE ES DONDE HACE LA BÚSQUEDA). PARA LA TERCERA COGE A UN CHICO QUE NO LA SABE Y TIENE QUE LLAMAR A UNO DE SUS PRIMOS, QUE LO AYUDA A ACUMULAR LOS 600 EUROS. EL DINERO DICE QUE LO QUIERE PARA DISFRUTAR Y VIAJAR PORQUE LA VIDA ES CORTA Y LE GUSTARÍA VOLVER A ITALIA CON SU MUJER Y SU HIJA. LA CUARTA TAMBIÉN LA SUPERA, HACEMOS PLENO Y DECIDE JUGÁRSELA, AUNQUE COGE EL MÚLTIPLO MÁS PEQUEÑO. BUSCA A UN SEÑOR TRAJEADO Y LO CONSIGUE, DANDO EN EL CLAVO Y LLEVÁNDOSE SUS 2000 EUROS.', 'Leandro', '2+', 'Mecánica corta
Compra de imán de Valladolid', '22:34', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (543, @jornada_id_148, '2025-06-13', 'MADRID', 'LADY SAVANNAH', 29, 'DRAG QUEEN', '@ladysavannahofficial', 544, 401, 'X3 SG', 3000, 'TC IN: 11:32   TC OUT: 12:28
 VAMOS POR MONTERA Y XUSO DICE QUE HOY, QUE ESTAMOS EN LA GRAN CIUDAD, QUIERE UN CONCURSANTE CHIC. SE PARA CON UNA FAMILIA EN 
UNA MESA Y UNA CHICA EXTRANJERA. DE PRONTO SE QUEDA ALUCINANDO PORQUE VE A LADY SAVANNAH Y LA LLAMA PARA HABLAR CON ELLA. 
EMPIEZA EL SHOW, ELLA SE PRESENTA Y EMPIEZA A POSAR PARA LAS CÁMARAS. XUSO, ATÓNITO, LE PROPONE CONCURSAR Y ELLA SE VUELVE LOCA, HAY 
MUCHAS RISAS. SUPERA LA PRIMERA PREGUNTA Y YA CUANDO RESUELVE LE CANTA UNA CANCIÓN DE LADY GAGA (SERÁ ALGO RECURRENTE CON 
TODOS LOS CONCURSANTES). NOS CUENTA DE DÓNDE VIENE SU NOMBRE Y TODO ES UN SHOW EN ELLA. PASAMOS A LA SEGUNDA, LA SUPERA Y VUELVE 
A CANTAR POR LADY GAGA. XUSO LE PREGUNTA QUIÉN HAY DETRÁS DE LADY SAVANNAH Y HABLA DE RUBÉN, PERO EN TERCERA PERSONA. XUSO LE 
PREGUNTA QUÉ PENSARÍA RUBÉN DE SU PARTICIPACIÓN EN EL PROGRAMA (AQUÍ IRÍA INSERTADO EL VIDEO QUE NOS MANDE RUBÉN). SUPERA 
TAMBIÉN LA TERCERA Y NOS CUENTA QUE EL DINERO LO INVERTIRÍA EN UN VIAJE A PANAMÁ PARA CONOCER A UNA PERSONA QUE ES COMO LA MADRE 
DE SU MADRE EN OTRA VIDA, UNA HISTORIA MUY RARA, SE CONOCEN DE TODA LA VIDA PERO NUNCA EN PERSONA. SUPERA LA CUARTA, SE LA JUEGA Y 
COGE EL SOBRE DEL X3. ELIGE A UNA CHICA QUE ESTÁ DE VACACIONES Y FALLA POR 100 AÑOS DE DIFERENCIA EN LA FECHA, LO QUE LA HACE GANAR 
3000 EUROS. SE VA CORRIENDO COMO UNA GACELA.', 'Leandro', '3+', 'Mecánica corta', '24:22', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (544, @jornada_id_148, '2025-06-13', 'MADRID', 'ANNA', 25, 'ACTRIZ', '@_annasantamaria', 560, 380, 'x3 SG', 1800, 'TC IN: 12:33   TC OUT: 13:36
 XUSO EMPIEZA EN UN PUESTO DE IMANES PORQUE EL IMÁN QUE COMPRÓ DE MADRID ERA UNA PAELLA Y VIRTUDES LE DIJO QUE ESO NO ERA NADA 
REPRESENTATIVO (METER ESE MOMENTO EN EL CONCURSANTE 294- ALMA PADILLA ACTING PAELLA) Y COMPRAMOS ESTA VEZ UN BOCADILLO DE 
CALAMARES. NOS ENCONTRAMOS CON UNA CHICA Y XUSO SE FIJA EN SU PINZA DEL PELO CON FORMA DE LIMÓN. ELLA IBA DE COMPRAS Y SE QUEDA 
ALUCINANDO PORQUE NO CONOCE EL PROGRAMA DE NADA Y SE CREE QUE XUSO ESTÁ GRABANDO PARA OT. ANNA ACEPTA CONCURSAR Y LA PRIMERA 
PREGUNTA NO LA SUPERA NI TAMPOCO CON AYUDA DE LA LLAMADA, PORQUE SU AMIGA NO LE COGE EL TELÉFONO. NOS CUENTA QUE ESTUDIA ARTE 
DRAMÁTICO Y ANTES VIVÍA EN BARCELONA, PERO SE VINO A MADRID A PROBAR SUERTE Y AQUÍ VA HACIENDO CASTINGS Y SUS COSILLAS. SU SUERTE 
CAMBIA Y SUPERA LA SEGUNDA Y LA TERCERA PREGUNTA TAMBIÉN. NOS CUENTA QUE, SI GANASE 50.000 EUROS, INVERTIRÍA EL DINERO EL PRODUCIR 
SU PROPIA PELÍCULA Y NOS HABLA DE SUS REFERENTES CINEMATOGRÁFICOS. SUPERA LA CUARTA Y DECIDE MULTIPLICAR, ELIGIENDO EL SOBRE DEL X3. 
ELIGE A UNA CHICA QUE ES MÉDICO Y SABE LA RESPUESTA, ASÍ QUE ANNA GANA 1800€ Y SE PONE SÚPER CONTENTA.', 'Leandro', '2+', 'Mecánica corta
Xuso compra imán más castizo que la paella que compró hace tiempo.', '19:33', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (545, @jornada_id_148, '2025-06-13', 'MADRID', 'AMANDA', 50, 'CANTAUTORA', '@amandaverdu', 561, 407, 'X5 SG', 5000, 'TC IN: 13:57   TC OUT: 14:46
 ESTAMOS EN CALLAO Y DECIMOS QUE LA BROMA DE ESTAR EN SILENCIO YA SE HA HECHO MUCHAS VECES Y ESTÁ MANIDA. DE PRONTO XUSO SE 
ENCUENTRA A UNA CHICA VESTIDA DE CHULAPA QUE VIENE DE UNA SESIÓN DE FOTOS Y LE PROPONE CONCURSAR. ANTES DE EMPEZAR YA NOS DA 
PINCELADAS DE QUE ES UNA MADRILEÑA DE PURA CEPA, AUNQUE NO ES GATA. SUPERA LA PRIMERA CON LA AYUDA DE TEO, CANTANTE DEL GRUPO 
CÓMPLICES. NOS CUENTA QUE COMPONE CHOTIS MODERNOS AUNQUE TAMBIÉN CANCIONES DE OTROS TIPOS Y DESTACAMOS SU FACETA MUSICAL. 
POR SUPUESTO, NOS CANTA SU CHOTIS "MANUELA". SUPERA TAMBIÉN LA SEGUNDA Y HABLAMOS DE LA IMPORTANCIA QUE TIENE MADRID PARA ELLA. 
SIEMPRE HA VIVIDO EN EL CENTRO, AUNQUE YA NO, Y LE TIENE UNA ESPECIE DE AMOR-ODIO PERO PONE EN VALOR LA OFERTA CULTURAL DE LA 
CAPITAL. LA TERCERA NO LA SUPERA Y LLAMA A SU MARIDO PARA QUE LE AYUDE Y LO CONSIGUE. EL DINERO LO QUIERE PARA INVERTIR EN SU MÚSICA, 
YA QUE AL SER ARTISTA INDEPENDIENTE NO LO TIENE FÁCIL EN ESE ASPECTO. SUPERA TAMBIÉN LA CUARTA Y DECIDE ARRIESGAR, ABRIMOS SU SOBRE Y 
HAY UN X5. ELIGE A UN CHICO QUE, CURIOSAMENTE, ES DE MURCIA COMO XUSO Y SABE LA RESPUESTA. AMANDA SE VA CON 5000 EUROS Y NOS 
ENSEÑA A TODOS A BAILAR EL CHOTIS.', 'Leandro', '3', 'Mecánica corta
Concursante vestida de chulapa. Equipo termina bailando el chotis.', '21:50', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (546, @jornada_id_149, '2025-06-17', 'BADALONA', 'MONTSE
MANOLI', 'BARRENDERA;
OPERARIA', '@manolipositiva
@mamidelramy', 580, 400, 'X5 SG', 5000, 'REC 16:25 - 17:21 // ARRANCAMOS EN LA PLAZA DEL AYUNTAMIENTO Y XUSO NOS CUENTA QUE ALLÁ POR LOS SESENTA, UN ZAGALICO LLAMADO MANOLO ESCOBAR LLEGÓ A BADALONA DESDE SU ALMERÍA NATAL PARA GANARSE LA VIDA COMO TANTOS ANDALUCES Y EXTREMEÑOS. TANTO LE GUSTÓ LA CIUDAD QUE VIVIÓ AQUÍ VEINTE AÑOS E HIZO SUYA LA CANCIÓN DE SERRAT "QUÉ BONITO ES BADALONA". SEGUIDAMENTE, XUSO SE ACERCA A UNA MUJER PARA PREGUNTARLE QUÉ ES LO MÁS BONITO DE BADALONA, DESPUÉS HABLA CON MANEL (OJO: ES EL CONCURSANTE #547. NO PULIR DEMASIADO SU INTERVENCIÓN), QUIEN NOS CANTA UN POQUITO DE LA CANCIÓN Y FINALMENTE SE ENCUENTRA CON MONTSE Y MANOLI. LAS CAPTAMOS Y COMENZAMOS A JUGAR. (OJO: MONTSE Y MANOLI SON MUY CAÓTICAS. PIDO DISCULPAS DE ANTEMANO. LES DIJIMOS VARIAS VECES QUE FUERAN CON CALMA, PERO DE LA EMOCIÓN NO ESCUCHABAN Y SE ABALANZABAN SOBRE LOS ELEGIDOS. DURANTE EL PRIMER PASEO Y TRAS VARIOS MOMENTOS DE CAOS, RETOMAMOS EN "MANOLI, QUE ME ASUSTAS A LA GENTE" POR CORTE). SUPERAN LA PRIMERA PREGUNTA Y NOS CUENTAN QUE ESTÁN CASADAS CON DOS HERMANOS Y QUE, A SU VEZ, SU PRIMA TAMBIÉN ESTÁ CASADA CON EL TERCER HERMANO. TAMBIÉN NOS CUENTAN QUE AMBAS TIENEN HIJOS Y NIETOS, Y DESCUBRIMOS QUE AL PRINCIPIO MANOLI SE FIJÓ EN EL MARIDO DE SU HERMANA, PERO SE ENAMORÓ DEL OTRO HERMANO. SUPERAN LA SEGUNDA PREGUNTA Y COMO YA HEMOS VISTO QUE SON UN TORBELLINO, XUSO LES PREGUNTA QUIÉN ES LA MAYOR Y NOS CUENTAN QUE HAY UNA TERCERA HERMANA, MERCEDES. ADEMÁS, MONTSE NOS CUENTA QUE MANOLI ES "LA GUARRA", PERO PORQUE DICE MUCHAS PALABROTAS. SUPERAN LA TERCERA PREGUNTA Y MANOLI CONFIESA QUE CON EL DINERO LE GUSTARÍA PONERSE DOS MUELAS Y UN TOLDO EN EL BALCÓN; Y MONTSE LO GASTARÍA CON SU FAMILIA. EN LA CUARTA PREGUNTA, LA ELEGIDA ACIERTA Y VAMOS A LA LLAMADA DE LA EMERGENCIA. DECIDEN LLAMAR A LA HIJA DE MANOLI, QUIEN NO ACIERTA Y 
SUPERAN LA CUARTA PREGUNTA. FINALMENTE, DECIDEN JUGAR Y SUPERAN LA QUINTA PREGUNTA.', 'Cristina', '2+', 'Mecaníca corta
En boca de 
Arranque mención Manolo Escobar y la canción "Qué bonito es Badalona". 
¡OJO! El primer hombre que para Xuso, MANEL, será el concursante 547', '24:12', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (547, @jornada_id_149, '2025-06-17', 'BADALONA', 'MANEL', 57, 'PESCATERO', 'NO TIENE', 586, 427, 'X2 SG', 2000, 'REC 17:40 - 18:21 // ARRANCAMOS EN LA CALLE DEL MAR Y XUSO NOS CUENTA QUE ANTES HA CONOCIDO A MANEL, UN HOMBRE QUE VIMOS EN OTRO 
PROGRAMA (CONCURSANTES #546), Y QUE NOS CANTÓ LA CANCIÓN "QUÉ BONITO ES BADALONA", ASÍ QUE NO PODÍAMOS DEJARLO ESCAPAR. 
SEGUIDAMENTE, ENTRA MANEL Y MICROFONAMOS. SUPERA LA PRIMERA PREGUNTA Y NOS CUENTA QUE ES PESCATERO DESDE HACE MÁS DE 30 AÑOS 
EN EL MERCADO DE LA SALUT. ADEMÁS, NOS EXPLICA QUE LOS MEJORES MESES PARA COMPRAR PESCADO AZUL SON MAYO, JUNIO Y JULIO; Y QUE LA 
MEJOR ÉPOCA PARA COMPRAR MARISCO SON LOS MESES FRÍOS. SUPERA LA SEGUNDA PREGUNTA Y VAMOS DIRECTOS A LA TERCERA. (DURANTE EL 
PASEO, MANEL HACE REFERENCIA AL CARRER DEL MAR Y ROBER GRABA RECURSOS DEL CARTEL CARACTERÍSTICO DEL CARRER DEL MAR). SUPERA LA 
TERCERA PREGUNTA Y NOS CUENTA QUE LE GUSTARÍA DONAR EL DINERO AL HOSPITAL DE CAN RUTI DE BADALONA, CONCRETAMENTE AL SERVICIO DE 
ONCOLOGÍA. (¡OJO!: CUANDO GIRAMOS HACIA EL PASEO MARÍTIMO, PASAMOS JUSTO AL LADO DE MONTSE Y MANOLI (CONCURSANTES #546) QUE 
ESTABAN SENTADAS EN UNA TERRAZA. INTENTAR EVITAR QUE APAREZCAN). SUPERA LA CUARTA PREGUNTA, DECIDE JUGAR Y ABRIMOS LOS SOBRES. 
EN LA QUINTA PREGUNTA, ELIGE A UNA AUSTRALIANA QUE HABLABA PERFECTAMENTE EL ESPAÑOL Y GANA 2.000 EUROS.', 'Cristina', '2', 'Mecánica corta
¡OJO! Manel apareció en el concurso de  las 546, se hace mención, pero NO TIENE QUE IR unido a ellas en programa.', '21:07', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (548, @jornada_id_149, '2025-06-17', 'BADALONA', 'MIGUEL
Mª CARMEN', 'INFORMÁTICO
JUBILADA', '@miguel1zquierdo', 587, 359, 'X2 SG', 800, 'REC 18:58 - 20:06 // ARRANCAMOS EN EL PASEO MARÍTIMO Y XUSO NOS CUENTA QUE ESTAMOS EN LA TIERRA DE MIREIA BELMONTE, LA PRIMERA NADADORA ESPAÑOLA EN CONSEGUIR EL ORO OLÍMPICO Y LA DEPORTISTA EN ACTIVO CON MÁS MEDALLAS OLÍMPICAS. SEGUIDAMENTE, DECIDE PREGUNTARLE A LA GENTE SI SON MÁS DE PLAYA O DE PISCINA. PARAMOS A UN PAR DE PERSONAS HASTA QUE NOS ENCONTRAMOS CON MIGUEL Y MARI, Y LOS CAPTAMOS. SUPERAN LA PRIMERA PREGUNTA Y AHONDAMOS EN SU BUENA RELACIÓN. NOS CUENTAN QUE VIVEN JUNTOS Y QUE SE LLEVAN LA MAR DE BIEN PORQUE MARI ES UNA ABUELA MUY MODERNA, A LA QUE NO LE GUSTA NI ESTAR CON GENTE MAYOR NI HACER COSAS DE ANCIANA. MARI NOS CUENTA QUE LE ENCANTA LA AMY WINEHOUSE, SANTANA, MANU CARRASCO, ETC. Y QUE ADEMÁS, BAILA SEVILLAS. XUSO PIDE A LOS EDITORES QUE LE PONGAN MÚSICA (CANCIÓN: MÍRALA CARA A CARA DE LOS REQUIEBROS) Y BAILA UNAS SEVILLANAS CON MARI. DESPUÉS, MARI NOS DICE QUE TAMBIÉN HACE ZUMBA, ASÍ QUE LA ABUELA, EL NIETO Y XUSO SE MARCAN UNOS PASITOS DE ZUMBA. SUPERAN LA SEGUNDA PREGUNTA Y MIGUEL NOS CUENTA QUE ES INFORMÁTICO Y MARI, QUE ESTÁ JUBILADA, PERO QUE TRABAJABA EN EL AYUNTAMIENTO (RECORTAR LA DESCRIPCIÓN DEL TRABAJO DE MARI HASTA QUE RETOMAMOS EN LA MATERNIDAD). MARI EXPLICA QUE COMPAGINABA EL TRABAJO CON LA CRIANZA DE TRES HIJOS Y QUE EL PRIMERO LO TUVO CON 17 AÑITOS, ASÍ QUE AHORA QUIERE DISFRUTAR DE LA VIDA Y VIAJAR. XUSO LE PREGUNTA SI EN ESTOS VIAJES HA CONOCIDO A ALGUIEN ESPECIAL Y MARI CONFIESA QUE ELLA QUIERE UN MULATO, NO UN SEÑOR MAYOR, ASÍ QUE XUSO LE ANIMA A PEDIR A CÁMARA CÓMO LE GUSTARÍA QUE FUESE SU PAREJA IDEAL ("MORENO, ALTO, GUAPO, QUE TENGA DINERO, COMO DENZEL WASHINGTON"). EN LA TERCERA PREGUNTA, LA CHICA ELEGIDA NO SABE LA RESPUESTA Y MIGUEL DECIDE LLAMAR A UN AMIGO, QUIEN TAMPOCO ACIERTA. NO SUPERAN LA TERCERA PREGUNTA Y MIGUEL DICE QUE CON EL DINERO LE GUSTARÍA INDEPENDIZARSE Y VIAJAR CON SU ABUELA. NO SUPERAN LA CUARTA PREGUNTA Y DECIDEN JUGAR. EN LA QUINTA PREGUNTA, EL ELEGIDO ACIERTA Y SE LLEVAN 800 EUROS. GRABAMOS DESPEDIDA CONCURSANTES Y DESPEDIDA DEL VERANO (ESTA ÚLTIMA, LA REPETIMOS DOS VECES. PARA MÍ, LA BUENA ES LA SEGUNDA).', 'Cristina', '2+', 'Mecánica corta
ESPECIAL ABUELOS', '30:23', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (549, @jornada_id_149, '2025-06-17', 'BADALONA', 'WILLIAM', 19, 'ASESOR ENERGÉTICO', '@wiilliamclark', 583, 436, 'X4 SG', 4000, 'REC 20:42 - 21:24 // ARRANCAMOS EN EL PASEO MARÍTIMO DE BADALONA, JUSTO AL LADO DEL PONT DEL PETROLI, PERO CON XUSO DICIENDO QUE ESTÁ EN SANTA MÓNICA. NOS CUENTA QUE AQUÍ SE HAN RODADO GRANDES PELÍCULAS COMO "FORREST GUMP" Y "HANNAH MONTANA". XUSO DECIDE HABLAR CON UNAS CHICAS CON LOOK DEPORTIVO EN INGLÉS Y SEGUIDAMENTE, SE CRUZA CON UN CHICO CON UN LOOK MUY WEST COAST QUE VA MONTADO EN MONOPATÍN. BROMEA CON L Y SE MONTA EN SU MONOPATÍN. FINALMENTE, SE CRUZA CON WILLIAM, QUIEN LE RESPONDE EN 
UN PERFECTO INGLÉS Y TRAS INTENTAR EXPLICARLE EL PROGRAMA EN INGLÉS, LO CAPTAMOS. SUPERA LA PRIMERA PREGUNTA Y NOS CUENTA QUE SU PADRE ES ESCOCÉS Y SU MADRE GUINEANA. SUS PADRES SE CONOCIERON HACE 25 AÑOS EN UNA DISCOTECA Y DE ESA MEZCLA TAN CURIOSA NACIÓ ÉL. SUPERA LA SEGUNDA PREGUNTA Y LA TERCERA PREGUNTA. TRAS LA TERCERA, NOS CUENTA BREVEMENTE QUE ES ASESOR ENERGÉTICO Y QUE CON EL DINERO LE GUSTARÍA PEGARSE UN BUEN VIAJE Y COMPRARSE UN COCHE. SUPERA LA CUARTA PREGUNTA Y DECIDE JUGAR. SUPERA LA QUINTA PREGUNTA Y SE LLEVA 4.000 EUROS.', 'Cristina', '2+', 'Mecánica corta', '23:05', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (550, @jornada_id_150, '2025-06-18', 'BARCELONA', 'HÉCTOR
MARI CARMEN', 'REALIZADOR;
INFLUENCER', '@hectorprva
@la.yaya.maricarmen', 577, 389, 'X4 SG', 4000, 'REC 16:04 (Presentación especial ) - 17:58 (Fin concurso) // GRABAMOS LA ENTRADILLA DEL "ESPECIAL ABUELOS" Y LLAMAMOS A HÉCTOR. GRABAMOS RECURSOS DE ROSA PENDIENTE DE 
LA LLEGADA DEL NIETO Y DE LA ABUELA Y CUANDO YA SE ESTABAN ACERCANDO DE VERDAD, GRABAMOS A ROSA AVISÁNDONOS Y A XUSO, MUY NERVIOSO, ESCONDIDO DETRÁS DE UNA 
COLUMNA. CUANDO LA ABUELA Y EL NIETO ESTÁN GIRANDO LA ESQUINA, SALIMOS A SU ENCUENTRO Y LA YAYA REACCIONA CON MUCHÍSIMA EMOCIÓN. LE DA INFINITOS BESOS Y 
ABRAZOS A XUSO, Y TRAS VARIAS BROMAS, LOS CAPTAMOS. SUPERAN LA PRIMERA PREGUNTA Y XUSO LE PREGUNTA A LA YAYA CÓMO LLEVA LA FAMA Y ESTO DE SER UNA INFLUENCER. 
ENTRE MEDIAS, BROMEAMOS CON EMILIO PORQUE A LA YAYA LE PARECE MUY ATRACTIVO Y LE PEDIMOS A NUESTRO COMPAÑERO QUE LE AJUSTE EL MICRÓFONO A LA YAYA, PORQUE 
ESTA QUIERE ROZARSE UN POCO CON ÉL SUPERAN LA SEGUNDA PREGUNTA, Y COMO ESTÁBAMOS HABLANDO DE PELEAS DE ARRIBA, AHONDAMOS EN SU RELACIÓN. LA YAYA NOS 
CUENTA QUE SE ADORAN, PERO QUE PELEAN MUCHO COMO EN TODAS LAS FAMILIAS, AUNQUE PARA ELLA SU NIETO ES LO MÁS IMPORTANTE DEL MUNDO. EL NIETO NOS CUENTA QUE 
ENTRE ELLOS NO HAY SECRETOS Y QUE ÉL LE CUENTA TODO SOBRE SUS LIGUES (OJO: CORTAR CUANDO LA ABUELA CUENTA QUE TIENE MIEDO QUE EL HIJO CONTRAIGA ALGUNA ITS, QUE 
DEBE TOMAR PRECAUCIONES, CUIDARSE, ETC.). EN LA TERCERA PREGUNTA, SE FIJAN EN TRES CHICOS DEPORTISTAS MUY SIMPÁTICOS. PARA DECIDIR CON CUÁL SE QUEDAN, LA YAYA LE 
TOCA EL BÍCEPS A LOS TRES PARA VER CUÁL ESTÁ MÁS FUERTE. SUPERAN LA TERCERA PREGUNTA Y NOS CUENTAN QUE CON EL DINERO VIAJARÍAN A ITALIA (CORTAR TODO LA 
EXPLICACIÓN POSTERIOR DE LA YAYA Y RETOMAMOS CUANDO XUSO DICE "Y TÚ HÉCTOR QUÉ HARÍAS..."?). MIENTRAS BROMÉABAMOS, EL NIETO DEJA CAER QUE A SU ABUELA LE PASÓ 
ALGO EN UN RÍO Y LE PEDIMOS QUE NOS LO EXPLIQUE, Y RESULTA QUE LA YAYA SE QUEDÓ EMBARAZADA DE LA MADRE DE HÉCTOR MIENTRAS HACÍA EL AMOR EN UN RÍO PORQUE ELLA 
PENSABA QUE EL AGUA SE LO LLEVABA TODO. SUPERAN LA CUARTA PREGUNTA Y DECIDEN JUGAR. EN LA QUINTA, ELIGEN A UN HOMBRE QUE ACIERTA Y CON TANTA ALEGRÍA, LA YAYA 
APROVECHA PARA TONTEAR CON EL ELEGIDO Y QUEDAN PARA TOMAR UN CAFÉ OTRO DÍA. FINALMENTE, CELEBRAMOS LOS 4.000 EUROS CON TODO EL EQUIPO Y NOS MARCHAMOS CON 
ELLOS.', 'Cristina', '3+', 'Mecánica corta
PRESENTACIÓN "ESPECIAL ABUELOS"', '34:34', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (551, @jornada_id_150, '2025-06-18', 'BARCELONA', 'MARINA', 24, 'MAQUILLADORA', '@m.wildness', 574, 304, 'X3 SP', 0, 'REC 18:19 - 19:19* (El bruto es largo porque hubo muchos elegidos que no quisieron participar, pero es breve de contenido). 
ARRANCAMOS CON XUSO - REPORTERO PREGUNTANDO A LOS MIEMBROS DEL EQUIPO QUÉ ES LO MEJOR QUE LES HA PASADO HOY. PRIMERO HABLA CON ROSA, JUANJO, CRISTINA, UN SEÑOR MUY SIMPÁTICO Y FINALMENTE, SE ENCUENTRA CON MARINA, UNA CHICA JOVEN, TATUADA Y CON MUCHA GRACIA, ASÍ QUE LA CAPTAMOS Y ARRANCAMOS EL CONCURSO. SUPERA LA PRIMERA PREGUNTA Y XUSO SE FIJA EN SUS TATUAJES. NOS EXPLICA QUE SU TATUAJE FAVORITO ES EL DEL BRAZO, EN HOMENAJE A SU ABUELO FALLECIDO. (OJO: EN LA SEGUNDA PREGUNTA, EL ELEGIDO CONTESTA "NO SÉ" Y SE MARCHA EN LA MITAD DE LA RESOLUCIÓN. REPETIMOS LA RESOLUCIÓN PORQUE XUSO NO HABÍA DADO LA RESPUESTA Y ASÍ SALVAMOS LA FUGA DEL ELEGIDO). SUPERA LA SEGUNDA PREGUNTA Y VAMOS DIRECTOS A LA TERCERA, Y TAMBIÉN LA SUPERA. EN LA CUARTA PREGUNTA, ELIGE A UN CHICO BRASILEÑO QUE ACIERTA Y MARINA DECIDE LLAMAR A SU ABUELA, QUIEN TAMBIÉN ACIERTA. CON 600 EUROS ACUMULADOS, SE ARRIESGA Y TRAS VARIOS ELEGIDOS QUE NO QUERÍAN CONCURSAR, ELIGE A UN HOMBRE Y REPETIMOS CAPTACIÓN PARA QUE NO APAREZCA SU ACOMPAÑANTE. EL ELEGIDO ACIERTA Y MARINA SE MARCHA CON LA CAMISETA.', 'Cristina', '1+', 'Mecánica corta
Xuso reportero
Nos saltamos una pregunta.
Candidata Segunda Oportunidad.', '21:25', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (552, @jornada_id_150, '2025-06-18', 'BARCELONA', 'CHRISTIAN', 39, 'PROFESOR', '@christianbcn1', 588, 350, 'X3 SP', 0, 'REC 20:08 - 20:57 // XUSO NOS CUENTA QUE ESTAMOS EN LA RAMBLA DEL POBLENOU, UNO DE LOS DISTRITOS MÁS MODERNOS Y A LA VEZ, CON ALMA DE PUEBLO, DE BARCELONA. MIENTRAS HABLA, NOS FIJAMOS EN CHRISTIAN, QUE ESTÁ GRABANDO AL EQUIPO CON EL MÓVIL (*LE HEMOS PEDIDO ESE VÍDEO*). XUSO LO LLAMA Y LE PRESENTA A TODOS LOS MIEMBROS DEL EQUIPO. CHRISTIAN CUENTA QUE ES FAN DEL CONCURSO DESDE QUE LO PRESENTABA JUANRA Y QUE SU SUEÑO SERÍA PARTICIPAR, ASÍ QUE LO CAPTAMOS Y ARRANCAMOS. SUPERA LA PRIMERA PREGUNTA Y NOS EXPLICA QUE SE DEDICA A LA ENSEÑANZA Y QUE ES PADRE MONOPARENTAL DE UN NIÑO QUE SE LLAMA ALAN, A QUIEN ADOPTÓ CUANDO SU SOBRINA SE QUEDÓ EMBARAZADA SIENDO ELLA MENOR. EL SEGUNDO ELEGIDO ES UN CHICO MUY JOVEN QUE ACIERTA LA PREGUNTA Y CHRISTIAN DECIDE LLAMAR A SU HERMANA. SUPERA LA SEGUNDA PREGUNTA, VAMOS DIRECTOS A LA TERCERA Y TAMBIÉN LA SUPERA. EN CASO DE GANAR LOS 50.000 EUROS, NOS DICE QUE LE GUSTARÍA HACER UN SAFARI. SUPERA LA CUARTA PREGUNTA Y DECIDE JUGAR. ELIGE A UN CAMARERO DE UNOS 50 AÑOS, PERO NO SABÍA LA RESPUESTA Y CHRISTIAN SE MARCHA CON LA CAMISETA DEL CLUB DE LOS PERDEDORES.', 'Cristina', '2', 'Mecánica corta
Nos saltamos una pregunta.', '21:00', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (553, @jornada_id_150, '2025-06-18', 'BARCELONA', 'MONTSERRAT', 49, 'ADMINISTRATIVA', '@mllortiz', 502, 439, 'X6 SP', 0, '*CUESTIONARIO MUSICAL* // REC 21:15 - 22:07 // 
XUSO COMIENZA CANTANDO "ELLA TIENE PODER, ELLA TIENE PODER. BARCELONA ES PODEROSA, BARCELONA TIENE PODER". NOS CUENTA QUE ESTAMOS EN BARCELONA Y QUE AQUÍ NACIÓ LA RUMBA CATALANA, ASÍ QUE QUIERE ENCONTRAR ALGUIEN CON ARTE. SE ACERCA A UNA SEÑORA PARA QUE SIGA LA CANCIÓN DE PERET Y DESPUÉS, SE ACERCA A MONTSE Y LA CAPTAMOS. NO SUPERA LA PRIMERA PREGUNTA Y DECIDE LLAMAR A SU CUÑADA, QUIEN TAMPOCO ACIERTA. ASÍ QUE, PARA REMONTAR LOS ÁNIMOS, VAMOS DIRECTOS A LA SEGUNDA PREGUNTA. SUPERA LA SEGUNDA PREGUNTA Y NOS CUENTA QUE TIENE DOS HIJOS Y QUE TRABAJA COMO ADMINISTRATIVA. SUPERA LA TERCERA PREGUNTA Y, EN CASO DE GANAR 30.000 EUROS, SE IRÍA TRES SEMANITAS DE VIAJE CON SU FAMILIA. SUPERA LA CUARTA PREGUNTA Y DECIDE JUGAR. EN LA QUINTA, ELIGE A UN HOMBRE ARGENTINO, PERO NO SABE LA RESPUESTA Y MONTSERRAT SE MARCHA CON LA CAMISETA.', 'Cristina', '1', 'Mecánica corta
Cuestionario musical
Nos saltamos una pregunta.
Anochece', '19:38', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion) VALUES (554, @jornada_id_151, '2025-06-19', 'CORNELLÀ', 'CRISTIAN', 39, 'VENDEDOR', '@cristian_112345', 575, 133, 'X2 SP', 0, '*ACTING - BAR DE LA PATATA//: ARRANCAMOS FRENTE AL BAR DE LA PATATA Y XUSO NOS CUENTA QUE ÓLIVER (CONCURSANTE #555) LE HA RECOMENDADO ESTE SITIO PARA COMER. ENTRAMOS EN EL BAR, XUSO SALUDA A LOS TRABAJADORES Y TOMA ASIENTO JUNTO A CHETE, JUANJO Y CRISTINA. EL DUEÑO DEL BAR, BONI, NOS TRAE UNA RACIÓN PATATAS Y XUSO LE PREGUNTA QUÉ LLEVA LA FAMOSA SALSA SECRETA DE LAS PATATAS, PERO EL DUEÑO SE NIEGA A DARLE LA RECETA. BROMEAN, PROBAMOS LAS PATATAS Y NOS MARCHAMOS. 
REC 11:31 - 12:17 // ARRANCAMOS EN EL MERCADILLO DE SAN ILDEFONSO CON XUSO MIRANDO UNOS TRAPITOS PARA VIRTUDES. INTERACTÚA CON UN PAR DE COMPRADORES Y COMERCIANTES, Y VAMOS BAJANDO HASTA LLEGAR A LA PARADA DE CRISTIAN, UN CHICO MUY SIMPÁTICO QUE VENDE FELPUDOS. XUSO SE FIJA EN UN FELPUDO CON LA GARA DE UN GATO E INTERCAMBIAN UN PAR DE BROMAS. CAPTAMOS A CRISTIAN Y MICRFONAMOS. EN LA PRIMERA PREGUNTA, ELIGE A UN SEÑOR QUE LLEVA GAFAS, PERO NO LE SALE LA PALABRA "PATILLAS" Y NOS VAMOS A LA LLAMADA DE EMERGENCIA. CRISTIAN LLAMA A SU MADRE, QUIEN SÍ SABE LA RESPUESTA Y SUPERA LA PRIMERA PREGUNTA. NOS CUENTA QUE SIEMPRE HA SIDO VENDEDOR AMBULANTE Y QUE SE SUELE MOVER POR LOS PUEBLOS DE LA ZONA DEL BAIX LLOBREGAT. SUPERA LA SEGUNDA PREGUNTA Y XUSO BAILA LA HAKA DE LOS ALL BLACKS CON EL ELEGIDO, UN SEÑOR MAYOR. VAMOS DIRECTOS A LA TERCERA Y TAMBIÉN LA SUPERA. EN CASO DE GANAR LOS 50.000 EUROS, LE GUSTARÍA QUITARSE LA HIPOTECA DE ENCIMA Y DARLE UNA BUENA VIDA A SUS DOS HIJAS PEQUEÑAS. DECIDE ARRIESGARSE A LA QUINTA PREGUNTA, Y ELIGE A UN SEÑOR CON LOOK DEPORTIVO, PERO QUE NO SABÍA NADA DE FÚTBOL, ASÍ QUE CRISTIAN SE MARCHA CON LA CAMISETA DEL PROGRAMA.', 'Cristina', '1+', 'Acting bar La Patata, al que van porque Óliver (concursante 555) se lo ha recomendado. 
Nos saltamos una pregunta.', '24:04');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (555, @jornada_id_151, '2025-06-19', 'CORNELLÀ', 'ÓLIVER', 41, 'CONDUCTOR', '@oliverrolop', 424, 600, '*CUESTIONARIO MUSICAL* // REC 12:52 - 13:23
 *PROPUESTA LOCALIZADOR: PONER "ALLENROCK" (PORQUE SIGNIFICA CORNELLÀ AL REVÉS Y ES EL TÍTULO DE UN ÁLBUM DE ESTOPA), Y QUE LUEGO SE REORDENEN LAS LETRAS Y PODAMOS LEER "KORNELLÀ". ARRANCAMOS CON XUSO JUNTO A LA ESTATUA DE LOS ESTOPA PORQUE EN CORNELLÀ ESTOS DOS HERMANOS ESTÁN CONSIDERADOS PATRIMONIO NACIONAL. Y PARA DEMOSTRAR QUE TODO EL MUNDO SE CONOCE LAS CANCIONES DE ESTOPA, SACA A CHETE Y COMIENZA A CANTAR "TU CALORRO". DESPUÉS, XUSO PARA A UNA CHICA PARA QUE CANTA "LA RAJA DE TU FALDA" Y FINALMENTE, SE ENCUENTRA A ÓLIVER Y CANTAN "COMO CAMARÓN". LO CAPTAMOS Y MICROFONAMOS. SUPERA LA PRIMERA PREGUNTA Y NOS CUENTA QUE SIEMPRE HA SIDO CONDUCTOR DE AUTOBUSES EN EMPRESAS PRIVADAS Y QUE AHORA TRABAJA PARA LOS TRANSPORTES METROPOLITANOS DE BARCELONA. SUPERA LA SEGUNDA PREGUNTA Y VAMOS DIRECTOS A LA TERCERA. EN LA TERCERA, LA ELEGIDA NO SUPERA LA PREGUNTA Y ÓLIVER DECIDE LLAMAR A SONIA, SU COMPAÑERA DE TRABAJO, QUIEN NO DUDA Y RESPONDE "EL LANGUI". TRAS SUPERAR LA TERCERA PREGUNTA, NOS CUENTA QUE EN SU CASA HACE MUCHA FALTA EL DINERO PORQUE TIENE UNA HERMANA CON PARÁLISIS CEREBRAL Y TODA AYUDA ES POCA. EN LA CUARTA PREGUNTA ELIGE A UN SEÑOR QUE HABÍA VIVIDO EN ACAPULCO, ASÍ QUE SE PLANTA CON 600 EUROS. ANTES DE ACABAR, LE RECOMIENDA A XUSO QUE SE PASE POR EL BAR DE LA PATATA PORQUE LOS DUEÑOS SON SUS AMIGOS DE TODA LA VIDA.', 'Cristina', '2+', 'Cuestionario musical. 
Arranque canciones de Estopa. 
Nos quitamos una pregunta.', '21:45', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (556, @jornada_id_151, '2025-06-19', 'CORNELLÀ', 'MARISOL', 55, 'PELUQUERA', '@marisol.brosses', 581, 446, 'X4 SG', 2400, 'REC 14:15 - 15:08 // ARRANCAMOS CON XUSO CAMINANDO POR LA CALLE Y SE PARA A HABLAR CON UNA SEÑORA QUE VA CONDUCIENDO. SEGUIDAMENTE, SE DESPIDE DE ELLA Y ESCUCHA UNA MÚSICA MUY FUERTE QUE VIENE DEL LOCAL DE AL LADO. EMILIO DICE QUE NO PODEMOS GRABAR CON TANTA MÚSICA Y XUSO DECIDE ENTRAR EN LA PELUQUERÍA. UNA VEZ DENTRO, SE ENCUENTRA CON MARISOL QUE ESTÁ PINCHANDO MÚSICA MIENTRAS LAS CLIENTAS SE ARREGLAN EL PELO. XUSO HABLA CON ELLA Y LA CAPTAMOS, PERO ANTES MONTAN UNA FIESTA EN LA PELUQUERÍA, SE PONE A BAILAR CON LAS CLIENTAS Y HACEN UNA CONGA. (OJO: COMENZAMOS EN LA CALLE, PERO HABÍA MUCHO RUIDO ASÍ QUE NOS DESPLAZAMOS HASTA LA PLAZA Y VOLVEMOS A EMPEZAR). SUPERA LA PRIMERA PREGUNTA Y NOS CUENTA QUE ES PELUQUERA Y DJ PORQUE YA ESTÁ EMPEZANDO A PINCHAR EN FIESTAS EN CORNELLÀ Y EN FIESTAS PRIVADAS, Y QUE SU SUEÑO ES ACABAR PINCHANDO EN IBIZA. SUPERA LA SEGUNDA PREGUNTA Y VAMOS DIRECTOS A LA TERCERA. EL ELEGIDO NO LA SUPERA Y DECIDE LLAMAR A UN AMIGO DE SU HIJA QUE CUIDA MUCHO SU ALIMENTACIÓN, PERO TAMPOCO SABE LA RESPUESTA. EN CASO DE LLEVARSE 30.000 EUROS, LE GUSTARÍA SEGUIR AMPLIANDO SU EQUIPO DE MÚSICA PORQUE EL MATERIAL ES MUY CARO. SUPERA LA CUARTA PREGUNTA Y DECIDE JUGAR. PARA LA QUINTA, ELIGE A UN CHICO JOVEN CON ROPA DEPORTIVA QUE ACIERTA SIN DUDAR Y MARISOL SE LLEVA 2.400 EUROS.', 'Cristina', '2+', 'Arranque en peluquería con DJ. 
Nos quitamos una pregunta.', '22:30', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (557, @jornada_id_151, '2025-06-19', 'CORNELLÀ', 'NOELIA', 30, 'MAESTRA', '@noelia_gazquez', 537, 388, 'X3 SG', 3000, '*REC CONCURSANTE NOELIA 17:15 - 18:05//: ESTAMOS EN LA RAMBLA DE CORNELLÀ CON XUSO ENSEÑANDO EL PAÑUELO DE LAS FIESTAS DE CORNELLÀ Y COMENTANDO QUE TIENE LA BARRIGA LLENA DESPUÉS DE LAS PATATAS. XUSO SALUDA A UNA SEÑORA LLAMADA PEPI QUE RESULTA SER ENCANTADORA Y LE DECIMOS QUE SE QUEDE CON NOSOTROS PARA QUE ELIJA A LA SIGUIENTE CONCURSANTE. CAPTAMOS A NOELIA Y MICROFONAMOS. SUPERA LA PRIMERA PREGUNTA Y NOS CUENTA QUE LLEVA 15 AÑOS CON SU PAREJA Y QUE TIENEN UNA HIJA DE CUATRO MESES. ADEMÁS,  SE ACABA DE INCORPORAR AL TRABAJO COMO PROFESORA TRAS LA BAJA MATERNAL. SUPERA LA SEGUNDA PREGUNTA Y VOLVEMOS A CELEBRARLO CON PEPI. VAMOS DIRECTOS A LA TERCERA, PERO LA ELEGIDA NO SABE LA RESPUESTA Y NOELIA DECIDE LLAMAR A ALEJANDRO, SU PAREJA, Y ÉL SÍ SABÍA EL NOMBRE DE LA INFLUENCER "RORO". NOELIA NOS CUENTA QUE DESTINARÍA EL DINERO PARA LA VIVIENDA (CORTAR CUANDO HABLA SOBRE EL PRECIO DE LA VIVIENDA EN SITGES E INCLUSO CUANDO NOS HABLA SOBRE EL CARNAVAL SI TIENE BUEN CORTE). SUPERA LA CUARTA PREGUNTA Y DECIDE JUGAR. ELIGE A UNA CHICA QUE ES PROFESORA Y SE LLEVA LOS 4.000 EUROS.', 'Cristina', '3-', 'La señora Pepi ayuda a Xuso a elegir y les  acompaña durante el concurso. 
Nos quitamos una pregunta.', '22:00', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (558, @jornada_id_152, '2025-06-20', 'EL PRAT', 'VICKY', 60, 'EMPLEADA DEL HOGAR', 'NO TIENE', 584, 449, 'X2 SG', 1200, 'REC 9:45 - 10:36 // ARRANCAMOS FRENTE AL MERCADO MUNICIPAL DE LA VILA DEL PRAT Y XUSO NOS CUENTA QUE NO HAY NADA MÁS DEL PRAT QUE EL POTABLAVA, EL POLLO CATALÁN MÁS CHULO DEL CORRAL. ES UNA RAZA DE POLLO AUTÓCTONA Y SE LLAMA ASÍ POR EL AZUL DE SUS PATAS PORQUE "POTABLAVA" SIGNIFICA "PATA AZUL" EN CATALÁN. ENTRAMOS EN EL MERCADO Y XUSO SALUDA A COMERCIANTES Y VENDEDORES. (CORTAR A LA PRIMERA SEÑORA QUE DICE QUE EL POLLO SE COME EN NAVIDAD). SEGUIDAMENTE, XUSO SALUDA A UNAS PESCATERAS CON MUCHO ARTE QUE CANTAN "EL PANTALÓN" DE OMAR MONTES (CORTAR TODA LA PARTE POSTERIOR EN LA QUE XUSO LES DICE QUE VOLVERÁ A POR ELLAS, NOS QUEDAMOS ÚNICAMENTE CON EL SALUDO, LAS BROMAS Y LA CANCIÓN). XUSO SIGUE ANDANDO Y SE PARA EN LA FRUTERÍA, BROMEA CON LOS CHORROS DE VAPOR DE AGUA QUE RIEGAN LAS VERDURAS Y ENTABLA CONVERSACIÓN CON VICKY, QUE ESTÁ COMPRANDO VERDURAS PARA HACER ESCALIVADA. LA CAPTAMOS Y ARRANCAMOS. SUPERA LA PRIMERA PREGUNTA Y NOS CUENTA QUE ES "INVESTIGADORA DE MANCHAS", QUE ES UNA FORMA SOFISTICADA DE DECIR "EMPLEADA DEL HOGAR". EXPLICA QUE EN CUANTO VE UNA MANCHA YA SABE DE QUÉ ES Y QUE ESTÁ MUY ORGULLOSA DE SU TRABAJO, YA QUE A VECES ESTÁ DENOSTADO SOCIALMENTE. [GRAFISMO: XUSO PIDE A LOS GRAFISTAS QUE LE HAGAN A VICKY UN PERFIL POLICIAL COMO SI FUESE UNA INVESTIGADORA DEL CSI (CLIPS 5957, 5958 Y 5959). // PROPUESTA DE TEXTO: NOMBRE: VICKY "LA PULCRA" CABAÑAS / RANGO: INVESTIGADORA JEFA DE MANCHAS / DEPARTAMENTO: UNIDAD ESPECIAL DE LIMPIEZAS IMPOSIBLES (UELI). / ZONA DE ACCIÓN: TODA LA CASA. / ESPECIALIDAD: ANÁLISIS FORENSE DE CHURRETONES. / CASOS FAMOSOS: OPERACIÓN "SALSA BRAVA" (2019) Y CASO SALMOREJO (1997). SUPERA LA SEGUNDA PREGUNTA Y XUSO SE FIJA EN LA CAMISETA DEL ELEGIDO PORQUE HACE REFERENCIA A UN FESTIVAL DE JAZZ DEL PRAT RELACIONADO CON LA ALCACHOFA, OTRA PRODUCTO TÍPICO DEL PRAT. // EN LA TERCERA PREGUNTA, EL ELEGIDO RESPONDE "MUSEO DE VERSALLES", SE QUEDA CERCA, PERO NO ACIERTA Y VICKY DECIDE LLAMAR A SU HIJO JOSE PORQUE LEE MUCHO, PERO CONTESTA "MUSEO DEL VATICANO". NOS CUENTA QUE CON EL DINERO LE GUSTARÍA REGALARLE UN VIAJE AL SERENGUETI A SU MARIDO PORQUE LLEVAN DESDE LOS 13 AÑOS Y "SE LO MERECE TODO". SUPERA LA CUARTA PREGUNTA Y DECIDE JUGAR. EN LA QUINTA, ELIGE A UN CHICO QUE ACIERTA Y SE LLEVA 1.200 EUROS', 'Cristina', '2', 'Acting mercado pollo potablava. 
Mecánica corta. 
Nos saltamos una pregunta. 
Tiene llamada de emergencia.', '21:20', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (559, @jornada_id_152, '2025-06-20', 'EL PRAT', 'SHEILA', 44, 'ADMINISTRATIVA', '@sheila.f.ll', 585, 400, 'REC 10:56 - 11:39 
ARRANCAMOS EN LA PLAZA DE LA VILA Y XUSO QUIERE PREGUNTAR A LOS VECINOS DEL PRAT QUÉ ES LO QUE MÁS LES ENNORGULLECE DE SU MUNICIPIO. SE ACERCA A UNA MESA CON TRES SEÑORAS Y LE HABLAN SOBRE LAS ALCACHOFAS, EL POTABLAVA, SAN POLLÍN Y EL MIRADOR DE AVIONES (*CRIS: SI FUESE POSIBLE POR TIEMPO, INTENTARÍA NO LEVANTAR NINGUNA INTERVENCIÓN PORQUE MENCIONAN LOS CUATRO ELEMENTOS MÁS REPRESENTATIVOS DEL PRAT). XUSO SE ACERCA A LA MESA DE AL LADO Y HABLA CON UNA CHICA QUE LE CONFIESA QUE ES FAN DE ÉL Y LA CAPTAMOS. EN LA PRIMERA PREGUNTA, SHEILA ELIGE A UNA MUJER A LA QUE NO LE VIENE A LA MENTE "EL POLO" Y NOS VAMOS A LA LLAMADA DE EMERGENCIA. SHEILA LLAMA A UNA COMPAÑERA DE TRABAJO Y SUPERA LA PRIMERA PREGUNTA. TRAS ESTE PRIMER BACHE, NOS CUENTA QUE ES ADMINISTRATIVA EN EL AYUNTAMIENTO DEL PRAT Y QUE SE DEDICA A AYUDAR AL CIUDADANO (REPETIMOS EXPLICACIÓN Y NOS QUEDAMOS CON LA SEGUNDA). SUPERA LA SEGUNDA PREGUNTA Y VAMOS DIRECTOS A LA TERCERA. NO SUPERA LA TERCERA PREGUNTA, Y NOS CUENTA QUE CON LOS 30.000 EUROS PAGARÍA LOS ESTUDIOS DE SUS HIJAS Y SE IRÍA CON SUS DOS HIJAS Y SU MARIDO A LONDRES. NO SUPERA LA CUARTA PREGUNTA Y DECIDE PLANTARSE.', 'Cristina', '1+', 'En boca de Xuso.
Mecánica corta. 
Tiene llamada de emergencia. 
Nos saltamos una pregunta. 
Se planta.', '21:16', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (560, @jornada_id_152, '2025-06-20', 'EL PRAT', 'LAIA', 25, 'PELUQUERA', '@shego.star', 595, 600, 'REC 12:04 - 12:44 // ARRANCAMOS CON XUSO BEBIENDO AGUA DE LA FUENTE CON FORMA DE LA CRESTA DEL POTABLAVA. BROMEA CON ROSA Y EMPEZAMOS A ANDAR. SALUDA A UNA MUJER QUE LLEVA UNA COCA PORQUE SE ACERCA LA VERBENA DE SAN JUAN Y SALUDA A UN HOMBRE MUY SIMPÁTICO QUE LE INVITA A SU HUERTO PARA QUE PUEDA PROBAR LAS FAMOSAS ALCACHOFAS DEL PRAT (SI FUESE NECESARIO RECORTAR TIEMPO, LEVANTAMOS A LA PRIMERA SEÑORA, PERO NO AL SEGUNDO HOMBRE). SEGUIMOS ANDANDO Y XUSO SE FIJA EN UNA CHICA QUE SE PARECE MUCHO A LA ACTRIZ MILENA SMITH, ELLA RECONOCE QUE SE LO DICEN MUCHO Y BROMEAMOS CON ELLA Y SU FAMILIA. LA CAPTAMOS Y MICROFONAMOS. LA PRIMERA ELEGIDA NO ACIERTA, Y LAIA LLAMA A SU NOVIO PORQUE ES VENEZOLANO "Y TIENE MELANINA". ANTES DE LA LLAMADA, NOS CONFIESA QUE TIENE LA PALETA ROTA Y QUE SU NOVIO ESTÁ CON PUNTOS EN LA CABEZA POR UN "BESO PASIONAL Y NOCTURNO" QUE ACABÓ EN ACCIDENTE. EL NOVIO ACIERTA Y LAIA SUPERA LA PRIMERA PREGUNTA. NOS CUENTA QUE ES PELUQUERA "CONVENCIONAL" Y QUE TAMBIÉN HACE PELUCAS PARA CANTANTES COMO LADILLA RUSA. XUSO SE PONE A CANTAR "MACAULAY CULKIN" Y LE PIDE A GRAFISMO QUE LE PONGAN UNA PELUCA EN LA CABEZA A MEDIDA QUE LAIA VA CONTANDO LAS DIFERENTES PELUCAS QUE HACE (DEJAR ESTE MOMENTO MÁS PICADO A MEDIDA QUE LAS DESCIBRE "LARGA", "CORTA", "DE COLOR AZUL", ETC. HASTA ACABAR CON UN MULLET SOBRE LA CABEZA DE LA XUSO PARA QUE LOS DOS TENGAN EL MISMO PELO). SUPERA LA SEGUNDA PREGUNTA Y NOS CUENTA QUE HACE "POLE DANCE". NOSOTROS NO TENEMOS BARRA, PERO SÍ NUTRIA, ASÍ QUE HACE UNA PEQUEÑA DEMOSTRACIÓN CON LA PÉRTIGA. SUPERA LA TERCERA PREGUNTA Y NOS CUENTA QUE CON EL DINERO SE ARREGLARÍA LA PALETA, HARÍA UN VIAJE Y PONDRÍA UNA BARRA DE POLE DANCE EN EL COMEDOR. NO SUPERA LA CUARTA PREGUNTA Y DECIDE PLANTARSE CON 600 EUROS.', 'Cristina', '2+', 'Mecánica corta. 
Se planta.', '20:08', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (561, @jornada_id_152, '2025-06-20', 'EL PRAT', 'JUANITO', 55, 'COMERCIAL', '@nolg', 547, 600, '***CUESTIONARIO MUSICAL*** // REC 13:31 - 14:13  //
 ARRANCAMOS EN LA PLAZA DE PAU CASALS DEL PRAT DE LLOBREGAT Y XUSO NOS CUENTA QUIÉN FUE ESTE HOMBRE: UN GRAN MÚSICO Y UNO DE LOS MEJOR VIOLONCHELISTAS DEL SIGLO XX. ADEMÁS, PAU CASALS COMPUSO EL HIMNO DE LAS NACIONES UNIDOS Y A DÍA DE HOY, SIGUE SIENDO UN EMBLEMA DE LA PAZ Y LA LUCHA POR LOS DERECHOS HUMANOS EN EL MUNDO. XUSO COMIENZA A ANDAR Y SE ENCUENTRA CON JUANITO Y LE PREGUNTA QUÉ MÚSICOS FAMOSOS HAN NACIDO EN EL PRAT. JUANITO NOS HABLA DE MUCHO MUCHACHO, UNO DE LOS PIONEROS DEL RAP EN ESPAÑA Y DE ALFRED GARCÍA (CORTAR EL TERCER GRUPO QUE MENCIONA). LO CAPTAMOS Y MICROFONAMOS. SUPERA LA PRIMERA PREGUNTA Y NOS CUENTA QUE ESTÁ EN UNA ASOCIACIÓN DE "POTABLAVAS" Y QUE PARTICIPA EN MUCHAS INICIATIVAS LÚDICAS Y CULTURALES. TAMBIÉN NOS HABLA DE SAN POLLÍN, QUE ES COMO LOS SANFERMINES DEL PRAT, PERO SIN SUFRIMIENTO ANIMAL (INTENTARÍA DEJAR LA MENCIÓN A SAN POLLÍN, PERO RECORTARÍA EL FINAL PORQUE SE ENROLLA MUCHO). SUPERA LA SEGUNDA PREGUNTA Y VAMOS DIRECTOS A LA TERCERA, PERO ANTES CAMBIAMOS DE ACERA PARA ESTAR A LA SOMBRA Y XUSO SE COMPRA UNAS EMPANADILLAS. EN LA TERCERA PREGUNTA, LA ELEGIDA NO ACIERTA Y JUANITO LLAMA A SU HERMANA, PERO TAMPOCO ACIERTA. EN CASO DE GANAR 30.000 EUROS, TAPARÍA AGUJEROS PARA VIVIR MÁS TRANQUILO. SUPERA LA CUARTA PREGUNTA GRACIAS A QUE EL ELEGIDO DUDABA ENTRE "MADRUGAR Y TRABAJAR" Y DECIDE PLANTARSE.', 'Cristina', '1+', 'Mención a Pau Casals, violonchelista de El Prat. 
Cuestionario musical. 
Mecánica corta. 
Nos saltamos una pregunta.  
Se planta.', '22:15', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (562, @jornada_id_153, '2025-06-23', 'ALBACETE', 'VÍCTOR', 63, 'FUNCIONARIO', '@victormajs', 571, 600, '12.33 - 13.23. Xuso arranca en el pasaje de Lodares, una de las tres únicas galerías modernistas de España. Llama la atención sobre las columnas y las cabezas mitológicas. Se para a hablar con un repartidor que quiere concursar, pero ahora no puede. Xuso nos cuenta que está feliz en Albacete porque de ahí es su familia, y justo aparece Víctor que cuenta que es de Elche de la Sierra y era amigo de infancia de su madre. Su padre y el abuelo de Xuso eran amigos y Xuso se enternece y le hace concursante. Arrancamos con la pregunta 1 y para a Antonio, de 90 años, que dice unos cuantos refranes sobre beber vino que habrá que rebajar. Antonio no sabe la respuesta y vamos al Xusoquer. Le sale el de continúe y gana sus primeros 200 euros. Nos cuenta historias de la familia de Xuso y nos ceba que su abuelo era un buen elemento. Vamos a la segunda y coge a un chico joven que responde Bruselas, y como se ha liado gana los 400. Nos cuenta que es viudo, y que tiene dos nietos que le hacen seguir adelante. También habla un poco más de la familia de Xuso, pero me quedaría con lo de su vida. Vamos a la tercera, y él no sabe como decir house tour porque no sabe nada de inglés. Para a Cristina y ella acierta. Con los 600 nos cuenta que fue a Las Vegas y allí no se hablaba en inglés y que el dinero lo quiere para pagar la hipoteca que le quedó porque tiene un hijo con distrofia muscular y no le dejaron adaptar la casa en la que vivían, así que tuvieron que comprar otra y justo su mujer murió de cáncer, pero él sigue luchando. Para la cuarta pregunta falseamos captación de un muchacho porque la acompañante no quería y de casualidad acierta. Aún así Víctor se planta con los 600€.', 'Adriana', '2', 'Acting en PASAJE LODARES. 
El concursante es amigo de la madre de Xuso. 
XUSOQUER "continúa"', '20:56', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (563, @jornada_id_153, '2025-06-23', 'ALBACETE', 'SEYLA', 31, 'DEPENDIENTA', '@sheiseyla', 558, 457, 'X2 SP', 0, '***CUESTIONARIO MUSICAL***
 13:44 - 14:40. Xuso arranca alabanzo el nuevo look del equipo y pide micro de cuestionario musical porque parecemos un cuerpo de baile. Capta a una señora que le canta Melendi muy mal (las otras no firman) y después a Seyla que le hace un show de Lola Índigo y le cuenta que viene de hablar con el florista sobre las flores de la boda, porque se casa. Xuso la convierte en concursante y en la primera pregunta para Natalia, que acierta, y juntas cantan "Tanto la quería." Nos cuenta que conoció a su chico en el instituto y que una amiga supo que sería novios y que le pidió matrimonio y ella no se lo esperaba. En la segunda, ella no tiene ni idea, pero busca a una chica, por eso del girlpower. Coge a Ana que responde las Pussycat Dolls y cantan. Gana los 400 y nos cuenta que organizar la boda está siendo un horror y que va a dar una sorpresa a los invitados haciendo un número de Lola Índigo. Lo hace a cámara. METER GRAFISMO DE ELEMENTOS DE BODA. De la tercera no tiene ni idea, y coge a un chico que tampoco. Así que vamos a comodín y le sale un del verrés, coge a Lady, una muchacha joven y no lo sabe, así que gana los 600 y hacemos la conga con la canción de Sopa de caracol. Como ya nos ha dicho que el dinero es para la boda, pasamos a la cuarta pregunta y la señora a la que para acierta. Con los 600 se arriesga. Sabe la respuesta porque le encanta eurovisión, pero para a Laura que no sabe nada, ni siquiera quién es Loreen. Se va a 0 con su camiseta de "Ole ole los caracoles".
 CANDIDATA SEGUNDA OPORTUNIDAD. Boda 4 octubre.', 'Adriana', '3', 'Cuestionario musical. 
Xuso destaca el nuevo look del equipo. 
XUSOQUER "Del verrés"
Nos saltamos una pregunta. 

CANDIDATA SEGUNDA OPORTUNIDAD (¿el día de su boda? 4 de octubre 2025)', '23:31', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (564, @jornada_id_153, '2025-06-23', 'ALBACETE', 'JUANAN', 40, 'MONITOR CENTRO OCUPACIONAL', '@84juanan', 564, 428, 'X3 SG', 1800, '16:28 - 17:23. Xuso reportero pregunta por unn artículo del Daily Mirror que dice que Albacete es la mejor ciudad para ir de turismo por su seguridad y no consigue a nadie de Albacete. Aparece Juanan con su mujer, que cuenta que es de Alicante, pero se vino por amor y se convierte en concursante. La primera la sabe y para a un chico joven, Miguel. La super ay nos cuenta que es voluntario con personas con discapacidad  y trabaja de ello. En la segunda para a Alberto, que acierta y con el XUSOQUER, vamos a llamada. Llama a su padre y tenemos que repetir cuenta atrás de la llamada, pero no acierta. Se gana los 400 y cuenta que es un showman y nos canta Mi gran noche de Raphael. PONER PELO EN GRAFISMO. En la tecerda para a una peluquera que hace publi de su peluquería y dice "16", así que no la supera. Nos cuenta que el dienro sería para una autocaravana para viajar con sus hijos. Tiene dos gemelos a los que manda un saludo. Para la cuarta coge a un chico que le encanta el protagonismo y responde "Sofía". Con los 600 no duda en jugársela, le sale un x3 y para a una chica, que resulta ser hermana de Ernesto Sevilla y que acierta porque es profesora de inglés. Es tan graciosa que le invitamos a concursar al despedir a Juanan, que se va feliz con su dinero. 
ENLAZAR CON EL 565', 'Adriana', '2', 'XUSO REPORTERO
¡OJO! La quinta elegida es la siguiente concursante, #565#, y deben ir juntos en escaleta.', '25:13', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (565, @jornada_id_153, '2025-06-23', 'ALBACETE', 'CARMEN', 49, 'PROFESORA', 'NO TIENE', 554, 1000, '17:24 - 18:19 Xuso va a donde se ha ido carmen y le pone la pegatina. Xuso se pone la gorra (meter en microfonado). Carmen arranca su concurso muy nerviosa y 
para en la primera a una chica con un bebéd e un mes, que va haciendo una videollamada. Carmen es muy nerviosa y no hace caso de nada (perdón a edición). Elena, 
la elegida, dice Puerto Rico y vamos a XUSOQUER. Le sale un continúa y nos cuenta que da clase a niños de todas las edades y Xuso saca a Juanjo, Adriana y él a hacer 
un examen de inglés. En la segunda coge a un jubilado que no sabe la respuesta y se alegra porque conoce el programa. Nos cuenta que etsá divorciada u tiene dos 
hijas de 17 y 19. En la tercera pregunta busca a alguien joven y coge a una chica que responde cantando muy bien. Es un momento muy surrealista. Luego cantan 
juntas y hablan en inglés. Con el dinero quiere pagar a sus hijas un máster. Nos cuenta que su nombre se lo pusieron por su abuela y que su hermano es muy serio en 
casa. Para la cuarta coge a una señora que la reconoce como la profesora de su hijo que ahora tiene 24 años, pero Carmen no tiene ni idea de quién es el hijo. Ana, la 
elegida tiene miedo de la nutria y responde que no sabe y se va corriendo agobiada, pero al final vuelve y celebran juntas, aunque Carmen dice que es muy mayor por 
haberle dado clases al hijo. Decide plantarse porque hace poco le estafaron mil euros en un centro de estetica láser y Dios se los esté devolviendo. Se va muy feliz.', 'Adriana', '2+', '¡OJO! Esta concursante debe ir en escaleta tras el #564#', '20:27', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (566, @jornada_id_154, '2025-06-24', 'HELLÍN', 'ALBERTO', 33, 'OPERARIO DE BODEGA', '@alberto.portana', 600, 339, 'X6 N', 2000, '09:43 - 10:40: Xuso empieza en la escultura al tamborilero y con un tambor porque es lo típico de Hellín. Cuenta que la Semana santa es un bien de interés turístico internacional y que se lía parda porque más de veinte mil tamborileros se juntan a tocar. Toca un poco regular y le decimos que lo hace mal, y busca a alguien que le enseñe. Charla con un jubilado que no es de Hellín, pero le dice que lo toca mal, que le pone un cinco. SIgue buscando profesor y se cruza con Alberto, que le corrige la postura y se pone el tambor para tocar. Le hace concursante y dice que es el primer concursante de Hellín (quitemos esto). Vamos a la primera pregunta y caminamos bastante hasta que coge a una chica que acierta. Nos cuenta que trabaja en una bodega en Villarobledo y nos habla del tambor. En la segunda coge a una señora que no se entera de nada y dice "una", al resolver insiste en que se juega con una al inicio y Xuso tiene que aclarárselo. Alberto nos cuenta los distintos toques de tambor de la semana santa. En la tercera elige a un joven que está en una terraza tomando algo y acierta por suerte, porque dice copa a boleo. Alberto nos cuenta que el dinero lo quiere para llevarse a su madre a Roma o Grecia porque lleva toda la vida cuidando de su hermana (no quiere decir porqué). También ahorraría porque se está preparando una oposición. en la cuarta coge a una señora con una muleta que acierta y vamos al comodín. Le sale un "al verrés" y busca extrañamente un hombre. Para a uno que va conduciendo y hacemos transición para reunirnos con él en otra calle. El señor acierta. ALberto duda de jugársela porque ese es el dinero que tiene que pagar a hacienda, pero al final se arriesga. Abrimos sobres, pero sale el x6 lo primero, así que nos quedamos con el sobre elegido, que es un x2. Alberto no se entera bien de la pregunta, cree que preguntamos por una ciudad. Elige a un chico joven que acierta sin saberlo y se va con los 2000 y el tambor de Xuso.', 'Adriana', '2', 'Acting Xuso con tambor, busca a alguien que le enseñe a tocarlo bien.', '23:50', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (567, @jornada_id_154, '2025-06-24', 'HELLÍN', 'CONCHI', 60, 'CUIDADORA', 'NO TIENE', 597, 420, 'X3 SP', 0, '11:09 - 11:57. Xuso entra en una tienda de caramelos buscando los famosos caramelos de Hellín, que se los ha encargado su madre. Dentro, el dependiente le habla 
de los caramelos y del éxito que tienen en todas partes. Xuso se come uno y coge de paso un imán de Hellín. El señor también le cuenta un rollo de la semana que hay 
que quitar porque se hace largo. Al salir ve a Conchi que está comprándole una navaja a su hijo que vive en M ozambique y le propone concursar, y a ella le viene 
genial para visitar a su hijo. Arrancamos ya en la calle y en la primer apregunta coge a Soledad que acierta y gana los 200. Nos cuenta que quiere ir a Mozambique 
donde su hijo trabaja de cooperante y que quiere. conocer a su nuera morenita, o negra como dice su hijo y que si le sale un novio mulato mejor que mejor. Xuso le 
pregunta si busca pareja y ella hace un llamamiento por el hombre perfecto (GRAFISMO FIRST DATES O TINDER). Vamos a la segunda pregunta y coge a una chica 
llamada Noelia (hay una primera captación, pero la persona no quiere). Noelia responde Juan Carlos I y Conchi gana los 400 celebrándolo por todo lo alto. Nos 
cuenta que está estudiando para bombero forestal y que nunca es tarde para cumplir sueños. En la tercera elige a una amiga suya que esté en la plaza. Encarni duda 
mucho, pero al final le sale la palabra mandala y lo celebran con una clase de zumba, ya que se conocen de esa actividad (un poco obligadas por Xuso). Vamos a la 
cuarta pregunta directos y coge a una señora que toma café, Amparo, a la que conoce bien porque han sido vecinas. Amparo no tiene ni idea de gramática y Conchi 
gana los mil. Se piensa mucho si se la juega o no, y al final se anima. Justo elige a un señor que está buscando a Xuso porque era amigo de la infancia de su madre. Este 
señor, Manolo, responde mocasines y la pobre Conchi se va a 0€.
 CANDIDATA A SEGUNDA OPORTUNIDAD EN ALBACETE.', 'Adriana', '3', 'Xuso busca la casa de sus abuelos en la que también vivió su madre. 
Xuso compra famosos caramelos de Hellín para su madre. 
Nos saltamos una pregunta. 
Candidata a SEGUNDA OPORTUNIDAD.', '23:43', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (568, @jornada_id_154, '2025-06-24', 'HELLÍN', 'VICTORIA
SARA', 'AUXILIAR ENFERMERÍA; ESTUDIANTE', '@mvictoriamaring
@saraavillena_', 578, 404, 'X3 SG', 1200, '***CUESTIONARIO MUSICAL***
 ESTE CUESTIONARIO ARRANCA CON XUSO LLEGANDO A HELLÍN, GRABADO EN LA JORNADA 153 CON MÓVIL, GO PRO Y CAM 1. 
+
 OPCIÓN A: INTENTEMOS AÑADIR LO DE LA CASA DE LOS ABUELOS DE XUSO. GRABADO EN LA JORNADA 154, CONCURSANTE 569 (14:07) (que no se terminó de grabar), pero este acting mola y si se puede recortar es bonito tenerlo. 
+ arranque de Xuso. Si se ha podido hacer lo anterior, que comience con Xuso diciendo: "voy a preguntar en el kiosko" y intentamos conducirlo como que Xuso quiere saber de sus antepasados (la idea original es que fuera una búsqueda)
 OPCIÓN B: AL FINAL, METEMOS LA DESPEDIDA DE XUSO LLEGANDO A CASA DE LOS ABUELOS. GRABADA AL FINAL DE LA JORNADA 154 (me gusta menos, pero puede valer) SE ME OCURRE UNA OPCIÓN, PERO ME GUSTARÍA EDITARLO YO Y VER COMO QUEDA. 
Xuso habla sobre buscar sus orígenes en Hellín y va al kiosko a preguntar por su abuelo, y el del kiosko no le conoce, pero Victoria que está comprando dice que su abuelo fue el dentista de Hellín y que su madre nació en Elche de la sierra. Xuso se emociona y la hace concursante con su sobrina Sara. Arrancan y en la primera no les suena de nada lo de "El madrileño". Sara cree que es un cantante antiguo y preguntan a un anciano, que obviamente no lo sabe. Hacemos transición antes de sacar el Xusoquer, porque no estamos bien ubicados. Al regresar les sale la llamada y llaman a una amiga de Sara que no lo coge. Nos cuentan que se llevan muy bien y que la madre de Sara murió y para Sara su tía es una brújula. Victoria se emociona. Vamos a la siguiente pregunta y de nuevo no tienen ni idea. Cogen a un chico que está de pie en una terraza y éste tampoco lo sabe. Ganan por fin algo de dinero. Nos cuentan que Victoria es auxiliar de enfermería y Sara quiere estudiar lo mismo. En la cuarta se ponen a buscar a un hombre y justo sale Eusebio de un portal, pero aunque conoce la canción no sabe la respuesta. Ellas nos cuentan que el dinero sería para ayudar al padre de Sara, que está al cargo de la casa y para que Victoria monte en globo. Nos vamos a la cuarta y mientras miran en una cafetería, sale una señora y deciden que ella les v ale. La señora no entiende ni la pregunta y está un poco zumbada, le dice a Xuso algo de su pareja que hay que quitar. Ganan los 400 y se la juegan porque no es nada de dinero. Le sale un x3 y a Sara le suena la canción porque su padre la escucha en el coche, pero Victoria ni idea. Cogen a un señor que dice escuchar solo música clásica, pero dice "Abril " y ellas se van felices con Xuso a buscar la casa de su abuelo (en la opción A, este final habría que modificarlo, hay que ver si se puede)', 'Adriana', '2', '¡OJO! Este concursante tiene que ser el PRIMERO que se escalete de Hellín. 
ACTING XUSO DESCUBRE CARTEL HELLÍN (está grabado en la jornada 153)
CUESTIONARIO MUSICAL.', '23:45', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (569, @jornada_id_155, '2025-06-25', 'ALBACETE', 'ELVIRA', 55, 'ABOGADA', 'NO TIENE', 596, 443, 'X3 SP', 0, '***CUESTIONARIO MUSICAL***
 09:37 - 10:24. Xuso está delante de la catedral de Albacete y habla sobre la mala rima que tiene Albacete y pide rimas nuevas. Le damos varias opciones y cuando se cruza con Elvira, esta le dice "A Albacete viene Xuso a repartir billetes". LA hace concursante y es cuestionario musical. Ella nos cuenta que su estilo favorito es la bachata, pero no sabe bien la respuesta a la primera pregunta. Coge a una chica embarazada de siete meses que acierta y le hace una muestra de bachata. Nos cuenta que es abogada, aunque quería ser Policía, pero como es muy bajita no pudo. Se enrrolla como una persiana y la tengo que cortar, en edición habrá que darle unos buenos tajos. En la segunda elige a Palomares, un anciano que viene de comprar lechuga a su canario sin nombre. Palomares es muy personaje y no conoce nada del programa, así que no da crédito a todo lo que sucede. Nos cuenta Elvira que tiene novio desde hace muchos años, que es de Tenerife y lo conoció por internet porque antes se murió su prometido con 28 años. En la tercera pregunta elige a Fran, que responde "Siniestro total" porque son gallegos. No la supera, sacamos los xusóquers y le sale el "continúa", asi que gana los 600€. Nos cuenta que el dinero es para la hipoteca y un masaje sin final feliz (en la despedida Xuso hace referencia al masaje). Para la cuarta coge a una chica joven que tiene un bebé de diez meses y acierta, así que con los 600 decide jugársela. La pregunta le parece fácil, pero la señora que elige, Patricia, dice "seXto" con X y Elvira se coge un buen disgusto. Se va con la camiseta de "echa la pala".', 'Adriana', '2', 'CUESTIONARIO MUSICAL.', '23:37', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (570, @jornada_id_155, '2025-06-25', 'ALBACETE', 'JUAN', 43, 'TÉCNICO MANTENIMIENTO ASCENSORES', 'NO TIENE', 592, 600, '11:00 - 11:37: Xuso está en el clavo mágico de Albacete pidiendo deseos, saca a Adriana y a Chete para que pidan sus deseos, cuando Chete pide el suyo 
le ponemos "Yo quiero bailar" de Sonia y Selena. Xuso ve a Juan que le está mirando, y cuando le dice que es de Hellín le convence. Le dice que pida un 
deseo, y le dice que por qué no pide concursar en LSNLS. Lo pide y se convierte en concursante. Arrancamos y se queda en shock con la primera 
pregunta porque no tiene ni idea. La persona elegida no acierta, es un chico de su misma edad que no cae en la palabra, así que tenemos que sacar el 
Xusóquer, y le sale un continúe. Nos cuenta su profesión, que tiene dos hijos y sobre todo habla muy bonito de su mujer de la que está muy 
enamorado. Para la segunda busca a una mujer mayor y para a Beatriz que nos ve todos los días, pero no sabe nada de Pau Gasol y le hace ganar los 400. 
Pasamos directos a la tercera pregunta y Juan está descolocado porque él veía más Los caballeros del zodiaco y El príncipe de Bel Air. Ve a un chico 
desayunando en un bar y entra Xuso a por él. El chico acierta, pero dice mal una letra, que al final corrige. Xuso hace el "ooonda vital" (METER 
GRAFISMO). Juan nos cuenta que el dinero sería para tapar agujeros y que para él lo improtante es la salud y disfrutar de sus hijos. En la cuarta coge a 
Eufemia, una señora un poco rara que acierta y cuando sabe que tenía que fallar se coge un buen disgusto. Juan decide plantarse y se va muy feliz.', 'Adriana', '2', 'Arranque en el clavo mágico. 
Nos saltamos una pregunta.', '19:23', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (571, @jornada_id_155, '2025-06-25', 'ALBACETE', 'JUAN', 27, 'OPTOMETRISTA', '@juaanchez', 593, 1000, 'ACTING DE INICIO: Xuso compra un imán. 10:56 - 10:58.
 CONCURSO: 12:01 - 12:33. Xuso llega a un mercadillo de ropa de segunda mano y busca un regalo para Virtudes, y ve a Juan tan bien vestido que le dice 
que le ayude. Le coge un peto vaquero y ofrece a Juan concursar. Antes de arrancar con la primera pregunta aparece un señor vestido de vaca y les 
embiste. Se van un poco más alejados y tras la primera pregunta, Juan no tiene ni idea de qué le hablan, pero elige a Juan Carlos que viene de hacer 
deporte y no duda en su respuesta. Juan nos cuenta su profesión, que es más que vender gafas, pero Xuso quiere saber cómo le quedan a él las gafas y le 
pide que le aconseje. METEMOS GRAFISMO DE LAS DISTINTAS GAFAS. La segunda le parece fácil de superar y lo hace con una señora fan del programa, 
Llanos, que es amante de Titanic. Juan nos cuenta que toca el piano desde hace un año. Vamos a la tercera y nos dice que la sabe porque vivió en 
Canarias 2 años y elige a una chica joven que no la sabe, pero la deduce. Juan nos cuenta que con el dinero se quiere llevar a su abuela Inocencia de 
balneario, porque su abuela es su alma gemela. Xuso dice que le recuerda a su abuela y ambos hablan de que hay que cuidar a los abuelos. Para la 
cuarta elige a Maria, fan del programa, que acierta y pide disculpas por ser tan lista. Pero Juan saca un Xusóquer y le toca un "continúa" (una vez más en 
el día de hoy). Con los mil euros decide plantarse para llevarse a Inocencia al balneario de Archena.', 'Adriana', '2+', 'Acting imán de Albacete.', '21:06', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (572, @jornada_id_155, '2025-06-25', 'ALBACETE', 'XUSO', 35, 'DIRECTOR DE CLÍNICA DENTAL', '@jesusmasia', 569, 429, 'X4 SG', 4000, '13:19 - 13:57. Xuso entra en la heladería más antigua de Albacete a probar los helados y se come uno de cacahuete salado. Al salir charla con una 
señora que se está comiendo el de turrón, y el chico de la mesa de al lado otro de turrónl. Prueba del del chico y le encanta, le pregunta como se llama 
y como son tocayos le invita a concursar. El concursante, en adelante Xuso2, le dice que es director de una clínica dental y que tiene un rato ahora. 
Arrancan y en la primera coge a Juana que acierta. Xuso2 nos habla de su trabajo y de que está casado y tiene dos gemelos de cuatro años. En la segunda 
justifica muy bien su búsqueda y elige a Anabel que no lo sabe. Pasamos directos a la pregunta tres y en esta vuelve a buscar a una mujer. Al pasar por la 
Casa del libro ve a una señora que compra en el interior y la elige. Ella sale y es muy educada, Acierta y se va feliz con su libro nuevo. Xuso nos dice que 
con el dinero viajaría y daría la entrada para un nuevo piso porque el suyo se queda pequeño para los cuatro y nos habla de su mujer, que es una 
persona increíble y sigue muy enamorado. En la cuarta no tiene ni idea y aunque busca una chica, cambia de opinión al ver a un joven que no sabe nada 
de refranes y le hace ganar los mil. Se arriesga y le sale una pregunta que le prece complicadísima, pero pasa unn grupo de curas y elige a uno de ellos. El 
cura le da suerte divina y le hace ganar los 4000. Se va feliz a su casa y muy agradecido.', 'Adriana', '2', 'Acting heladería más antigua de Albacete. 
Nos saltamos una pregunta.', '21:41', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (573, @jornada_id_156, '2025-06-30', 'BILBAO', 'JOSEBA', 67, 'JUBILADO', '@joseba.cano', 576, 424, 'X22 N', 0, 'REC 15:44 - 16:42 // ARRANCAMOS JUNTO A LA ESTACIÓN DE LA CONCORDIA TAMBIÉN CONOCIDA COMO LA ESTACIÓN DE SANTANDER PORQUE FUE LA PRIMERA QUE CONECTABA BILBAO Y SANTANDER EN MENOS DE CUATRO HORAS Y GRACIAS A ESO, EL COMERCIO EN EL NORTE PEGÓ UN BUEN EMPUJÓN. NOS FIJAMOS EN LA FACHADA MODERNISTA Y COMENZAMOS A ANDAR. OJO: XUSO HABLA CON UNA MUJER EXTRAJERA QUE NO FIRMA DERECHOS. CONSULTAR CON PRODUCCIÓN SI PODEMOS DEJARLA. SEGUIDAMENTE, NOS ENCONTRAMOS CON JOSEBA QUE NOS CUENTA QUE SE DIRIGE A LA ESTACIÓN PARA COMPRAR UNOS BILLETES A LEÓN PORQUE SE MARCHA PASADO MAÑANA CON UNOS AMIGOS. LO CAPTAMOS Y MICROFONAMOS. EL PRIMER ELEGIDO NO SABE LA RESPUESTA Y NOS VAMOS POR TRANSICIÓN AL XUSOKER. LE SALE UN RECICLA, ELIGE A UNA CHICA 
JOVEN Y JOSEBA SUPERA LA PRIMERA PREGUNTA. NOS CUENTA QUE AHORA ESTÁ JUBILADO Y QUE, COMO LA HISTORIA SIEMPRE FUE SU ASIGNATURA PENDIENTE Y LAS HUMANIDADES, SU GRAN PASIÓN, AHORA ESTUDIA HISTORIA POR LA UNED. SUPERA LA SEGUNDA PREGUNTA Y VAMOS DIRECTOS A LA TERCERA. REPETIMOS FORMULACIÓN DE LA TERCERA PREGUNTA. NO SUPERA LA TERCERA PREGUNTA Y EXPLICA QUE CON EL DINERO LE GUSTARÍA SEGUIR VIAJANDO Y DISFRUTAR DE LA GASTRONOMÍA Y LA HISTORIA DE LAS CIUDADES QUE VISITE. SUPERA LA CUARTA PREGUNTA Y DECIDE JUGAR. ABRIMOS LOS SOBRES MULTIPLICADORES Y VEMOS UN X22. ELIGE A UNA CHICA QUE NO ERA AFICIONADA A LA LECTURA Y SE MARCHA CON LA CAMISETA DEL PROGRAMA.', 'Cristina', '2', 'Mecánica corta. 
Arranque estación de la Concordia. 
Nos saltamos una pregunta. 
Apertura de sobres.
Aunque tiene pasta, no me disgusta para Segunda Oportunidad.', '23:39', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (574, @jornada_id_156, '2025-06-30', 'BILBAO', 'TAMARITA', 31, 'DEPENDIENTA', '@tamaritamiau', 559, 600, 'REC 17:05 - 17:43 // ARRANCAMOS A LOS PIES DE LA CATEDRAL DE SANTIAGO Y XUSO NOS CUENTA QUE SE TRATA DEL EDIFICIO MÁS ANTIGUO QUE SE CONSERVA EN LAS SIETE CALLES, Y ESTÁ CONSIDERADA LA IGLESIA GÓTICA MÁS GRANDE DE BIZKAIA. ADEMÁS, NOS FIJAMOS EN LAS CONCHAS DE LA FACHADA QUE HACEN REFERENCIA AL CAMINO DE SANTIAGO Y ECHAMOS A ANDAR. XUSO HABLA CON UNA SEÑORA QUE SE ESTÁ TOMANDO UN CAFÉ Y DESPUÉS SE FIJA EN DOS CHICOS JÓVENES. INTERACTÚA CON ELLOS Y NOS QUEDAMOS CON TAMARITA POR SU ACTITUD COQUETA. SUPERA LA PRIMERA PREGUNTA Y NOS CUENTA QUE ES DEPENDIENTA EN UNOS GRANDES ALMACENES Y QUE TAMBIÉN ES MAQUILLADORA. EN LA SEGUNDA PREGUNTA, ELIGE A UN CHICO QUE ESTÁ SENTADO EN UNA GRAN MESA Y RESULTA QUE SON PROFESORES QUE ESTÁN CELEBRANDO EL FIN DE CURSO. AUN ASÍ, EL CHICO NO SABE LA RESPUESTA Y TAMARITA SUPERA LA SEGUNDA PREGUNTA. VAMOS DIRECTOS A LA TERCERA Y TAMARITA ELIGE A UNA MUJER QUE CONTESTA "TAJO", ASÍ QUE NOS VAMOS AL XUSOKER. LA CARTA ELEGIDA ES UN CONTINÚA, LO CELEBRAMOS Y TAMARITA NOS CUENTA QUE CON EL DINERO LE GUSTARÍA PAGAR LA ENTRADA DE UN PISO Y DEJAR DE PAGAR EL ALQUILER (CORTAR CUANDO XUSO PREGUNTA SI LA VIVIENDA ES CARA EN BILBAO). EN LA CUARTA PREGUNTA, TAMARITA ELIGE A UN SEÑOR MAYOR QUE CHAPURREA BASTANTE BIEN EL INGLÉS, ASÍ QUE NO SUPERA LA CUARTA Y SE PLANTA CON 600 EUROS.', 'Cristina', '2', 'Mecánica corta. 
Arranque frente a la iglesia de Santiago. 
Nos saltamos una pregunta. 
El elegido de la cuarta pregunta se emociona por no haber podido ayudarla', '21:13', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (575, @jornada_id_156, '2025-06-30', 'BILBAO', 'ELENA', 32, 'GERENTE', '@elenamarquezugc', 566, 441, 'X2 SP', 0, '***CUESTIONARIO MUSICAL***// REC 18:28 - 19:31 //
 ARRANCAMOS CON XUSO ESCRIBIENDO POR MÓVIL PARA INSERTAR EN GRAFISMO LOS MENSAJES TIPO WHATSAPP QUE SE ESTÁ INTERCAMBIANDO CON ROBERTO. NOS CUENTA QUE ESTÁ HABLANDO CON ROBERTO, EL GANCHO Y NOVIO DE ELENA, Y DA PASO AL VÍDEO. ARRANCAMOS A ANDAR SIGILOSAMENTE HASTA GIRAR EN UNA ESQUINA EN LA QUE VEMOS A ELENA Y A SU PAREJA SENTADOS EN UN MURO TOMANDO ALGO. XUSO LES SALUDA Y ELENA NOS PRESENTA A ROBERTO, SU "VASQUITO". XUSO LE PREGUNTA QUÉ TAL ESTÁ, CÓMO HAN IDO ESTOS MESES Y QUÉ ES LO QUE MÁS ECHA DE MENOS DE SEVILLA. XUSO PIDE UN MÓVIL A PRODUCCIÓN Y VEMOS EL VÍDEO DE SUS AMIGAS. LE PONEMOS LA BANDA Y COMENZAMOS. (NO USAR LOS RECURSOS DE LA PAREJA DESPIDIÉNDOSE PORQUE ROBERTO SE QUEDARÁ CON NOSOTROS DURANTE EL CONCURSO). ELENA SUPERA LA PRIMERA PREGUNTA Y LE PREGUNTAMOS POR LAS REACCIONES A SU PERREO TELEVISADO. NOS CUENTA QUE LO VIO LA ABUELA DE SU NOVIO Y QUE LE ESCRIBIÓ SU EXSUEGRA Y HASTA PROFESORES DEL COLEGIO. EN LA SEGUNDA PREGUNTA, SEGUIMOS CAMINANDO Y XUSO Y ELENA BAILAN "DESPACITO". FINALMENTE, ELIGE A UN SEÑOR QUE NO SABE LA RESPUESTA Y SUPERA LA SEGUNDA PREGUNTA. TRAS ESTA PREGUNTA, NOS CUENTA CÓMO CONOCIÓ SU VASQUITO Y CÓMO ESTE LE PIDIÓ SALIR EN UN MONTE DE BILBAO. HACEMOS ENTRAR A ROBERTO, SE DAN UN BESO Y LA PAREJA SE MARCA UNAS SEVILLANAS. SUPERA LA TERCERA PREGUNTA Y NOS CUENTA QUE SIGUE CON ESE PROYECTO SECRETO QUE COMENTÓ EN EL PGM ANTERIOR Y QUE AÚN NO SE HA MATERIALIZADO, ASÍ QUE CON EL DINERO INTENTARÍA LLEVARLO A CABO Y LE COMPRARÍA UNA MOTO A SU NOVIO. SUPERA LA CUARTA PREGUNTA Y DECIDE JUGAR. ELIGE A UNA SEÑORA MAYOR, PERO CONTESTA "BORRIQUITO COMO TÚ" ASÍ QUE ELENA SE MARCHA CON LA CAMISETA.', 'Cristina', '2+', 'SEGUNDA OPORTUNIDAD. 
Mecánica corta. 
Cuestionario musical.', '26:18', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (576, @jornada_id_156, '2025-06-30', 'BILBAO', 'JULEN', 24, 'OPERARIO DE LOGÍSTICA', '@julensito_', 589, 345, 'X3 SP', 0, 'REC 19:34 - 20:33 // ARRANCAMOS JUNTO A UNA BOCA DEL METRO DE BILBAO TAMBIÉN CONOCIDA COMO FOSTERITO PORQUE DEBE SU NOMBRE AL ARQUITECTO NORMAN FOSTER. XUSO QUIERE COGER A ALGUIEN QUE VAYA A ENTRAR O SALIR DEL METRO, PERO UN CHICO JOVEN INTERRUMPE A XUSO Y DICE QUE QUIERE CONCURSAR, ASÍ QUE LO CAPTAMOS Y MICROFONAMOS. JULEN SUPERA LA PRIMERA PREGUNTA Y NOS CUENTA QUE ES OPERARIO DE LOGÍSTICA EN UNA EMPRESA EN ALEMANIA, QUE ECHA DE MENOS A SU FAMILIA Y, DESPUÉS DE CRUZAR EL PASO DE CEBRA, XUSO Y JULEN BROMEAN SOBRE SI ES MÁS DIFÍCIL EL EUSKERA O EL ALEMÁN. EN LA SEGUNDA PREGUNTA, EL ELEGIDO ACIERTA Y NOS VAMOS AL XUSOKER POR TRANSICIÓN. LE SALE UN CONTINÚA, LO CELEBRAMOS Y NOS CUENTA QUE EN SUS RATOS LIBRES LE GUSTA HACER SENDERISMO Y ESTAR EN LA MONTAÑA. SUPERA LA TERCERA PREGUNTA Y CON EL DINERO LE GUSTARÍA PAGARSE LOS ESTUDIOS Y AHORRAR PARA VOLVER A ESPAÑA. SUPERA LA CUARTA PREGUNTA Y DECIDE JUGAR, PERO EL ELEGIDO NO SABÍA EL LUGAR DE NACIMIENTO DE CRISTIANO RONALDO, ASÍ QUE JULEN SE MARCHA CON LA CAMISETA.', 'Cristina', '2', 'Arranque frente a los "fosteritos". Mecánica corta.', '21:54', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (577, @jornada_id_157, '2025-07-01', 'ZARAUTZ', 'GAIZKA', 27, 'MONITOR DE SURF', '@_gaizkasanmi', 601, 254, 'X19 N', 0, 'REC 11:05 - 12:09 // ARRANCAMOS EN EL PASEO MARÍTIMO DE ZARAUTZ CON XUSO CONTANDO QUE ESTAMOS EN UNA DE LAS MECAS DEL SURF EN 
ESPAÑA Y QUE LE GUSTARÍA TENER A UN SURFISTA COMO CONCURSANTE. LO VEMOS OTEANDO EL HORIZONTE Y SE FIJA EN UN CHICO QUE ESTÁ 
SALIENDO DEL AGUA. BROMEA CON GAIZKA, NOS ENSEÑA UN MOVIMIENTO BÁSICO DE SURF Y LO CAPTAMOS. EN LA PRIMERA PREGUNTA, EL ELEGIDO 
FALLA, SACAMOS LOS XUSOKER Y A GAIZKA LE SALE UN CONTINÚA. NOS CUENTA QUE ANTES DE DEDICARSE AL SURF JUGABA AL FÚTBOL, PERO TUVO 
QUE DEJARLO A RAÍZ DE DESARROLLAR UNA DIABETES TIPO 1. (SI ES POSIBLE, INTENTAR CORTAR CUANDO EXPLICA EL ORIGEN EMOCIONAL DE LA 
DIABETES TIPO 1). NOS EXPLICA CÓMO ES SU DÍA A DÍA CON ESTA ENFERMEDAD Y QUE CON LA AYUDA DE LA ALIMENTACIÓN Y EL EJERCICIO ES POSIBLE 
LLEVAR UNA VIDA NORMAL. EN LA SEGUNDA PREGUNTA, LA ELEGIDA ACIERTA POR CHIRIPA Y NOS VAMOS DIRECTOS A LA TERCERA PREGUNTA. EL 
TERCER ELEGIDO NO SABE LA RESPUESTA ASÍ QUE LLEGAMOS A LA CUARTA CON 200 EUROS. GAIZKA NOS CUENTA QUE LE GUSTARÍA INVERTIR EL 
DINERO EN UNA VIVIENDA CON SU NOVIA Y HACER UN VIAJE A HAWÁI O A LA POLINESIA FRANCESA PORQUE SON LAS MECAS MUNDIALES DEL SURF. EN 
LA CUARTA PREGUNTA, EL ELEGIDO ACIERTA Y GAIZKA DECIDE ARRIESGARSE LOS 200 EUROS. ABRIMOS LOS SOBRES, VEMOS EL X19, PERO A GAIZKA LE 
SALE UN X2. ELIGE A UNA SEÑORA QUE SE QUEDA MUY CERQUITA DE ACERTAR, PERO NO SUPERA LA PREGUNTA. OJO: UNA AMIGA DE GAIZKA 
LLAMADA MIREIA QUE TAMBIÉN PRACTICA SURF LE SALUDA DURANTE LA DESPEDIDA Y LA CAPTAMOS A VER SI TIENE MÁS SUERTE QUE GAIZKA. LOS 
ENLAZAMOS Y SERÁ LA SIGUIENTE CONCURSANTE, #578. DESPEDIMOS A GAIZKA Y NOS QUEDAMOS CON MIREIA.', 'Cristina', '1+', 'Nos saltamos una pregunta. 
¡OJO! La concursante #578 aparece en la despedida de Gaizka y será la siguiente concursante. DEBEN IR JUNTOS.', '24:17', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (578, @jornada_id_157, '2025-07-01', 'ZARAUTZ', 'MIREIA', 25, 'RECEPCIONISTA', '@mireiaarieta_', 611, 600, 'REC 12:30 - 13:10 // ARRANCAMOS CON MIREIA BROMEANDO SOBRE QUE NO SERÁ DÍFICIL HACERLO PEOR QUE GAIZKA Y COMENZAMOS A CONCURSAR. TRAS MUCHOS ELEGIDOS QUE NO QUERÍAN PARTICIPAR, MIREIA ELIGE A UNA MUJER QUE NO SABE LA RESPUESTA Y SACAMOS LOS XUSOKER (GRAFISMO: XUSO DICE "MIS GRAFISTAS YA ME HAN VUELTO A PONER HUMO EN LA CABEZA). NOS VAMOS A LA LLAMADA DE EMERGENCIA Y DECIDE LLAMAR A UNA COMPAÑERA DE TRABAJO QUE SÍ ACIERTA Y SUPERA LA PRIMERA PREGUNTA. NOS CUENTA QUE ES RECEPCIONISTA EN UNA ESCUELA DE SURF Y QUE TAMBIÉN LO PRACTICA, AUNQUE NO ES UNA GRAN EXPERTA. TAMBIÉN NOS EXPLICA QUE EN ZARAUTZ LLEGAN MUCHOS EXTRANJEROS PARA HACER SURF, SOBRE TODO DURANTE LOS MESES DE VERANO. SUPERA LA SEGUNDA PREGUNTA Y VAMOS DIRECTOS A LA TERCERA. CORTAR CUANDO LE PREGUNTA A XUSO SI LA PILARICA ES FAMOSA POR SUS FIESTAS. EN LA TERCERA, MIREIA ELIGE A UNA MUJER DE ASPECTO FILIPINO Y NO SUPERA LA TERCERA PREGUNTA. NOS CUENTA QUE INVERTIRÍA EL DINERO EN LA ENTRADA DE UN PISO. EN LA CUARTA PREGUNTA ELIGE A UN SEÑOR MAYOR MUY SIMPÁTICO QUE NOS SALVA LA MAÑANA Y QUE NO ACIERTA, ASÍ QUE MIREIA SUPERA LA CUARTA PREGUNTA Y DECIDE PLANTARSE.', 'Cristina', '1', 'Nos saltamos una pregunta. 
¡OJO! Esta concursante debe ir en escaleta después del 577', '16:41', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (579, @jornada_id_157, '2025-07-01', 'ZARAUTZ', 'ANDER', 21, 'ESTUDIANTE', '@_andertxioo', 612, 431, 'X4 SP', 0, 'REC 13:40 - 14:31 // ARRANCAMOS EN EL PASEO MARÍTIMO CON XUSO CONTANDO QUE ESTAMOS EN LA PLAYA MÁS LARGA DE LA COSTA VASCA, CON SUS MÁS DE 2.500 METROS DE LARGO. SEGUIDAMENTE, XUSO HABLA CON UN CHICO QUE TRABAJA EN LA TIENDA DE ALQUILER LOS TOLDOS PINTORESCOS DE ZARAUTZ Y DESPUÉS SE CRUZA CON ANDER. LO CAPTAMOS Y MICROFONAMOS. EN LA PRIMERA PREGUNTA, ELIGE A UN SEÑOR MAYOR QUE NO SABE LA RESPUESTA Y SACAMOS LOS XUSOKER. DESVELAMOS EL DEL VERRÉS, VOLVEMOS A JUGAR Y SUPERA LA PRIMERA PREGUNTA. ANDER NOS CUENTA QUE HA ESTUDIADO ELECTRICIDAD Y QUE AHORA ESTÁ BUSCANDO TRABAJO, ASÍ QUE APROVECHAMOS PARA QUE SE VENDA UN POQUITO Y PUEDA ENCONTRAR TRABAJO (GRAFISMO: HACER CV DE LAS CUALIDADES DE ANDER). XUSO LE APODA "ANDER EL CHISPAS" POR SU TRABAJO (GRAFISMO: ¿PODRÍAN SALIR CHISPAZOS DE ELECTRICIDAD DE ANDER DURANTE EL CONCURSO?). SUPERA LA SEGUNDA PREGUNTA Y VAMOS DIRECTOS A LA TERCERA, PERO NO LA SUPERA. EN CASO DE LLEVARSE LOS 50.000 EUROS, LE GUSTARÍA REGALARLE UN VIAJE A SU FAMILIA, AHORRAR PARA UNA VIVIENDA E INVITAR A LOS AMIGOS. EN LA CUARTA PREGUNTA, EL ELEGIDO CONTESTA "DIOS" Y CON 600 EUROS EN LA MANO, ANDER DECIDE LLAMAR A SU MADRE PARA PREGUNTARLE QUÉ DEBE HACER. LA MADRE LE ACONSEJA QUE SE PLANTE, PERO ANDER DECIDE JUGAR Y LE SALE EL X4. EL ELEGIDO NO SABE LA RESPUESTA Y ANDER SE MARCHA CON LA CAMISETA DEL PROGRAMA.', 'Cristina', '1+', 'Nos saltamos una pregunta.', '22:06', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (580, @jornada_id_157, '2025-07-01', 'ZARAUTZ', 'ALEXIS', 43, 'COMERCIAL', '@busolloyellow46', 610, 448, 'X3 SG', 3000, 'REC 16:11 - 16:57 // ARRANCAMOS PASEANDO POR LA CALLE Y XUSO SE FIJA EN LA FACHADA DEL CINE MODELO PORQUE LE RECUERDA AL CINE DE "CINEMA PARADISO". APROVECHA PARA PREGUNTARLE A LOS MIEMBROS DEL EQUIPO CUÁL FUE LA PRIMERA PELÍCULA QUE VIERON EN EL CINE. TAMBIÉN SE LO PREGUNTA A UN SEÑOR Y LUEGO, A UN TRABAJADOR DEL MISMO CINE. DESPUÉS, UN CAMIÓN DE LA BASURA PASA POR NUESTRO LADO Y XUSO SALUDA AL CONDUCTOR. POR ÚLTIMO, NOS ENCONTRAMOS CON ALEXIS QUE LLEVA TATUADA LA CARA DE MARILYN MONROE, "LA VIDA ES BELLA" Y A PETER PAN. LO CAPTAMOS Y MICROFONAMOS. EL PRIMER ELEGIDO NO SABÍA LA RESPUESTA Y SACAMOS LOS XUSOKER. ALEXIS DESVELA EL "CONTINÚE", LO CELEBRAMOS Y NOS CUENTA QUE NACIÓ EN ITALIA SU PADRE ES VENECIANO Y SU MADRE DE PAMPLONA, ASÍ QUE SABE HABLAR ITALIANO Y EUSKERA A LA PERFECCIÓN. SUPERA LA SEGUNDA PREGUNTA Y VAMOS DIRECTOS A LA TERCERA. EN LA TERCERA, ELIGE A UN CHICO QUE TIENE UN AMIGO DE GUINEA ECUATORIAL Y ACIERTA LA PREGUNTA. ALEXIS NOS CUENTA QUE INVERTIRÍA EL DINERO EN UNA CASA DE PROPIEDAD PORQUE LA VIVIENDA EN ZARAUTZ ESTÁ UN POCO CARA. SUPERA LA CUARTA PREGUNTA Y DECIDE JUGAR SIN PENSÁRSELO DOS VECES. EL ÚLTIMO ELEGIDO NOS HACE SUFRIR UNOS SEGUNDOS PORQUE NO LE VENÍA LA RESPUESTA, PERO FINALMENTE DICE MANACOR Y ALEXIS SE MARCHA CON 3.000 EUROS.', 'Cristina', '2+', 'Arranque frente al CIne Modelo (guiño Cinema Paradiso).
Nos saltamos una pregunta.', '23:36', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (581, @jornada_id_158, '2025-07-02', 'BILBAO', 'NEKANE', 33, 'MODELO', '@nekane_loveyourself', 614, 450, 'X2 SP', 0, '***CUESTIONARIO MUSICAL*** // REC 10:13 - 11:00
 ARRANCAMOS CON XUSO ENTRANDO EN EL MERCADO DE LA RIBERA PORQUE HA EMPEZA A CAER SIRIMIRI EN LA CIUDAD Y APROVECHANDO QUE ESTAMOS EN BILBAO 
Y AQUÍ EL ATHLETIC CLUB SE VIVE Y SE SIENTE, XUSO SE PROPONE ENCONTRAR A ALGUIEN QUE LE CANTE EL GRITO DE INICIO DEL HIMNO DEL ATHLETIC. COMIENZA A 
CAMINAR, SALUDA A UNA SEÑORA QUE ESTÁ HACIENDO UN VÍDEO PARA SU PADRE Y SE FIJA EN DOS PARADAS: UNA FRUTERÍA Y UNA CARNICERÍA QUE TIENEN LAS 
BANDERAS DEL ATHLETIC COLGADAS EN LA PARED. PRIMERO SE ACERCA AL FRUTERO, UN CHICO JOVEN QUE LLEVA EL ESCUDO Y EL LEÓN TATUADOS Y LE PIDE QUE LE 
HAGA EL GRITO. Y LUEGO, NOS FIJAMOS EN EL CARNICERO, QUE TAMBIÉN NOS HACE EL GRITO DEL ATHLETIC. XUSO LES PREGUNTA SI QUIEREN CONCURSAR, PERO 
DEBEN QUDARSE EN LA PARADA. SEGUIMOS CAMINANDO Y SE FIJA EN UNA CHICA DEL PELO ROSA, QUE TAMBIÉN NOS HACE EL GRITO Y LA CAPTAMOS. EN LA PRIMERA 
PREGUNTA, EL ELEGIDO CONTESTA TRAP, ASÍ QUE SACAMOS LOS XUSOKER, SALE EL "CONTINÚA" Y LO CELEBRAMOS. NOS CUENTA QUE ES MODELO CURVY Y HACE UN 
ALEGATO POR LA DIVERSIDAD CORPORAL (GRAFISMO: ¿PODRÍAMOS ENMARCAR EL MOMENTO ALEGATO? PROPONGO UN MARCO ESTILO PARED DE 
LADRILLO/ESTÉTICA CALLEJERA CON MENSAJES EN LAS PAREDES DEL TIPO "LOVE YOURSELF"/ "PERDAMOS ODIO, NO PESO" / "DIVERSOS Y ORGULLOSOS" / "POR LA 
DIVERSIDAD CORPORAL"). NO SUPERA LA SEGUNDA PREGUNTA Y NOS CUENTA QUE ES MADRE MONOMARENTAL DE UN NIÑO QUE SE LLAMA IAN Y QUE ESTÁ 
INTENTANDO EDUCARLO DE LA MEJOR MANERA POSIBLE PARA QUE CREZCA CON VALORES. SUPERA LA TERCERA PREGUNTA Y CON EL DINERO LE GUSTARÍA CUMPLIR EL 
SUEÑO DE SER ACTRIZ DE TELENOVELA. XUSO RECUPERA A LA ELEGIDA EN LA TERCERA PREGUNTA PARA QUE NEKANE Y AINHOA INTERPRETEN UNA ESCENA DE 
TELENOVELA VENEZOLANA. NO SUPERA LA CUARTA PREGUNTA Y DECIDE JUGARSE LOS 400 EUROS. LA QUINTA ELEGIDA NO SE SABÍA LA CANCIÓN DE MACHÍN Y 
NEKANE SE MARCHA CON LA CAMISETA DEL CLUB DE CONCURSANTES.', 'Cristina', '2-', 'Mecánica corta. 
Arranque en el Mercado de la Ribera con acting himno del Atleti. 
Candidata Segunda Oportunidad.', '24:33', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (582, @jornada_id_158, '2025-07-02', 'BILBAO', 'ERRAPEL', 60, 'CELADOR', 'NO TIENE', 599, 400, 'REC 11:49 - 12:29 //
 ARRANCAMOS EN LA PLAZA NUEVA Y CRISTINA INTERRUMPE A XUSO PARA PROPONERLE UN JUEGO. LE ENTREGA UN TARJETÓN CON TRES PALABRAS EN 
EUSKERA Y DEBE ENCONTRAR A TRES PERSONAS QUE LE DIGAN EL SIGNIFICADO DE CADA UNA DE ELLAS (PINPILINPAUXA, PIRRILERA Y CHIRENE). DEBE 
DARSE PRISA PORQUE SOLO TIENE UN MINUTO Y TENEMOS QUE BUSCAR AL SIGUIENTE CONCURSANTE. XUSO PARA A UN CAMARERO, DESPUÉS A UN 
COCINERO Y DESPUÉS A UN HOMBRE QUE SE LLAMA ERRAPEL Y NOS LLAMA LA ATENCIÓN POR SU MISTICISMO. LO CAPTAMOS Y MICROFONAMOS. 
SUPERA LA PRIMERA PREGUNTA Y NOS CUENTA QUE ES CELADOR Y QUE EN BILBAO SE VIVE MUY BIEN PORQUE "AQUÍ SE HACE TODO MUY BIEN".  EN 
LA SEGUNDA PREGUNTA, LA ELEGIDA ACIERTA Y SACAMOS LOS XUSOKER. (OJO: LA SEGUNDA ELEGIDA LLEVABA UNA CAMISETA ROJA COMO LA DEL 
EQUIPO, XUSO LE HACE UN COMENTARIO AL RESPECTO Y NOS ENSEÑA LA CAMISETA DE LA CNT. LEVANTAR SI TIENE BUEN CORTE). ERRAPEL ELIGE LA 
CARTA DE "RECICLA", ASÍ QUE VOLVEMOS A ELEGIR A OTRA PERSONA Y SUPERA LA SEGUNDA PREGUNTA. VAMOS DIRECTOS A LA TERCERA PREGUNTA 
Y NO LA SUPERA. NOS CUENTA QUE CON EL DINERO LE GUSTARÍA ARREGLAR LA HABITACIÓN Y COMPRARSE UNA CAMA PORQUE LA SUYA ESTÁ 
GASTADA DE TANTA ACTIVIDAD. NO SUPERA LA CUARTA PREGUNTA Y SE PLANTA PORQUE CON 400 EUROS TIENE DE SOBRA PARA UNA CAMA 
CIRCULAR.', 'Cristina', '1+', 'Mecánica corta. 
Arranque en Plaza Nueva con acting significado palabras en euskera. 
Nos saltamos una pregunta.', '19:38', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (583, @jornada_id_158, '2025-07-02', 'BILBAO', 'SENDOA', 40, 'ANIMADOR SOCIOCULTURAL', '@sendoa.a', 604, 231, 'X12 N', 0, 'REC 13:11 - 14:00 // ARRANCAMOS EN LA PLAZA NUEVA CON XUSO LLEVANDO UNA BANDEJITA CON DOS CAROLINAS PARA LOS MIEMBROS DEL EQUIPO. NOS CUENTA QUE ES EL DULCE MÁS TÍPICO DE BILBAO Y JAIME, GONZALO Y CRISTINA LE ESPERAN SENTADOS, PERO XUSO NO HA TRAÍDO CUCHARAS Y NO SABEMOS CÓMO COMERNOS LA CAROLJNA. XUSO SE FIJA EN SENDOA Y LE PREGUNTA CÓMO SE COME ESTE DULCE. NOS CUENTA QUE SE COGEN POR EL HOJALDRE Y SE COMEN DESDE LA PUNTA HASTA LA BASE. SENDOA NOS EXPLICA LA HISTORIA DE ESTE DULCE, XUSO SE LO METE ENTERO EN LA BOCA Y SE QUEDA CON LA CARA MANCHADA DE MERENGUE. LE LIMPIAMOS LA BOCA A XUSO Y CAPTAMOS A SENDOA. (CLIP DE MICROFONADO: GONZALO PROBANDO LA CAROLINA Y MANCHÁNDOSE TODA LA BOCA). EL PRIMER ELEGIDO NO ACIERTA, SACAMOS EL XUSOKER Y NOS VAMOS A LA LLAMADA DE EMERGENCIA. SENDOA DECIDE LLAMAR A UNA AMIGA QUE HA VIAJADO MUCHO Y SUPERA LA PRIMERA PREGUNTA. NOS CUENTA QUE TRABAJA EN LA CASA DE LA CULTURA DE SANTURCE ORGANIZANDO EXPOSICIONES Y QUE POR ESO, SUS AMIGOS LE LLAMAN "EL MARQUÉS". BROMEAMOS CON NACHO PORQUE ÉL TAMBIÉN ES EL "MARQUÉS" DEL GRUPO. SUPERA LA SEGUNDA Y LA TERCERA PREGUNTA. NOS CUENTA QUE CON EL DINERO LE GUSTARÍA "DIVORCIARSE DEL BANCO" Y MONTAR UN FESTIVAL DE MÚSICA EN SANTURCE (GRAFISMO: ¿PODRÍAMOS HACER EL CARTEL DE UN FESTIVAL TIPO "HORTERALIA" CON LOS NOMBRES DE LOS ARTISTAS QUE PARTICIPARÍAN A MEDIDA QUE SENDOA LOS 
MENCIONA?). NO SUPERA LA CUARTA PREGUNTA Y DECIDE JUGAR. ABRIMOS LOS SOBRES. LA QUINTA ELEGIDA SABÍA LA RESPUESTA Y SENDOA SE MARCHA CON LA CAMISETA DEL CLUB DE CONCURSANTES.', 'Cristina', '1+', 'Mecánica corta. 
Arranque con Xuso ofreciendo Carolinas (dulce típico de Bilbao) al equipo. 
Nos saltamos una pregunta.', '21:45', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (584, @jornada_id_158, '2025-07-02', 'BILBAO', 'MARI JOSE', 48, 'VIGILANTE', '@jositapradomendez', 608, 459, 'X3 SP', 0, 'REC 14:21 - 15:02 // ARRANCAMOS CON XUSO EN UNA DE LAS CALLES DEL CASCO VIEJO CONTANDO QUE EL EUSKERA ES UN IDIOMA MILENARIO Y FASCINANTE QUE NO TIENE NADA QUE VER NI CON EL CASTELLANO NI EL INGLÉS NI EL ITALIANO PORQUE ES ÚNICO Y COMO LOS IDIOMAS HAY QUE CUIDARLOS Y USARLOS, XUSO VA A PREGUNTARLE A LA GENTE PALABRAS EN EUSKERA PARA USARLAS EN EL DÍA A DÍA. PRIMERO HABLA CON UNA MUJER MUY SIMPÁTICA QUE LE ENSEÑA UN PAR DE PALABRAS Y DESPUÉS CON MARI JOSE, QUE LE DICE EN EUSKERA "VAMOS A TOMARNOS UNOS PINTXOS". LA CAPTAMOS Y MICROFONAMOS. SUPERA LA PRIMERA PREGUNTA Y XUSO LE PREGUNTA SOBRE EL EUSKERA Y MARI JOSE NOS CUENTA QUE NO SABE DEMASIADO PORQUE CUANDO ELLA ESTUDIÓ LAS ASIGNATURAS ERAN EN CASTELLANO, PERO AHORA LOS NIÑOS APRENDEN EUSKERA DESDE PEQUEÑOS. DESPUÉS, NOS CUENTA QUE ES VIGILANTE DE SEGURIDAD EN UNA COMPAÑÍA DE TELEFONÍA. SUPERA LA SEGUNDA PREGUNTA. REPETIMOS TRES VECES LA FORMULACIÓN DE LA TERCERA PREGUNTA POR RUIDO DEL MÓVIL Y PRONUNCIACIÓN. EN LA TERCERA PREGUNTA, LA ELEGIDA NO ACIERTA Y SACAMOS LOS XUSOKER. APARECE EL "CONTINÚA", LO CELEBRAMOS, Y NOS CUENTA QUE CON EL DINERO COMPRARÍA UN COCHE PARA LA FAMILIA. SUPERA LA CUARTA PREGUNTA Y DECIDE JUGAR, PERO LA ELEGIDA SABÍA LA RESPUESTA, ASÍ QUE SE MARCHA CON LA CAMISETA DEL CLUB DE CONCURSANTES. (CORTAR CUANDO DICE QUE NO SABE CÓMO SE DICE "ABRAZO" EN EUSKERA).', 'Cristina', '1', 'Mecánica corta. 
Nos saltamos una pregunta.', '20:45', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (585, @jornada_id_159, '2025-07-04', 'SEGOVIA', 'MARÍA', 48, 'AGENTE DE VIAJES', '@mariadeanma', 622, 585, 'X6 SP', 0, '10:38 - 11:26. Xuso está con el diablo de Segovia y cuenta su leyenda, nos pregunta por qué venderíamos nuestra alma al diablo y se da cuenta de María le está mirando y le pregunta. Ella responde que por concursar con él y se convierte en concursante. Arrancamos en el acueducto y nos dice que iba de camino a comprarse unos bañadores porque se le han estropeado en Mauricio y se va de viaje la semana que viene. Xuso le formula la primera pregunta y no tiene ni idea, pero coge a una chica joven de 18 años llamada Nerea que acierta. María nos cuenta que viaja mucho porque tiene una agencia de viajes y que es su pasión, además tiene dos hijos que también viajan. En la segunda tampoco sabe la respuesta y coge a una anciana extraña que responde "escritores", por lo que gana los 400. Nos vamos directos a la tercera, y de nuevo María no lo sabe y asegura que nunca ha estado en ese país del que hablamos y que ella sabe poco de gastronomía. Coge a Patricia que está desayunando y no tiene ni idea, así que sacamos los XUSÓQUERS y le sale el CONTINÚA, ante el extremo regocijo del equipo. Nos cuenta que con el dinero se iría a Japón y a Maldivas, y al formular la cuarta no la entiende bien, cree que la respuesta es "nube", así que Xuso se la repite y ya se pone a buscar, pero da muchísimas vueltas hasta que coge a una señora búlgara que no sabe la respuesta. Decide arriesgarse y le sale un x6. Se juega 6000€, pero coge a un señor que no tiene ni idea y se va a casa con la camiseta pero feliz de conocer a Xuso.', 'Adriana', '2+', 'Muy efusiva y dando siempre botecitos.
Candidata Segunda Oportunidad, aunque sea para viajar.', '22:08', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, duracion, valoracion_final) VALUES (586, @jornada_id_159, '2025-07-04', 'SEGOVIA', 'PACO', 44, 'TRABAJADOR DE LA ONCE', 'NO TIENE', 598, 1000, '11:51 - 12:30. Xuso está en la casa de los picos de Segovia, y cuenta a ver cuántos picos hay. Como no lo sabe, busca a alguien que se lo diga y se para a charlar con unos taiwaneses (revisar derechos). Luego habla con un músico ambulante que no lo sabe, pero le toca su instrumento y luego habla con Paco que se sabe el dato: 617. Le cuenta que viene de trabajar, que es trabajador de la ONCE y se va ya a casa. Xuso le hace concursante y de la primera pregunta no sabe nada. Para a una choica joven, que odia el deporte, pero acierta. Nos cuenta que está ne la ONCE porque tuvo una lesión en la espalda y le dieron la discapacidad, que tiene dos hijos y uno estudia ingenieria aeroespacial en León y que le viene genial el dinero. En la segunda coge a un chico que acierta, sacamos XUSÓQUER, y le sale el RECICLA. Para a Irina, que es rumana y no lo sabe, así que gana. Vamos directos a la tercera y no sabe la respuesta, aunque es fan de la serie. Para a un señor de La Habana que es muy fan de la serie y la ve en Cuba, y por supuesto acierta y nos hace algunas de las expresiones de Amador. Paco nos dice que aparte de los estudios de su hijo, se quitaría la hipoteca con 50k. En la cuarta, le parece tan fácil que no sabe a quién coger, pero ve a un vecino del barrio que no tiene casi dientes y le elige. El vecino no lo sabe y Paco se gana los mil y se planta para invertirlos en la matrícula de la universidad y el piso en León de su hijo.', 'Adriana', '1', '19:24', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, duracion, valoracion_final) VALUES (587, @jornada_id_159, '2025-07-04', 'SEGOVIA', 'SALVA', 52, 'FISIOTERAPEUTA', '@salvadorluciomartin', 609, 473, 'X7 SG', 4200, '13:20 - 14:00. Xuso está al lado de la estatua de Machado recitando (propongo METER PLANOS BONITOS DE SEGOVIA PARA CUBRIR PARTE DEL POEMA, QUE ES MUY LARGO). Comenta que Machado vivió en Segovia y le quiere hacer un homenaje, así que busca a alguien que le recite poemas del poeta sevillano. Para a una chica llamada María que le dice "caminante no hay camino" y Xuso le invita a concursar, pero ella tiene que irse a trabajar. Xuso le dice que estarán más tiempo en segovia, que vuelva a buscarle (OJO: SERÁ CONCURSANTE 588). El siguiente al que para es a Salva que viene de comprar el pan y le dice el mismo poema, Xuso le invita a caminar con él y concursar. La primera pregunta le parece simple y coge a una señora que dice no tener estudios, pero acierta. Salva nos cuenta que es fisioterapeuta y trabaja con e una residencia de mayores, y aprovecha para hacer un alegato por los mayores. En la segunda coge a una dependienta de una tienda, que está con otra que ya respondió en Segovia con una concursante. Le pide que aconseje a su compañera. BUSCAR Y METER EL CORTE DE LA VEZ ANTERIOR. La elegida, Yolanda, no lo sabe y Salva gana los 400. Vamos directos a la tercera y no tiene ni idea, busca a una señora mayor, pero cambia de opinión y coge a una jovencita que dice "Beyoncé". Vamos a los XUSÓQUERS, y le sale un CONTINÚE. Nos cuenta que quiere el dinero para llevar a su hija de diez años a Disney, porque es un padre separado, tiene custodia compartida y habla de que está en una asociación que lucha por la custodia compartida. En la cuarta no sabe a quién elegir, es demasiado fácil y coge a Alba que sabe la respuesta. Con los 600 se arriesga, porque quiere cumplir el sueño de su hija y le sale un x7. Busca a alguien enchaquetado y elige a un señor elegante que no tiene dudas al responder, y le hace ganar los 4200€.', 'Adriana', '2-', '22:23', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (588, @jornada_id_159, '2025-07-04', 'SEGOVIA', 'MARÍA', 28, 'AUXILIAR ADMINISTRATIVO', '@clavedeversos_', 605, 474, 'X9 SP', 0, '***CUESTIONARIO MUSICAL***
14:22 - 15:06. Xuso está muy contento con el imán que se ha comprado y aparece María (que sale del concursante 587. METEMOS FLASHBACK) corriendo porque ha pedido salir del trabajo para concursar porque necesita el dinero. Ha sido mamá hace un año, se casó el año pasado y le viene muy bien para su economía familiar. Xuso la hace concursante. Arrancamos y en la primera busca a alguien como su madre, coge a Mari Carmen que es fan de La Pantoja, y responde "maldito", así que vamos a los XUSÓQUERS y le sale la LLAMADA. María llama a su madre, Rosa. Rosa adivina en el último segundo y nos canta la canción. Nos cuenta María que trabaja en una inmobiliaria que ayuda a los estudiantes a buscar piso y que se casó con el hermano de una amiga suya, con el que lleva 9 años. En la segunda no tiene ni idea, coge a una dependienta, fan de Rihanna, y no sabe la respuesta. Lo celebra cantando Rihanna con Xuso. Vamos directos a la tercera y pregunta a una chica que está tomando algo en un bar y nos canta la canción, muy animada. Gana los 600 y nos explica que su pasión es la escritura y ha escrito varios cuentos ninfantiles. Cortamos cuando no se le ocurre ningún verso que decir. Para la cuarta coge a otra camarera que está hablando por teléfono con un amigo de Xuso. La chica pasa mucha vergüenza, pero responde correctamente. Con los 600, María se arriesga y busca a una señora para que responda. Unas cuantas se niegan, hasta que llegamos a una que está de comida con su familia y responde "Madrid", así que María se va a casa con la camiseta.', 'Adriana', '2', 'Cuestionario musical.
Debería escaletarse después del 587, ya que aparece en esa grabación.', '23:15', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, duracion, valoracion_final) VALUES (589, @jornada_id_160, '2025-07-07', 'LEGANÉS', 'AITOR', 29, 'ASESOR UNIVESITARIO', '@aitor.granado', 563, 433, 'X2 SP', 0, 'TC IN: 11:11 TC OUT: 11:55
ESTAMOS EN EL BABYLON PARK Y XUSO PRUEBA LAS MAQUINITAS DE SACAR PELUCHES SIN ÉXITO ALGUNO. ENTRO A DECIRLE QUE QUÉ HACE Y ME PIDE QUE LE DEJE INTENTARLO PORQUE QUIERE UN PELUCHE PARA SU SOBRINO. FALLA Y LE DIGO QUE NO PUEDE GASTARSE EL PRESUPUESTO DEL PROGRAMA EN PELUCHES, QUE ESTO ES PARA LOS CONCURSANTES. NOS ENCONTRAMOS A UN CHICO EN OTRA MÁQUINA SACANDO GOMINOLAS Y LE PROPONE CONCURSAR EN EL PROGRAMA. SUPERA LA PRIMERA PREGUNTA Y AITOR NOS CUENTA QUE ES ASESOR UNIVERSITARIO Y NOS HABLA UN POQUITO DE LAS FUNCIONES DE SU TRABAJO. LA SEGUNDA TAMBIÉN LA SUPERA Y XUSO LE PREGUNTA POR SU FAMILIA. NOS CUENTA QUE TIENE UNA HERMANA QUE ADOPTARON EN CHINA PORQUE ÉL NACIÓ PREMATURO Y SU MADRE NO PUDO TENER MÁS HIJOS DE FORMA NATURAL. NOS HABLA DEL VIAJE A CHINA PARA RECOGERLA. LA TERRCERA NO LA SUPERA, LE SALE EL RECICLA Y LA SEGUNDA ELEGIDA TAMPOCO LO SABE. QUIERE EL DINERO PARA LLEVAR A DISNEY A SU HERMANA PORQUE LE HACE MUCHA ILUSIÓN. SUPERA LA CUARTA Y SE LA JUEGA, LE SALE EL X2 Y LA CHICA A LA QUE ELIGE RESPONDE PERO SE EQUIVOCA EN LOS ELEMENTOS QUÍMICOS. AITOR SE VA CON LA CAMISETA.', 'Leandro', '2', '20:27', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, duracion, valoracion_final) VALUES (590, @jornada_id_160, '2025-07-07', 'LEGANÉS', 'ÁNGEL', 61, 'VIGILANTE DE SEGURIDAD', 607, 461, 'X9 N', 3000, 'TC IN: 12:17 TC OUT: 12:52
XUSO ARRANCA CON UNA BOLSA DE TORREZNOS QUE HA COMPRADO Y LE OFRECE A LOS MIEMBROS DEL EQUIPO COMO YA ES HABITUAL. VE A UNA PAREJA QUE VA A ENTRAR A UNA TIENDA Y LE OFRECE UNOS TORREZNITOS Y ELLOS COGEN GUSTOSAMENTE. ÁNGEL LE CUENTA QUE HAN VENIDO A COMPRAR UNAS ZAPATILLAS DE DEPORTE PARA CORRER. LES PROPONE CONCURSAR, PERO SU MUJER DICE QUE SE VA A QUEDAR MIRANDO TIENDAS, ASÍ QUE ÁNGEL ES EL QUE SE ANIMA. SUPERA CON ÉXITO LA PRIMERA PREGUNTA Y NOS HABLA DE SU TRABAJO: ES VIGILANTE DE SEGURIDAD EN UN CENTRO COMERCIAL DE VALLECAS. PASAMOS A LA SEGUNDA PREGUNTA Y TAMBIÉN LA SUPERA. XUSO LE PREGUNTA POR EL TEMA DE CORRER Y ÁNGEL LE CUENTA QUE TODA LA FAMILIA HACE CARRERAS DE OBSTÁCULOS Y VIAJAN PARA ELLO, AUNQUE DEPENDE DE LA ECONOMÍA VAN AL CAMPEONATO O NO. PARA LA TERCERA COGE A UN CHICO QUE DICE LA RESPUESTA CORRECTA DE PURA CHIRIPA (CABE RESALTAR QUE ÁNGEL CELEBRA CADA ACIERTO CON MUCHA EUFORIA). NOS CUENTA QUE QUIERE EL DINERO PARA VIAJAR A FINLANDIA PARA HACER EL CAMPEONATO DE CARRERA DE OBSTÁCULOS. SUPERA TAMBIÉN LA CUARTA Y SE LA JUEGA, ABRIMOS SOBRES, HABÍA UN X9 PERO ÉL COGIÓ EL X3. ELIGE A UN CHICO QUE SABE LA RESPUESTA Y GANA SUS 3000 EUROS. SU MUJER ENTRA A CELEBRARLO CON ÉL.', 'Leandro', '3', '22:05', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (591, @jornada_id_160, '2025-07-07', 'LEGANÉS', 'DENITSA', 30, 'GESTORA', '@dalonsoh_', 567, 400, 'AQUÍ VAN LAS PÍLDORAS. LA DEL ABANICO NO VALE POR PUBLICIDAD. TC: 13:22
TC IN: 13:22 TC OUT: 14:03
XUSO HACE REFERENCIA AQUÍ AL CENTRO COMERCIAL Y LO NOMBRA (POR LOS ACUERDOS ESTOS DE PRODU). SE CRUZA CON UNA CHICA QUE ESTÁ BUSCANDO EL REGALO DE SU MADRE PORQUE ES SU CUMPLEAÑOS Y LE OFRECE CONCURSAR. DENITSA ACEPTA Y NOS PONEMOS EN MARCHA. LA PRIMERA NO LA SUPERA, ELIGE A UNA SEÑORA QUE DICE QUE HOY ESTÁ TORPE...TANTO QUE SU RESPUESTA FINAL ES "DE PUTA MADRE", TAL CUAL. NO ENTENDIÓ LA PREGUNTA AUNQUE LA REPETIMOS MIL VECES. LE SALE EL RECICLA Y LA SEGUNDA ELEGIDA SÍ LO SABE. DENITSTA TRABAJA EN BANCA, VIVE POR LA ZONA Y ADEMÁS TIENE PAREJA, UNA CHICA CON LA QUE LLEVA 6 AÑOS. LA SEGUNDA SÍ QUE LA SUPERA Y XUSO LE PREGUNTA POR SU NOMBRE YA QUE ES MUY ORIGINAL. LA CONCURSANTE RESPONDE QUE ES DE ORIGEN BÚLGARO Y SIGNIFICA "PRIMERA ESTRELLA DEL AMANECER". LA TERCERA PREGUNTA TAMPOCO LA SUPERA Y NOS CUENTA QUE CON EL DINERO SE IRÍA DE VIAJE A JAPÓN CON SU CHICA Y CON SU FAMILIA. LA CUARTA PREGUNTA TAMPOCO ES SUPERADA Y DENITSA DICE QUE SE PLANTA PORQUE CON 400 EUROS TIENE PARA HACERLE UN BUEN REGALO A SU MADRE QUE SE LO MERECE TODO.', 'Leandro', '2', 'Interior centro comercial', '20:04', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (592, @jornada_id_160, '2025-07-07', 'LEGANÉS', 'SARA', 36, 'EDUCADORA INFANTIL', '@sarittamtnez', 579, 426, 'X41 N', 800, 'TC IN: 15:44 TC OUT: 16:34
XUSO HABLA CON LA GENTE DEL CENTRO COMERCIAL QUE ESTÁ COMIENDO Y LLEGA A UNA PAREJA QUE TAMBIÉN VA A COMER. SERÁ SARA LA QUE CONCURSE Y SE DESPIDE DE SU CHICO. EMPEZAMOS EL CONCURSO Y NO LA SUPERA, LE SALE LA LLAMADA DE EMERGENCIA Y LLAMA A SU SUEGRO QUE ES COCINITAS. NOS CUENTA QUE LLEVA EN MADRID 16 AÑOS PORQUE VINO A ESTUDIAR, YA QUE ES DE LA MANCHA Y SE SIENTE MUY ORGULLOSA. NOS CUENTA SU HISTORIA DE AMOR Y TAMBIÉN QUE TIENEN UN NIÑO DE CINCO AÑOS. PASAMOS A LA SEGUNDA Y ELIGE A UNA CHICA HONDUREÑA QUE NO SABE EL NOMBRE VERDADERO DE BRUNO MARS Y ACUMULA 400 EUROS. SARA NOS CUENTA QUE ACABA DE APROBAR UNA OPOSICIÓN COMO ADMINISTRATIVA DEL ESTADO Y HACE HINCAPIÉ EN LO COMPLICADO QUE HA SIDO. LA TERCERA NO LA SUPERA PORQUE EL CHICO DICE QUE, AL SER TAN DIFÍCIL LA PREGUNTA, PENSABA QUE TENÍA QUE NO SABERLA, AUNQUE CONOCÍA LA RESPUESTA. SARA QUIERE EL DINERO PARA HACERSE UN VIAJE CON LA FAMILIA AL COMPLETO Y, SI ES MÁS, CAMBIAR EL PISO POR UN CHALET. NO SUPERA LA CUARTA Y SE QUEDA EN 400, MULTIPLICA Y ABRIMOS EL X41 QUE HA DEJADO PASAR, ELLA HA ELEGIDO EL X2. LA CHICA SELECCIONADA LA SABE Y GANA SUS 800 EUROS.', 'Leandro', '2+', 'Se menciona que hemos estado en Hellín, por lo que tendrá que ir en programación después de, al menos, uno de esta localidad.', '20:32', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (593, @jornada_id_161, '2025-07-10', 'CARABANCHEL', 'SAMI', 32, 'MAESTRO', 'NO TIENE', 590, 1000, 'TC IN: 10:03      TC OUT: 10: 44   ***A LAS 9:43 EMPIEZA LA GRABACIÓN DE LAS PÍLDORAS DE ESE DÍA 
XUSO SALE DEL METRO OPORTO Y DICE QUE NOS HEMOS TRASLADADO AL PAÍS VECINO Y QUIERE HABLAR CON LA GENTE DE ALLÍ. HABLA CON VARIOS TRANSEÚNTES CON PALABRAS Y ACENTO PORTUGUÉS HASTA QUE LLEGA A SAMI, QUE LE RESPONDE EN PORTUGUÉS PORQUE SABE UN POQUITO. CONOCE EL PROGRAMA Y ACEPTA RÁPIDO CUANDO LE PROPONE CONCURSAR. SUPERA LA PRIMERA PREGUNTA Y NOS CUENTA QUE ES DEL BARRIO DE TODA LA VIDA, QUE HA VENIDO A DAR UNA VUELTA Y HABLAMOS DE SU HISTORIA. SU PADRE ES SIRIO Y VINO A ESPAÑA HUYENDO DEL SERVICIO MILITAR Y AQUÍ CONOCIÓ A SU MADRE. HABLA DE LA SITUACIÓN DEL PAÍS Y COMENTA QUE LE GUSTARÍA IR AHORA QUE ESTÁ TODO MEJOR. SUPERA LA SEGUNDA GRACIAS A UN SEÑOR QUE COGE DE UNA FURGONETA Y SE BAJA A AYUDARLE. EL SEÑOR LA SABÍA, PERO PENSABA QUE TENÍA QUE NO SABERLA PORQUE ES SEGUIDOR DEL PROGRAMA. SAMI ES PROFESOR DE EDUCACIÓN FÍSICA Y NOS HABLA DE SU TRABAJO. SUPERA LA TERCERA Y NOS CUENTA QUE QUIERE EL DINERO PARA INVERTIR EN LA CASA DE NAVALCARNERO QUE SE HA COMPRADO CON SU MUJER, CON LA QUE LLEVA DESDE LOS 18 AÑOS Y CON LA QUE TIENE UN BEBÉ. SUPERA TAMBIÉN LA CUARTA Y DICE QUE EN LA TELE CUANDO LO VE SIEMPRE PIENSA QUE JUGARÍA, PERO TENIÉNDOLOS EN LA MANO, NO. SE PLANTA. BLUREAR A LA ACOMPAÑANTE DE LA CUARTA ELEGIDA QUE NO FIRMA', 'Leandro', '3', 'Mecánica corta. 
Arranque simulando que estamos en Oporto.', '20:09', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (594, @jornada_id_161, '2025-07-10', 'CARABANCHEL', 'ANDREA', 24, 'PELUQUERA', '@andrea__25', 594, 600, 'TC IN: 10:48    TC OUT: 11:51
 ESTAMOS EN LA PLAZA Y SACAMOS UN BALÓN PARA HACER TOQUES, XUSO CUENTA QUE DE AQUÍ ES JENNIFER HERMOSO. SACA EN ESCENA A QUINO, UN CÁMARA QUE TUVIMOS AL PRINCIPIO DEL PROGRAMA Y QUE AHORA VIVE EN ARABIA SAUDÍ GRABANDO PARTIDOS DE FÚTBOL. (IGUAL HABRÍA QUE RESCATAR ALGÚN FLASHBACK). JUGAMOS A LOS TOQUES Y YO SOLO HAGO UNO. UN ESPONTÁNEO CONSIGUE HACER 8 Y VEMOS A UNA CHICA QUE SE ACERCA A XUSO Y TAMBIÉN HACE UN TOQUE. XUSO LE PROPONE CONCURSAR Y LE DICE QUE SÍ. SUPERA LA PREGUNTA (OMITIR TODO LO DEL BANCO DE LAS SEÑORAS QUE NOS DICEN QUE NO) Y NOS CUENTA QUE TRABAJA EN UNA PELUQUERÍA Y QUE QUIERE FORMARSE PARA EL TEMA DE MEDICINA ESTÉTICA. SUPERA TAMBIÉN LA SEGUNDA Y NOS VAMOS DIRECTAMENTE A LA TERCERA. CON ESTA NO TIENE TANTA SUERTE, SACAMOS LOS XUSÓKERS Y LE TOCA EL RECICLA, ELIGE A OTRO SEÑOR Y TAMPOCO LA SABE. NOS CUENTA QUE LE GUSTA VIAJAR Y CON EL DINERO QUERRÍA IR A ESTAMBUL Y TAMBIÉN INVERTIR, POR EJEMPLO, EN UN NEGOCIO DE ESTÉTICA. SUPERA LA CUARTA Y ANDREA DECIDE QUEDARSE CON LOS 600.', 'Leandro', '1', 'Mecánica corta. 
Arranque mención a Jennifer Hermoso y da toques de balón. 
Aparición de Quino.
Nos saltamos una pregunta.', '17:02', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (595, @jornada_id_161, '2025-07-10', 'CARABANCHEL', 'MARTA', 52, 'ESTILISTA', '@flash.estilistas', 619, 475, 'X10 SP', 0, '***CUESTIONARIO MUSICAL***
 TC IN: 12:39    TC OUT: 13:30
 ARRANCAMOS ANTE EL MURAL MÁS GRANDE DE ESPAÑA SITUADO EN EL PALACIO DE VISTALEGRE. XUSO VA POR LAS MESAS PREGUNTÁNDOLE A LA GENTE QUÉ TIPO DE MÚSICA LES GUSTA. UN CHICO LE DICE QUE EL ROCK Y MARTA DICE QUE TAMBIÉN, IGUAL QUE EL CHICO DE DETRÁS. LE PROPONE CONCURSAR Y ELLA LE DICE QUE SÍ PORQUE NO TIENE NADA QUE HACER HOY. ARRANCAMOS LA PRIMERA Y LA SUPERA GRACIAS A UN CHICO ITALIANO. NOS CUENTA QUE ES PELUQUERA TODA LA VIDA Y AHORA HA ABIERTO UN SEGUNDO NEGOCIO CON UN TOQUE MÁS MODERNO Y ORGÁNICO, POR LO QUE SABE PERFECTAMENTE EN QUÉ INVERTIRÍA EL DINERO DEL PREMIO. SUPERA TAMBIÉN LA SEGUNDA (QUE VA SOBRE DISNEY Y EL ELEGIDO SE LLAMA ARIEL). NOS CUENTA QUE TIENE TRES HIJOS Y QUE LA AYUDAN MUCHO PORQUE SU MARIDO MURIÓ EN 2018 DE GOLPE Y HAN TENIDO QUE TIRAR PARA ADELANTE. SUPERA LA TERCERA Y LEANDRO CANTA Y BAILA CON MARTA UNA CANCIÓN DE MARTIRIO. LA CUARTA NO LA SUPERA, SACAMOS EL XUSÓKER Y LE TOCA EL AL VERRÉS, POR LO QUE CORRE MUCHA MÁS SUERTE PARA SUPERARLA. MARTA SE L A JUEGA Y LE SALE EL X10. AL VER LA PREGUNTA, SE ARREPIENTE. ELIGE A UN FARMACEÚTICO Y NO LA SABE, ASÍ QUE SE VA SIN NADA.', 'Leandro', '2+', 'Mecánica corta. 
Arranque frente al mural más grande de España en Carabanchel.
Tiene que ir después de la emisión de algún programa de Segovia, ya que algún participante hace mención a que ha visto algo de esta ciudad.', '23:22', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (596, @jornada_id_161, '2025-07-10', 'CARABANCHEL', 'SERGIO', 92, 'JUBILADO', 'NO TIENE', 624, 471, 'X2 SG', 2000, 'TC IN: 13:33     TC OUT: NO LO COGÍ 
XUSO ARRANCA VESTIDO DE MANOLITO GAFOTAS Y NOS PREGUNTA DE QUÉ VA (HACEMOS COMO QUE NO LO SABEMOS) AVANZAMOS UN POCO Y VE A UN SEÑOR SENTADO EN UNA MESA QUE LO CONOCE Y HABLAN. XUSO LE DICE AL OÍDO QUE VA DE MANOLITO GAFOTAS PARA QUE LO ADIVINE. A XUSO LE CAE GENIAL Y BROMEA CON ÉL, INCLUSO SE TIRA AL SUELO (NO ME ACUERDO POR QUÉ, PERO FUE MUY GRACIOSO) LE PROPONE CONCURSAR Y EMPEZAMOS. SUPERA LA PRIMERA PREGUNTA Y NOS CUENTA QUE VIVE EN CARABANCHEL DESDE HACE MÁS DE 60 AÑOS, ANTES VIVÍA EN TETUÁN, PERO MONTÓ UNOS BARES EN LA ZONA. XUSO LE PREGUNTA POR LA EDAD Y LE DICE QUE TIENE 92, XUSO NO DA CRÉDITO Y LE PIDE EL DNI Y SE VUELVE A TIRAR AL SUELO (EL SEÑOR ESTÁ GENIAL, LA VERDAD). SUPERA LA SEGUNDA Y PASAMOS A LA TERCERA, CON LA QUE NO CORRE TANTA SUERTE Y, AL SACAR LOS XUSÓKERS, LE SALE EL CONTINÚE Y LO CELEBRAMOS MUCHO (GRACIOSO EL MOMENTO QUE XUSO LE PREGUNTA QUIÉN ES EL QUE APARECE EN LAS CARTAS Y SERGIO DICE QUE ES PAJARES). NOS CUENTA QUE NO TIENE PROBLEMAS DE DINERO, ASÍ QUE HARÍA ALGUNA OBRA DE CARIDAD. SUPERA LA CUARTA Y DECIDE JUGÁRSELA. ELIGE A UNA SEÑORA LATINOAMERICANA QUE NO LO SABE Y GRACIAS A ELLO GANA 2000 EUROS. NOS DICE QUE QUIERE INVITARNOS A UNOS CHILIPÚS Y NOS VAMOS TODO EL EQUIPO CON ÉL.', 'Leandro', '3', 'Mecánica corta.
Acting Xuso hace de Manolito Gafotas y está así todo el concurso.', '20:48', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (597, @jornada_id_162, '2025-07-15', 'ALCALÁ DE HENARES', 'NOÉ', 25, 'ESTUDIANTE Y DEPENDIENTE', '@noeninternet', 623, 1000, '17:23 - 18:11. Xuso cuenta datos sobre las personas ilustres que han pasado por la universidad de Alv¡calá de Henares y decide ponerse en la puerta a esperar que salga un universitario. Sale Noé con su TFM en la mano y se queda sorprendido de ver a Xuso. Le cuenta que acaba de defenderlo ante el tribunal y Xuso ojea el TFM y le invita a concursar.Noé cree que la primera es fáicl y coge a Elisa que acierta. Nos cuenta que estudió magisterio y ahora un master y que es el primero de su familia en estudiar tanto. Que la vocación le viene de querer cambiar las cosas porque a él le hicieron bullying. En la segunda no tiene ni idea y elige a Marcos Rodríguez González, de Ponferrada, gran fan del programa, que nos pide que vayamos a El Bierzo. Mientras responde se le posa una libélula en la cabeza. No tiene ni idea y Noé gana los 400. Nos cuenta que vive con sus hermanas, su madre y su pareja y se divierte poniéndoles el pie en la cara. Vamos a la tercera y se pone en busca de alguien con pinta de profesor. Coge a José Manuel que responde "Francia" y nos vamos a los XUSÓQUER, le sale un RECICLA y coge a una muchacha que es maestra de educación física y dice la respuesta correcta al azar. Noé nos cuenta que con el dienro se mudaría a un chalet con un bulldog francés al que su novio quiere poner nombre de drag y a él no le entiusiasma. En la cuarta coge a una chica joven que dice "ii" y con los mil se planta y se va feliz.', 'Adriana', '3', 'Mecánica corta. 
Arranque frente a la Universidad de Alcalá. Enumera alumnos ilustres y espera a que salga alguno actual.', '21:54', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (598, @jornada_id_162, '2025-07-15', 'ALCALÁ DE HENARES', 'FELIPE', 69, 'JUBILADO', '@toompak', 627, 458, 'X6 SG', 6000, '***CUESTIONARIO MUSICAL***
 18:28 - 19:09. Xuso comenta que la Calle Mayor de Alcalá es la más larga de Europa porticada en ambos lados. Y busca a alguien que le diga los metros que tiene. Para a unos señores muy secos, luego a otros majos, pero que no firman y luego a Felipe que como hace su paseo matinal por ahí sabe que tiene 396 metros. Xuso le invita a concursar y como ve que en su camiseta pone que hace música con objetos, le hace cuestionario musical. La primera pregunta le parece difícil porque no sabe inglés ni sabe quién es Cher, pero para a Pablo que lo sabe y la canta. Nos cuenta sobre el grupo de su hijo, que hace música con objetos y que él les ayuda con los instrumentos y le hace una muestra a Xuso tocando en la mesa de un bar. En la segunda pregunta coge a una cocinera que no conoce el programa ni sabe la respuesta, pero nos canta Karol G. Con los 400 euros nos hacen un baile de hula. PONER POR GRAFISMO COLLARES HAWAIANOS Y FALDAS.  Vamos directos a la tercera y coge a un conocido del barrio, que se sabe la canción, pero no el grupo. Sacamos los XUSÓQUER y le sale un CONTINÚA (repetimos porque Emilio grita y a todos nos da la risa). Felipe nos dice que su sueño es comprar una moto, pero eso le va a costar el divorcio. Vamos a la cuarta y coge a una chica muy joven que no sabe la respuesta, pero antes de irse nos baila el aserejé. Felipe se la juega y (OJO: aquí hay una cagada mía, porque no le doy el combo musical, le doy otro.) le sale un x6 y para a una señora que duda entre decir "Caimán" y "Galápagos" y se queda con Galápagos. Así que Felipe gana los 6k.', 'Adriana', '2', 'Mecánica corta.
Arranque con mención a la calle porticada a ambos lados más larga de Europa. Busca a alguien que le diga cuántas columnas tiene. 
Cuestionario musical.
Nos saltamos una pregunta. 
El combo no es musical.', '22:54', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (599, @jornada_id_162, '2025-07-15', 'ALCALÁ DE HENARES', 'KIMBERLY', 26, 'PROFESORA DE INGLÉS', '@kva_99', 591, 1000, '19:51 - 20:40. Xuso camina por las calles de Alcalá con el cartel de "Busco profesora de inglés" y se le acerca mucha gente muy divertida. Primero una señora con silla de ruedas que le dice que ella le enseña búlgaro y no es un idioma. Después una muchacha joven y luego un chico con un perfecto acento inglés que le da mucho juego. Después encuentra a Elizabeth, profesora jubilada, pero que no quiere concursar y llega a Kimberly que se queda en shock. Se sorprende de que se encuentren en el mismo lugar que la otra vez (Aquí va VTR de recordatorio) y Kimberly acepta darle clases de inglés. A cambio Xuso solo puede pagarle con lo que hay dentro de una caja. Ella la abre y saca la banda y se la pone, pero no reacciona, está anonadada. Microfonamos y arrancamos y ella nos cuenta que se ha disociado y no sabe qué está pasando. En la primera pregunta elige a Gonzalo que está con su familia tomando algo y que tras pensar un rato acierta. Kimberly nos cuenta que su vida no ha cambiado, que ahora está preparando el nuevo curso y que cuando salió en la tele sus amigas se metieron mucho con ella, pero que se hizo famosa. Vamos a la segunda y elige a Consuelo, que no conoce el programa y dice "bicolor", Kimberly gana los 400 y Consuelo unas clases de inglés gratuitas. Vamos directos a la tercera y elige a un muchacho joven que le dice a Xuso que tiene una foto con él de hace 10 años. No la encontrará, así que mejor rebajar esto en el precorte. El chico vive en Dinamarca y acierta las provincias de la comunidad Valenciana. Xuso recuerda que Kimberly iba mucho a Valencia a ver a su novio (FLASHBACK DE ESTO) y le pregunta por sus planes de fututo. Ella quiere mudarse a una casa más grande con su chico y para eso le vendría genial el dinero. Aunque sigue con el tema del podcast en la cabeza. En la cuarta elige a una chica mulata muy simpática que responde "seis" y Kimberly gana los mil y se planta', 'Adriana', '3', 'SEGUNDA OPORTUNIDAD. Busca a Kimberly con cartel, se le paran varias personas hasta que se acerca a su presa y esta se queda en shock. 
Mecánica corta. 
Nos saltamos una pregunta.', '20:38', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (600, @jornada_id_162, '2025-07-15', 'ALCALÁ DE HENARES', 'ANDREA', 22, 'COMMUNITY MANAGER', '@andrea.diezz', 606, 600, '20:45 - 21:32. Xuso come almendras garrapiñadas de las monjas de clausura de Alcalá y reparte entre el equipo. Va ofreciendo a la gente. LA SEÑORA MAYOR 
GRACIOSA NO QUIERE DARNOS EL DNI, PERO NO NOS VA A DENUNCIAR. Se encuentra con Andrea, que no para de mirarle y le cuenta que está de paseo con su jefa. A 
Xuso le conquista y la hace concursante. En la priemra tiene mala pata porque elige a Juan Carlos, un funcionario que dice siglo XX. Le sale el XUSÓQUER de 
CONTINÚA. Nos cuenta que es de un pueblo, pero vive aquí porue etsudia aquí y que siempre ha estudiado y trabajado para ayudar a sus padres a pagar los gastos de 
la carrera. Estudia ADE. En la segunda coge a una chica que va con su pareja y se llaman Daniel y Daniela. La chica no lo sabe y gana los 400. Vamos directos a la 
tercera y busca alguien mayuor que sabe más de religión. Elige a Beni, fan del programa y que lleva ua cruz de Caravaca al cuello, pero Beni dice "seis" y no supera la 
pregunta. Nos dice que si ganara mucho dinero se lo daría a sus padres para ayudarles a pagar los gastos y si puede se iría con su novio Carlos de viaje. Le formulamos 
la cuarta y busca a un señor mayor. Elige a Jose, que conoce el prigrama y cree que le ha cogido por un no lo sabe. De hecho, al hacerle la pregunta, sabe la respuesta 
pero toma la decisión de decir que no lo sabe, porque después de ver mucho el programa cree que la gente joven coge a los viejos por este motivo y empieza a dar 
una charla sobre el edadismo un poco aburrida. Andrea, a pesar del chaparrón, gana los 600 y se planta porque eso es un mes de piso en Alcalá.', 'Adriana', '2-', 'Arranque comiendo almendras garrapiñadas de las monjas de clausura. 
Mecánica corta. 
Nos saltamos una pregunta.', '18:56', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (601, @jornada_id_163, '2025-07-16', 'MADRID', 'JAVIER', 31, 'PERIODISTA', '@javitm8', 634, 452, 'X8 SG', 3200, '***CUESTIONARIO MUSICAL***
 17:13 - 18:00. Xuso busca a gente que le siga la canción y decide cantar canciones de David Bisbal. Para a varias personas sosas, hasta que llega Javier, que le hace la patada bisbalera y casi se lesiona las lumbares. Dice que le viene muy bien concursar porque tiene siete bodas este año y no tiene un duro. Además, quiere hacer un máster. Nos cuenta que es de Almería, pero estudió en Murcia. Arrancan con el cuestionario musical y en la primera elige a un señor que no sabe la respuesta. Vamos a los XUSÓKER, y le sale un RECICLA. Sigue buscando y nos cuenta que ha tenido muy mala suerte con los hombres, así que va a buscar una mujer. Coge a Araceli y ella dice "dulces sueños", así que no supera la primera pregunta. Nos cuenta que a Madrid le ha traído la precariedad, que trabaja en comunicación en una empresa y que es soltero desde que nació porque quizá es muy tóxico. Vamos a la segunda y no tiene ni idea, pero evita a la gente joven. Finalmente elige a Raúl que no sabe tampoco la respuesta. Nos cuenta que salir del pueblo le hizo descubruir nuevas aficiones como la gimnasia rítmica o la natación sincronizada y nos hace un paso de gimnasia rítmica. En la tercera canta una canción que no es, pero que también es María, y coge a Noemí, una señora pija que, después de que Xuso insista, dice María a boleo y supera la pregunta. Como nos ha ido contando que el dinero es para las bodas que tiene, aligeramos la tercera pregunta personal y para la cuarta coge a un jubilado que acierta de boleo. Así que con los 400 se la juega, le sale un x8 y busca a alguien joven porque él se sabe la respuesta. Coge a una madre de 30 años, Aitana, que acierta y nos cantan la canción mientras Javier se despide con un paso de gimnasia.', 'Adriana', '3', 'Cuestionario musical. 
Mecánica corta. 
Chico gimnasta rítmico.', '24:48', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (602, @jornada_id_163, '2025-07-16', 'MADRID', 'ISHANDRA', 33, 'ADMINISTRATIVA', '@ishandradf', 613, 464, 'X11 N', 2000, '18:29 - 19:10.  Xuso decide subir y bajar por la escalera mecánica y que el que le toque la mano se convierte en concursante, pero no le sale bien porque nadie quiere. Así que se pone a buscar caminando por las calles del centro comercial. Aparece Isahandra muy emocionada porque es muy fan del programa y lo ve todos los días. Va con su marido a comprar pastillas de lavavajillas pero se queda con Xuso a concursar porque es su ilusión y el dinero le da igual. En la primera coge a Yelko, un chico gallego que acierta. Ishandra nos cuenta que es hija de inmigrantes filipinos y sus padres le puso casi el mismo nombre a sus tres hermanas. En la segunda elige a la dependienta de una tienda de aceitunas que es muy fan de Xuso, y responde "18". Les invita a una aceituna y a Ishandra no le gustan, así que se la da a Xuso que se atraganta y casi escupe la aceituna. Ishandra nos dice algunas palabras en filipino. Vamos a la tercera pregunta y tarda mucho en encontrar a quién coger, pero no deja a Xuso que la distraiga mientras caminan. Coge a una señora que acierta, aunque pronuncia regular. Ishandra nos cuenta que el dinero sería para comprar una casa porque vive de alquiler con su marido y sus dos hijas. En la tercera elige a una señora colombiana que acierta así que sacamos el XUSÓQUER y le sale un CONTINÚA. Con los mil euros se la juega. ABRIMOS SOBRES. Le sale un x2 y coge a una chica que tiene mucha prisa, pero que tras mucho pensar acierta y hace que Ishandra se vuelva loca de alegría.', 'Adriana', '2+', 'Mecánica corta.', '24:16', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (603, @jornada_id_163, '2025-07-16', 'MADRID', 'PETRA', 27, 'ACTRIZ', '@lapetrona_', 603, 1000, '20:31 - 21:02: Xuso destaca que estamos en Gran Vía, el lugar de los musicales, de los sueños y con su micro pregunta a la gente que sueños les quedan 
por cumplir. Para a dos parejas que dicen cosas muy bonitas y encuentra a Petra que le dice que sueña con ser actriz. Le encanta su look y la elige. Para la 
primera pregunta busca a alguien con pinta de intelectual y elige a Víctor, que es encantador y acierta. Nos cuenta que es de Gijón, pero Madrid le ha 
abrazado desde que llegó porque como Mujer trans y como actriz es importante encontrar un círculo que te acoja. En la segunda pregunta busca a 
alguien como ella, porque ella no lo sabe. Coge a una chica joven que dice "seda" y gana los 400. Nos cuenta sus aficiones y dice que se formó como 
teatro musical, así que Xuso le hace cantar y le canta "La violetera" de Sara Montiel. En la tercera busca a alguien con look moderno, pero coge a un chico 
súper elegante que acierta y Xuso hace un alegato en contra del overbooking. Nos dice que el dinero es para ayudar a sus padres que le han comprado un 
piso en Madrid. En la cuarta coge a un chico joven que acierta y vamos al XUSÓQUER, que le sale un continúe. Así que con los mil se planta.', 'Adriana', '2+', 'Mecánica corta. 
Arranque en Gran Vía, el lugar de los musicales, de los sueños... Xuso pregunta a la gente por sueños por cumplir.', '20:38', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (604, @jornada_id_164, '2025-07-22', 'OVIEDO', 'MARÍA JESÚS', 61, 'JUBILADA', 637, 454, 'X3 SG
X48 N', 1200, '10:28 - 11:18: Xuso junto a la estatua de La Regenta comenta el libro y su frase estrella: ¿cabe libertad donde no hay elección?. Decide preguntárselo a la gente y para a un señor de Uruguay y a un peregrino inglés. Finalmente coge a María jesús que le da un discurso bonito y la convierte en concursante. Para la primera pregunta busca a alguien con cara de leído, y para a una chica joven que no tiene ni idea. Así que nos vamos al XUSÓQUER, y le sale un CONTINÚE. Nos cuenta que es maestra jubilada, maestra por vocación y que no ha podido disfrutar aún de la jubilación porque tuvo un cáncer de mama y se está recuperando. Para la segunda pregunta elige a Aida, que es muy maja y no lo sabe, y se alegra mucho de que gane los 400. María jesús nos cuenta que ella está casada con Manolo y que Manolo ha sido muy bueno con ella durante el cáncer. Da un discurso muy bonito. Vamos a la tercera y elige a una chica cubana que lleva un año en Oviedo y no sabe la respuesta. María jesús quiere le dinero para arreglar la casa del pueblo y porque le viene bien, ya que su marido no trabaja. La cuarta pregunta le parece muy complciada, porque le usta mucho NY, aunque no tanto su presidente. Elige a una señora que acierta, así que María Jesús se queda con 400 y decide jugársela. ABRIMOS SOBRES y enseñamos el x48, pero a ella le sale el x3. La pregunta le parece fácil y coge a un señor mayor, José Manuel, que no lo sabe y se va feliz con su dinero.', 'Adriana', '2+', 'Acting Regenta, pregunta sobre frase libro. 
Lleva explicación mecánica y xusoker.', '24:26', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (605, @jornada_id_164, '2025-07-22', 'OVIEDO', 'GLORIA', 74, 'JUBILADA', 631, 467, 'X2', 0, '***CUESTIONARIO MUSICAL***11:19 -12:18 Xuso comienza frente al Teatro Campoamor, donde se celebran los premios Princesa de Asturias, y decide hacer un homenaje a Melendi y buscar a quién le cante, pero aparece Gloria, que no tiene ni idea de Melendi, pero le conquista con su gracia. Gloria es muy fan del programa y se emociona mucho al ver a Xuso. Cuenta que es de Granada, aunque emigró a Suiza y desde hace cincuenta años vive en Oviedo. le gusta la música italiana, pero no canta bien porque está nerviosa. Xuso explica mecánica. Arrancamos con la primera y no tiene ni idea, para a un chico que dice "bombero" y Xuso les canta la canción. Sacamos los Xusóquers y le sale un CONTINÚE. Nos cuenta que trabajó de cocinera en un centro de menores y tenía un bar y que su plato estrella son los arroces. En la segunda también juega sin saber, y coge a una mexicana que no cae y le hace ganar los 400. Nos cuenta que el dinero le da igual, ella está feliz por concursar y se conserva así de bien porque hace zumba, y nos cuenta anécdotas del gimnasio (se enrrolla demasiado). Le dice a Xuso que está muy fuerte y vamos a la tercera, que coge a Elena, que conoce la canción, pero no el autor. Nos cuenta Gloria que con el dinero haría un regalo a sus nietos y volvería a Suiza a reencontrarse con su infancia. Para la cuarta elige a Marta, que acierta a boleo y con los 400, Gloria se la juega. Le sale un x2 y para a una señor que dice "Tequila". Se va con la camiseta, pero feliz con Xuso del brazo.', 'Adriana', '2', 'Cuestionario musical.', '23:15', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, duracion, valoracion_final) VALUES (606, @jornada_id_164, '2025-07-22', 'OVIEDO', 'CARMEN', 77, 'JUBILADA', 616, 600, '12:30 - 13:19 Xuso dice que en Oviedo hay más de cien estatuas y hoy habrá una más, porque Felipe y él se van a convertir en estatuas y a ver quién se le acerca. Pide que se alejen las cámaras y de repente una chica entra y le da un beso, Xuso asegura que es muy raro lo que le acaba de pasar. Luego un señor empieza a teorizar a su lado, y por último entra Carmen muy ilusionada proque le encanta el programa. Xuso la convierte en concursante. Explica mecánica y arrancamos con la primera pregunta, en la que busca a una persona madura, pero finalmente para a una chica joven que tras pensar un buen rato, acierta. Xuso le dice a Carmen que está estupenda y ella le dice que es de comer fabada y cuenta que fue maestra de matemáticas y dibujo. En la segunda elige a una señora que recuerda tarde el nombre de Gio, y le hace ganar los 400. Pasamos directos a la pregunta 3, en la que elige a OLga que no lo sabe y vamos al XUSÓKER. Le sale un CONTINÚE. Nos cuenta que el dinero sería para sus nietos y sus dos hijos y en la cuarta elige a Alfredo, un señor jorobado que acierta, así que Carmen se planta con los 600 y le promete a Xuso que le va a hacer una bufanda.', 'Adriana', '1+', '19:21', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (607, @jornada_id_164, '2025-07-22', 'GIJÓN', 'CLAUDIA', 28, 'GESTORA DE VENTAS', '@claufdezfdez', 582, 456, 'X2', 1200, '16:34 - 17:18: Xuso está ante la estatua de Don pelayo y dcie que va a buscar un rey o reina asturiano. Para a varias personas que no son asturianas y finalmente llega a Claudia, que le dice que es tan asturiana que se casó el día de Asturias. Xuso la convierte en concursante, le explica mecánica y arrancamos con la primera, en la que para a un chico que está de turismo. Pedro acierta y Cluadia nos cuenta que tiene 29 años y se ha casado joven con su novio Fran, y nos cuenta que se conocieron en Genarín, una fiesta de León. Xuso destaca que diga "ye" en vez de "es" y se ríen de ello. Xuso saca a Adriana, pero por favor, cortadlo. Vamos a la segunda y cohe a una chica muy moderna, Paula, que está de turismo y no tiene ni idea, pero se alegra de que gane los 400. Claudia nos cuenta que ella ha jugado al baloncesto y le encanta la montaña. también cuenta que es gestora de una eléctrica y Xuso pide que no le llamen en la hora de la siesta. Vamos a la tercera, que no la sabe, aunque ha estado en Marrakech. Para a Álvaro, de Ciudad real, que no lo sabe y vamos al XUSÓQUER. Le sale un RECICLA. Para a Merche, turista canaria, que dice "jaima". Claudia nos cuenta que el dinero será para invitar a sus padres a un crucero, porque su madre ha estado cuidando de su abuela que ha fallecido y necesita un estímulo. Se emociona un poco y formulamos la cuarta. Elige a Julia que es muy graciosa y dice "ibérico". Con los 600, Claudia se la juega, le sale un x2, y elige enseguida a una chica joven que no sabe el nombre del robot y le hace ganar los 1200. Se va muy feliz.', 'Adriana', '2+', 'Nota Loreto: menciona que se casó un 8 de septiembre, día de Asturias. Conviene que no coincida con el 8 de septiembre.', '23:09', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, duracion, valoracion_final) VALUES (608, @jornada_id_165, '2025-07-23', 'AVILÉS', 'JOSÉ RAMÓN', 39, 'HOSTELERO', '@joselg_85', 645, 477, 'X2', 0, 'REC 10:52 - 11:39ARRANCAMOS EN LA PLAZA DEL CARBAYEDO Y XUSO NOS CUENTA EL ORIGEN DEL NOMBRE DE ESTA PLAZA Y NOS HABLA SOBRE EL HÓRREO, UN SÍMBOLO DE LA ASTURIAS RURAL. SEGUIDAMENTE, LE PREGUNTA A UN PAR DE PERSONAS QUÉ OTRAS COSAS TÍPICAS TIENE ASTURIAS. EL PRIMER CHICO NOS CONTESTA "PAELLA, FABADA, CACHOPO", DESPUÉS LE PREGUNTAMOS A OTRO SEÑOR (QUITAR); EL TERCERO NOS CONTESTA LA "LONGANIZA DE AVILÉS" Y FINALMENTE NOS ENCONTRAMOS CON JOSE RAMÓN Y SU PAREJA, ALFREDO. JOSE RAMÓN RESPONDE QUE LOS BAILES REGIONALES TAMBIÉN SON MUY TÍPICOS DE ASTURIAS Y SE ARRANCA A BAILAR UNA JOTA DE CANGAS CON SU PAREJA. CAPTAMOS A JOSE RAMÓN Y DESPEDIMOS A ALFREDO. // NO SUPERA LA PRIMERA PREGUNTA Y SACAMOS LOS XUSÓKER. LE SALE UN AL VERRÉS Y SUPERA LA PRIMERA PREGUNTA. NOS CUENTA QUE TIENE UN RESTAURANTE EN CUDILLERO Y QUE TAMBIÉN SE DEDICA A LA GANADERÍA. SUPERA LA SEGUNDA PREGUNTA Y XUSO LE PREGUNTA POR SU PAREJA. NOS CUENTA QUE LLEVA CASADO TRES AÑOS CON SU MARIDO, PERO MÁS DE 15 JUNTOS. SUPERA LA TERCERA PREGUNTA Y CON EL DINERO LE GUSTARÍA PAGAR LA HIPOTECA Y HACER UN VIAJE CON SUS AMIGOS. NO SUPERA LA CUARTA PREGUNTA Y DECIDE JUGAR. NO ABRIMOS SOBRES MULTIPLICADORES Y NO SUPERA LA QUINTA PREGUNTA.', 'Cristina', '2', '20:42', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (609, @jornada_id_165, '2025-07-23', 'AVILÉS', 'MARÍA JESÚS', 36, 'AMA DE CASA', '@marichu89', 625, 600, 'REC 11:45 - 12:44ARRANCAMOS EN LA PLAZA DE ESPAÑA Y XUSO NOS CUENTA QUE ESTA PLAZA ES CONOCIDA COMO "EL PARCHE" PORQUE HACE MUCHOS AÑOS HICIERON UNA OBRA Y LA GENTE DIJO QUE ERA UNA CHAPUZA, VAMOS, UN PARCHE, Y ASÍ SE QUEDÓ. XUSO EXPLICA QUE EN EL EQUIPO TAMBIÉN TENEMOS COMPAÑEROS CON APODOS CURIOSOS COMO ROSA, "LA PEQUEÑA PETUNIA"; CRISTINA, "PRINCESS" Y NACHO, "EL MARQUÉS", ASÍ QUE XUSO SE PROPONE ENCONTRAR A ALGÚN AVILESINO O AVILESINA CON UN APODO CURIOSO. XUSO INTERACTÚA CON UN PAR DE PERSONAS, SE HACE FOTOS CON UNAS SEÑORAS Y SE ENCUENTRA CON MARÍA JESÚS Y SU PAREJA. NOS CAEN MUY BIEN, PERO MARÍA NOS DICE QUE NO TIENE NINGÚN APODO, ASÍ QUE LA CAPTAMOS Y LE DECIMOS QUE YA SE LO PONDREMOS DURANTE EL CONCURSO. // EXPLICAMOS LA MECÁNICA Y SUPERA LA PRIMERA PREGUNTA POR LOS PELOS. LA APODAMOS "MARÍA LA PESCAÍLLA" PORQUE ES PISCIS (A PARTIR DE AQUÍ, LE PONEMOS UN APODO A TODOS LOS ELEGIDOS SEGÚN SU SIGNO ZODIACAL). NOS CUENTA QUE LLEVA 9 AÑOS CASADA CON SU PAREJA Y QUE SE CONOCIERON DE CASUALIDAD EN UN DÍA DE PLAYA. NO SUPERA LA SEGUNDA PREGUNTA, SACAMOS LOS XUSÓKER Y SALE EL RECICLA. SUPERA LA SEGUNDA PREGUNTA, VAMOS DIRECTOS A LA SIGUIENTE Y NO SUPERA LA TERCERA PREGUNTA. NOS CUENTA QUE ESTÁ EN PARO, QUE TIENE UN PEQUE DE CUATRO AÑOS Y QUE SE ACABA DE COMPRAR UNA CASA. SUPERA LA CUARTA PREGUNTA Y DECIDE PLANTARSE.', 'Cristina', '2+', 'Nota Loreto: Xuso dice que han estado grabando el día anterior en Gijón. Así que conviene ponerlo un día después de haber programado a alguien de Gijón', '21:13', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (610, @jornada_id_165, '2025-07-23', 'AVILÉS', 'JOSÉ MANUEL', 70, 'JUBILADO', 651, 445, 'X9 SG', 9000, 'REC 12:53 - 13:51 ARRANCAMOS ENTRANDO EN LA TIENDA DE ULTRAMARINOS DE AVILÉS PORQUE XUSO QUIERE COMPRARLE UN MANTECADO DE AVILÉS A LA VIRTU. LA SEÑORA DEPENDIENTA NOS EXPLICA QUE ANTIGUAMENTE LOS MARINEROS SE LLEVABAN ESTE DULCE CUANDO IBAN A FAENAR PORQUE PODÍA AGUANTAR VARIOS DÍAS SIN PONERSE MALO. XUSO LO PRUEBA Y SE LO DA A LOS MIEMBROS DEL EQUIPO. (LEVANTAR EL RESTO DE EXPLICACIÓN SOBRE LA HISTORIA DE LA CONFITERÍA Y RETOMAR CUANDO XUSO PIDE QUE SE LO PONGAN PARA LLEVAR). SALIMOS DE LA TIENDA Y NOS ENCONTRAMOS CON JOSE, QUE LE RECOMIENDA A XUSO QUE TAMBIÉN COMPRE LA LONGANIZA DE AVILÉS. LO CAPTAMOS Y COMENZAMOS EL CONCURSO. // EXPLICAMOS LA MECÁNICA, SUPERA LA PRIMERA PREGUNTA Y NOS CUENTA QUE SE HA DEDICADO A LA HOSTELERÍA DURANTE MÁS DE 30 AÑOS Y QUE ESO LE HA SUPUESTO PERDERSE MUCHOS MOMENTOS ESPECIALES PORQUE EN LOS FESTIVOS COMO NOCHEVIEJA O EL DÍA DE LA MADRE ES CUANDO MÁS SE TRABAJA, PERO AHORA ESTÁ JUBILADO Y YA PUEDE DISFRUTAR MÁS DE LA VIDA. SUPERA LA SEGUNDA PREGUNTA Y VAMOS DIRECTOS A LA SIGUIENTE. SUPERA LA TERCERA PREGUNTA Y LE CANTAMOS "CUMPLEAÑOS FELIZ" A LA ELEGIDA PORQUE ERA SU CUMPLEAÑOS. NOS CUENTA QUE CON EL DINERO LE GUSTARÍA IRSE UN MES DE CRUCERO CON SU HIJA, SU YERNO Y SU NIETO, Y COMPRARSE UNA BICICLETA PORQUE LA SUYA SE HA QUEDADO ANTICUADA. SUPERA LA CUARTA PREGUNTA Y DECIDE JUGAR. EL ELEGIDO CONTESTA "ESCOBA O FREGONA", Y FINALMENTE DICE, "ESCOBA". JOSE SE LLEVA 9.000 EUROS POR LOS PELOS Y CON MUCHA ALEGRÍA.', 'Cristina', '2+', 'Acting pastelería, Xuso compra mantecado para Virtudes. 
Incluye explicación mecánica y novedad Xusokers.', '22:18', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (611, @jornada_id_165, '2025-07-23', 'AVILÉS', 'FRANCISCO JAVIER', 54, 'PELUQUERO', '@peluqueria_francisco_fran27f', 615, 465, 'X6 SG', 0, '***CUESTIONARIO MUSICAL***REC 15:55 - 16:41 // ARRANCAMOS IN MEDIA RES CUANDO NOS ESTÁBAMOS PREPARANDO PARA EMPEZAR PORQUE SE CAE LA SOMBRILLA DE UNA TERRAZA POR EL VIENTO Y XUSO SE ACERCA A LA CAMARERA PARA OFRECERLE SU AYUDA. COMO ESTÁ TODO BIEN, SEGUIMOS CON EL ARRANQUE. XUSO NOS CUENTA QUE QUIERE ENCONTRAR A UN ASTURIANO O ASTURIANA QUE LE CANTE EL "ASTURIAS, PATRIA QUERIDA". PRIMERO PARA A UNA CHICA QUE RESULTA SER UN POCO FRIKI (EDITAR EN MODO RISAS PARA SUBRAYAR INCOMODIDAD), DESPUÉS PARA A OTRA CHICA QUE ES DE MADRID Y QUE SOLO SE SABE EL ESTRIBILLO, Y FINALMENTE NOS ENCONTRAMOS CON FRANCISCO QUE SE ANIMA A CANTAR Y A BAILAR EL HIMNO. LO CAPTAMOS Y COMENZAMOS EL CONCURSO. // SUPERA LA PRIMERA PREGUNTA Y COMO EL ELEGIDO ERA MÚSICO Y ESTABA TOMANDO ALGO CON SU AMIGO, QUE TAMBIÉN ES MÚSICO, LES PEDIMOS QUE NOS TOQUEN UNA CANCIÓN. DESPUÉS DE ESTE MOMENTO MUSICAL, FRAN NOS CUENTA QUE ES PELUQUERO DESDE HACE 30 AÑOS Y QUE COMENZÓ POR CASUALIDAD A RAÍZ DE CORTARLE EL PELO A SU TENIENTE CORONEL DURANTE LA MILI. SUPERA LA SEGUNDA PREGUNTA Y VAMOS DIRECTOS A LA SIGUIENTE. SUPERA LA TERCERA PREGUNTA Y NOS CUENTA QUE CON EL DINERO HARÍA UN VIAJE E INVITARÍA A UNA MERIENDA A LOS ANCIANOS DE LA RESIDENCIA DONDE SUELE IR A BAILAR CON SU GRUPO DE BAILES PARA ANIMAR A LOS MÁS MAYORES. SUPERA LA CUARTA PREGUNTA Y DECIDE JUGAR. NO ABRIMOS SOBRES MULTIPLICADORES. EL ÚLTIMO ELEGIDO NO ACIERTA Y FRAN SE MARCHA CON LA CAMISETA.', 'Cristina', '2', 'Cuestionario musical. 
Xuso busca al concursante que le erice el vello cantando el himno de Asturias.', '24:07', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, duracion, valoracion_final) VALUES (612, @jornada_id_166, '2025-07-24', 'GIJÓN', 'AROA', 25, 'TÉCNICA DE LABORATORIO', '@aroresch', 635, 460, 'X8 SG', 8000, 'REC: 10:00 - 10:55ARRANCAMOS EN EL PASEO MARÍTIMO IN MEDIAS RES PORQUE NOS ENCONTRAMOS CON UNA SEÑORA MUY CURIOSA QUE ESTÁ PASEANDO A SU PERRO MIENTRAS CANTA "EL EMIGRANTE" DE JUANITO VALDERRAMA. XUSO BROMEA CON ELLA, CANTAN JUNTOS Y LE PIDE QUE LE ENSEÑE ALGUNA PALABRA EN ASTURIANU, PERO NOS DICE QUE ES DE LEÓN. (NOS DILATAMOS MUCHO CON ELLA PORQUE NO SE CALLABA. DEJARLO MÁS CORTO Y POTENCIAR SU LOCURA). SE SUMA OTRO SEÑOR Y NOS ENSEÑA LA PALABRA "ORBAYU", QUE ES LA LLUVIA FINA TÍPICA DE ASTURIAS. LES DESPEDIMOS Y SEGUIMOS CAMINANDO. NOS ENCONTRAMOS CON AROA, NOS ENSEÑA UN PAR DE PALABRAS Y LA CAPTAMOS. // EN LA PRIMERA PREGUNTA, HACEMOS TRANSICIÓN PORQUE EL PASEO ESTABA VACÍO. SUPERA LA PRIMERA PREGUNTA Y NOS CUENTA QUE TÉCNICA DE LABORATORIO EN UNA CLÍNICA DE REPRODUCCIÓN ASISTIDA. SUPERA LA SEGUNDA PREGUNTA Y NOS EXPLICA QUE ANTES DE TRABAJAR EN EL LABORATORIO, SE DEDICÓ A LA DANZA DESDE LOS TRES AÑOS Y ESTUDIÓ LA CARRERA DE DANZA ESPAÑOLA DURANTE SEIS AÑOS. NOS DELEITA CON UNOS PASOS DE FLAMENCO Y SEGUIMOS. SUPERA LA TERCERA PREGUNTA Y CON EL DINERO LE GUSTARÍA COMPRARSE UNA CARAVANA PORQUE DE PEQUEÑA SIEMPRE VIAJÓ EN AUTOCARAVANA CON SUS PADRES. SUPERA LA CUARTA PREGUNTA Y DECIDE JUGAR. EN LA QUINTA PREGUNTA, AROA BUSCA UN PROFESORA Y ELIGE A UN MAESTRO DE SALAMANCA QUE SABÍA QUE TOLEDO ES CONOCIDA COMO LA CIUDAD DE LAS TRES CULTURAS.', 'Cristina', '2-', '22:27', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (613, @jornada_id_166, '2025-07-24', 'GIJÓN', 'MAITE', 31, 'AGENTE INMOBILIARIA', '@maitemg8', 638, 1000, '***CUESTIONARIO MUSICAL*** // REC 11:00 - 12:00 ARRANCAMOS A LAS PUERTAS DEL HOTEL ASTURIAS EN LA PLAZA MAYOR PORQUE ALLÍ SE RODÓ PARTE DE LA PELÍCULA "VOLVER A EMPEZAR", DE JOSÉ LUIS GARCI, LA PRIMERA PELÍCULA ESPAÑOLA EN ALZARSE CON EL OSCAR Y APROVECHANDO QUE ESTA CINTA ES UNA ODA A LAS SEGUNDAS OPORTUNIDADES, XUSO SE ACERCA A LOS TRANSEÚNTES PARA PREGUNTARLES SI ALGUNA VEZ HAN TENIDO QUE VOLVER A EMPEZAR EN LA VIDA. PRIMERO SE ACERCA A UNOS TÉCNICOS DE LUCES QUE ESTÁN MONTANDO UN ESCENARIO Y LES PROPONE CONCURSAR (SI TIENE BUEN CORTE, LEVANTAR TODA LA SECUENCIA CON LOS TÉCNICOS DE LUCES). DESPUÉS, SE ACERCA A UNA CHICA QUE NOS CONTESTA QUE SU VIDA HA ESTADO LLENA DE SEGUNDAS OPORTUNIDADES (A SUS AMIGOS, A SU FAMILIA, ETC). XUSO SIGUE ANDANDO Y PARA A DOS CHICAS MUY SIMPÁTICAS. UNA DE ELLAS NOS CONTESTA QUE HA VUELTO A EMPEZAR PORQUE SE SEPARÓ Y AHORA ESTÁ FELIZMENTE ENAMORADA, ASÍ QUE LA CAPTAMOS Y COMENZAMOS EL CONCURSO // EN LA PRIMERA PREGUNTA, LA ELEGIDA FALLA, SACAMOS LOS XUSÓKER Y SALE EL "CONTINÚE". MAITE SUPERA LA PRIMERA PREGUNTA Y NOS CUENTA QUE TIENE UN HIJO Y QUE SU ACTUAL PAREJA TAMBIÉN TIENE UN HIJO. ESTÁ MUY ENAMORADA Y TRABAJA EN UNA INMOBILIARA. SUPERA LA SEGUNDA PREGUNTA Y VAMOS DIRECTOS A LA TERCERA. (EN LA TERCERA, CORTAR CUANDO XUSO CANTA "EL DEL MEDIO DE LOS CHICHOS PORQUE AUNQUE LA ELEGIDA YA HA CONTESTADO CORRECTAMENTE, PODRÍA SER UNA PISTA). TRAS SUPERAR LA TERCERA PREGUNTA, NOS CUENTA QUE CON EL DINERO LE GUSTARÍA PAGAR LA HIPOTECA. SUPERA LA CUARTA PREGUNTA Y DECIDE PLANTARSE.', 'Cristina', '2', 'Arranque frente al hotel Asturias, donde se rodó la oscarizada "Volver a empezar".', '19:35', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (614, @jornada_id_166, '2025-07-24', 'GIJÓN', 'JOANA', 42, 'EMPRESARIA', '@joana.unaynomas', 621, 483, 'X2 SG
X50 N', 800, 'REC 12:36 - 13:23 ARRANCAMOS EN LA BARANDILLA QUE RODEA LA PLAYA DE SAN LORENZO CON XUSO Y "ROSE" (NUESTRA ROSA) INTERPRETANDO LA ESCENA DEL TITANIC HASTA QUE LES INTERRUMPIMOS. XUSO INTERACTÚA CON UNA PAREJA Y LES ANIMA A QUE TAMBIÉN INTERPRETEN ESTA MÍTICA ESCENA. CONTINUAMOS ANDANDO Y XUSO HABLA CON UNA SEÑORA Y LE PREGUNTA QUÉ ES LO QUE MÁS LE GUSTA DE LA PLAYA DE SAN LORENZO. CONTINUAMOS ANDANDO Y NOS TOPAMOS CON JOANA Y SU AMIGA QUE VAN A LA PLAYA. HABLA CON ELLAS Y CAPTAMOS A JOANA // EXPLICAMOS MECÁNICA Y XUSÓKER. JOANA SUPERA LA PRIMERA PREGUNTA Y NOS CUENTA QUE TIENE UNA EMPRESA DE "ESCAPE ROOMS", PERO QUE TAMBIÉN SE DEDICA A VENDER LOCALES, DESDE PISOS HASTA GARAJES. EN LA SEGUNDA PREGUNTA, ELIGE A UN SEÑOR QUE ACIERTA, SACAMOS LOS XUSÓKER Y VEMOS EL "AL VERRÉS". EN LA SEGUNDA OPORTUNIDAD, JOANA SUPERA LA SEGUNDA PREGUNTA. NO SUPERA LA TERCERA PREGUNTA, Y NOS CUENTA QUE CON EL DINERO LE GUSTARÍA PAGAR LA HIPOTECA, HACER UN VIAJE Y OPERARSE LA NARIZ. NO SUPERA LA CUARTA PREGUNTA Y DECIDE JUGAR. ABRIMOS LOS SOBRES Y VEMOS EL X50, PERO EN SU SOBRE HABÍA UN X2. SUPERA LA QUINTA PREGUNTA Y SE LLEVA 800 EUROS.', 'Cristina', '1+', 'Arranque simulación escena mítica Titanic.
Lleva explicación mecánica.', '22:57', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, duracion, valoracion_final) VALUES (615, @jornada_id_166, '2025-07-24', 'GIJÓN', 'MERCE', 42, 'DESEMPLEADA', 647, 472, 'X6 SG', 3600, 'REC 13:45 - 14:20 // ARRANCAMOS EN EL PASEO MARÍTIMO Y XUSO NOS CUENTA QUE VAMOS A SEGUIR AÑADIENDO PÁGINAS AL LIBRO DE "MUJERES CÉLEBRES" QUE INICIAMOS EN ALMERÍA CON CARMEN DE BURGOS PORQUE HOY QUE ESTAMOS EN ASTURIAS QUEREMOS RECORDAR A MARGARITA SALAS, UNA DE LAS CIENTÍFICAS MÁS CÉLEBRES DEL SIGLO XX (GRAFISMO: INSERTAR HOJA DE LIBRO COMO EN ALMERÍA CON EL TÍTULO "MUJERES CÉLEBRES" Y AÑADIR A MARGARITA SALAS. AÑADIR TAMBIÉN -DISCÍPULA DE SEVERO OCHOA -PIONERA DE LA BIOLOGÍA MOLECULAR -REFERENTE PARA GENERACIONES DE INVESTIGADORES). XUSO LE PREGUNTA A LOS MIEMBROS DEL EQUIPO SI HAY ALGUNA MUJER QUE LES HAYA INSPIRADO. CRISTINA CONTESTA FRIDA KAHLO, CHETE, AITANA BONMATÍ Y ROSA, ROSA PARKS. CONTINUAMOS ANDANDO Y XUSO PARA A UNA CHICA QUE CONTESTA SU MADRE Y SU ABUELA. SEGUIDAMENTE, SE PARA CON MERCE QUE CONTESTA JANE GOODALL, PORQUE LE ENCANTAN LOS ANIMALES. LA CAPTAMOS Y COMENZAMOS EL CONCURSO. SUPERA LA PRIMERA PREGUNTA Y NOS HABLA DE LAS MASCOTAS QUE TIENE EN CASA. SUPERA LA SEGUNDA PREGUNTA Y XUSO LE PREGUNTA QUÉ HOBBIES TIENE Y SI VIVE EN PAREJA (SI TIENE BUEN CORTE, YO LEVANTARÍA ESTA PREGUNTA PERSONAL PORQUE NO APORTA NADA E IRÍA DIRECTA A LA TERCERA PREGUNTA). EN LA TERCERA PREGUNTA, EL ELEGIDO NO SABE LA RESPUESTA, SACAMOS LOS XUSÓKER Y LE SALE EL RECICLA. LO VOLVEMOS A INTENTAR, PERO LA SEGUNDA ELEGIDA TAMPOCO SABE LA RESPUESTA (EN LA SEGUNDA ELEGIDA, XUSO FORMULA DOS VECES LA PREGUNTA, NOS QUEDAMOS CON LA SEGUNDA PORQUE ENTONA MEJOR). NO SUPERA LA TERCERA PREGUNTA Y NOS CUENTA QUE CON EL DINERO PAGARÍA UN VOLUTARIADO CON LEONES EN SUDÁFRICA. SUPERA LA CUARTA PREGUNTA Y DECIDE JUGAR. SUPERA LA QUINTA PREGUNTA Y GANA 3.600 EUROS.', 'Cristina', '2-', '20:33', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, duracion, valoracion_final) VALUES (616, @jornada_id_167, '2025-09-01', 'MADRID', 'JUANJO
PEDRO', 'FOTÓGRAFO
ADMINISTRATIVO', '@jjlezamiz
@peorti', 630, 442, 'X6 SG', 6000, 'TC IN: 16:51     TC OUT: 17:36
 EMPEZAMOS HACIENDO REFERENCIA A LA PLAZA DE LAS DESCALZAS AUNQUE TODOS LLEVAMOS ZAPATOS, MENOS CHETE QUE LLEVA LAS CROCS Y BROMEAMOS (HAY RECURSO DE SUS PIES). VEMOS A JUANJO QUE ESTÁ ESPERANDO A SU CHICO Y XUSO LE PROPONE DARLE UNA SORPRESA Y QUE CONCURSEN JUNTOS...Y ASÍ SUCEDE. NO SUPERAN LA PREGUNTA, UTILIZAN EL RECICLA Y CORREN MEJOR SUERTE. NOS CUENTAN QUE SE CONOCIERON EN UN BAR DE CHUECA HACE YA 19 AÑOS Y DESDE EL PRIMER MOMENTO FUE UN FLECHAZO. SUPERAN LA SEGUNDA Y TAMBIÉN LA TERCERA (CORTAR CUANDO XUSO NOMBRA A LOS OTROS MONARCAS ADEMÁS DE ALFONSO XIII QUE LO HACE Y DICE MAL, PERO DEJAD CÓMO EXPLICA LA NOTA SOBRE ALFONSO XIII, ES IMPORTANTE MATIZAR). NOS CUENTA QUE EL DINERO LO QUERRÍAN PARA PAGAR DEUDAS Y HACERSE UNA BUENA ESCAPADA, YA QUE LOS FINES DE SEMANA LLEVAN UN ASADOR DE POLLOS QUE ERA DE LA FAMILIA DE PEDRO Y APENAS HAN TENIDO DÍAS LIBRES EN TODO EL VERANO. SUPERAN TAMBIÉN LA CUARTA Y SE LA JUEGAN, COGIENDO UN X6. ELIGEN A UNA CHICA ARGENTINA (CORTAR EL MOMENTO QUE SALE CON EL VINO, XUSO RETOMA Y ESE PLANO PUEDE PASAR POR UN CORTO) AUNQUE AL PRINCIPIO SE LÍA DICIENDO "MONALISA", XUSO LE REPITE LA PREGUNTA Y YA DA CON LA TECLA. LES HACE GANAR LOS 6000 EUROS Y SE VAN TAN CONTENTOS.', 'Leandro', '3', '22:45', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (617, @jornada_id_167, '2025-09-01', 'MADRID', 'SOLE', 61, 'ENCARGADA DE TIENDA', 'NO TIENE', 632, 600, '***CUESTIONARIO MUSICAL***
 TC IN: 18:00    TC OUT; 18:36
 XUSO CAMINA POR LA CALLE Y SE CRUZA CON SOLE Y SU COMPAÑERO DE TRABAJO. ELLA SE QUEDA PASMADA Y NO SE LO PUEDE CREER. VIENEN DE COMPRARLE EL REGALO DE CUMPLE A OTRO COMPAÑERO Y LE CUENTA A XUSO EN SECRETO QUE LES HA TOCADO 48 EUROS, 
PERO ELLA NO SABE QUE EL MICRO LA ESTABA ESCUCHANDO. SOLE ACEPTA CONCURSAR Y CUANDO VE EL MICRO DEL MUSICAL SE PARTE DE RISA CON XUSO. EMPEZAMOS SUPERANDO LA PRIMERA (HAGO UNA PERFORMANCE CON LA ELEGIDA CANTANDO) Y SOLE DICE QUE 
ELLA ES MUY FARANDULERA Y LE ENCANTA LA MÚSICA, NOS CANTA UN TROCITO DE "MEDITERRÁNEO" DE SERRAT. SUPERA LA SEGUNDA Y PASAMOS A LA TERCERA, PERO NO CORRE TANTA SUERTE Y NO LA SUPERA NI A LA PRIMERA NI CON EL XUSÓKER. NOS CUENTA QUE CON EL DINERO QUIERE HACERSE UN VIAJE A NUEVA YORK PARA VER ALGÚN MUSICAL, YA QUE ELLA TIENE UN GRUPO AMATEUR DE TEATRO. SE VUELVEN A PARTIR DE RISA CUANDO XUSO LE PIDE UN SOLILOQUIO Y ELLA HACE UNA REPRESENTACIÓN DE UNA OBRA. SUPERA LA CUARTA Y DECIDE PLANTARSE CON LOS 600 EUROS PORQUE TIENE QUE HACER UNOS PAGOS Y LE VIENE BIEN.', 'Leandro', '3+', 'Cuestionario musical.', '21:38', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, duracion, valoracion_final) VALUES (618, @jornada_id_167, '2025-09-01', 'MADRID', 'CARLOS', 29, 'MÚSICO Y TÉCNICO AUDIOVISUAL', '@choley.y', 620, 208, 'X30 SP', 0, 'TC IN: 19:13   TC OUT: 20:08 
EMPEZAMOS EN EL OSO Y EL MADROÑO Y XUSO HABLA DE LA LEYENDA QUE DICE QUE SI LE TOCAS EL OSO AL CULO VUELVES A MADRID Y TIENES SUERTE. UNA CHICA SE HACE UNA FOTO Y XUSO LA COGE EN BRAZOS PARA QUE TOQUE EL CULO DEL OSO Y LA SEÑORA LO CONFUNDE CON ÓSCAR CASAS (SE PARTE DE RISA, SE PUEDE PONER EN GRAFISMO AL LADO PARA COMPARACIÓN, ÉL HA HECHO REFERENCIA). BAJA CARLOS Y TAMBIÉN LO ANIMA A TOCARLE EL CULO AL OSO, Y YA DE PASO, LE PROPONE CONCURSAR. LA PRIMERA NO LA SUPERA PORQUE EL SEÑOR CREE QUE TIENE QUE NO SABERLA. LA LLAMADA A SU HERMANO LO SALVA. (AQUÍ HAY UNA SALIDA DE PLANO ABSURDA Y NO JUSTIFICADA PORQUE XUSO SE PUSO NERVIOSO Y AGOBIADO, ASÍ QUE HABRÁ QUE COMÉRSELA CON PATATAS). CARLOS NOS CUENTA QUE SE DEDICA A LA MÚSICA Y ESTÁ EN PROCESO DE SACAR UN ÁLBUM, NOS CANTA UN POCO PERO MUY POCO. LA SEGUNDA LA SUPERA Y PARA LA TERCERA ELIGE A UNA CHICA ARGENTINA QUE, AUNQUE CONOCE LA PELÍCULA, NO SABE QUE ES LUZ CASAL. CARLOS NOS CUENTA QUE QUIERE EL DINERO PARA SEGUIR INVIRTIENDO EN PRODUCCIÓN MUSICAL, YA QUE ES BASTANTE CARA. LA CUARTA TAMPOCO LA SUPERA, DECIDE MULTIPLICAR Y HACEMOS APERTURA DE SOBRES, HABIENDO ELEGIDO ÉL UN X30. LA CHICA SELECCIONADA ES MEXICANA Y SOLO CONOCE A VERDELISS DE INFLUENCER ESPAÑOLAS, ASÍ QUE DICE MARCO EN VEZ DE MARTÍN, Y LE HACE PERDER 12.000 EUROS A CARLOS QUE SE VA DE VACÍO.', 'Leandro', '2-', '23:46', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (619, @jornada_id_167, '2025-09-01', 'MADRID', 'ALI', 25, 'MAESTRA EDUCACIÓN ESPECIAL', '@aalimaavi', 629, 489, 'X8 SG', 8000, 'TC IN: 20:30    TC OUT: 21:22
 HACEMOS ACTING DE MENSAJES BONITOS (3-4 PERSONAS) Y LLEGAMOS A ALI, QUE DICE QUE LA PERSONA MÁS IMPORTANTE DE SU VIDA ES SU ABUELA Y XUSO LA ANIMA A LLAMARLA PARA QUE SE LO DIGA. LO HACEMOS Y ALI SE ANIMA A CONCURSAR CON NOSOTROS. EMPEZAMOS BIEN SUPERANDO LA PRIMERA Y ALI NOS CUENTA QUE ES PROFESORA DE EDUCACIÓN ESPECIAL CON NIÑOS CON AUTISMO. LA SEGUNDA TAMBIÉN LA SUPERA Y DESCUBRIMOS QUE ALI ES CANTANTE Y HACE CONCIERTOS PARA DONAR DINERO A ASOCIACIONES BENÉFICAS. NOS CANTA UN TROCITO DE UNA CANCIÓN QUE LE DEDICÓ A SU ABUELO QUE MURIÓ. LA TERCERA TAMBIÉN LA SUPERA Y NOS CUENTA QUE EL DINERO LO QUIERE PARA DONARLO A ASOCIACIONES QUE LO NECESITEN, AUNQUE UNA PARTE LO DEJARÍA PARA HACER UN VIAJE CON SU ABUELA QUE NUNCA HA MONTADO EN AVIÓN. ALI SUPERA LA CUARTA PREGUNTA Y DECIDE MULTIPLICAR...XUSO ABRE EL SOBRE Y HAY UN X8. ALI SE TOMA SU TIEMPO PARA ESCOGER Y ELIGE A UN SEÑOR MAYOR QUE ES FRANCÉS PERO LLEVA DESDE 1964 EN ESPAÑA. NO SABE LA RESPUESTA Y ALI GANA LOS 8000 EUROS, LLORA DE EMOCIÓN Y ANIMA A TODO EL MUNDO A DONAR PORQUE HAY GENTE QUE SUFRE MUCHO. XUSO LE PIDE LLAMAR A SU ABUELA PARA CONTÁRSELO Y LA EMOCIÓN SIGUE FLUYENDO. UN CONCURSO MARAVILLOSO.', 'Leandro', '3+', 'Acting MENSAJES BONITOS. 
Anochece', '24:47', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (620, @jornada_id_168, '2025-09-02', 'FUENLABRADA', 'JUAN', 29, 'POLICÍA NACIONAL', '@gundojuan20', 667, 478, 'X2 SG', 1200, 'TC IN: 11:36    TC OUT: 12:16
 XUSO VA EN BUSCA DE FERNANDO TORRES Y LE PREGUNTA A LOS VECINOS. SE ENCUENTRA CON AMPARO (QUE LUEGO CONCURSARÁ), LUEGO A UNOS CARNICEROS QUE NOS INVITAN A JAMÓN Y JUAN NOS DICE QUE ES FUTBOLERO Y FAN DEL ATLETI, NOS SACA SU ABONO Y TIENE LA FOTO DE FERNANDO TORRES. XUSO LE PROPONE CONCURSAR Y ÉL ACEPTA ENCANTADO, Y YA NOS ADELANTA QUE HA SIDO PADRE HACE POCO. SUPERA LA PRIMERA Y NOS CUENTA EL TIEMPO QUE LLEVA CON SU CHICA, CÓMO SE CONOCIERON Y LA LLEGADA DEL BEBÉ. CON LA SEGUNDA TAMBIÉN TIENE SUERTE Y AHORA NOS HABLA DE SU PROFESIÓN. ES POLICÍA DE VOCACIÓN Y CON 21 AÑOS YA ESTABA DENTRO DEL CUERPO. SE LO PASA BIEN Y ADEMÁS ES MUY NERVIOSO Y ÉL RECONOCE QUE NO PODRÍA ESTAR EN UNA OFICINA. LA TERCERA NO LA SUPERA, PERO LE SALE LA LLAMADA DE EMERGENCIA Y UN AMIGO SUYO LE HACE ALCANZAR LOS 600 EUROS. NOS CUENTA PARA QUÉ QUIERE EL DINERO: QUIERE CASARSE CON SU CHICA Y FORMAR UNA BUENA CELEBRACIÓN. PARA A UNA SEÑORA MAYOR QUE ESTÁ ENCANTADA DE VER A XUSO, PERO SABE LA RESPUESTA Y JUAN NO LLEGA A COMPLETAR EL PLENO. DECIDE JUGÁRSELA PERO LE SALE EL X2 (YO AQUÍ ME EQUIVOQUÉ PORQUE ERA UN COMBO R, YA AVISÉ A SARA). PARA A UN SEÑOR MAYOR QUE NO TIENE NI IDEA Y SE HACE CON EL PREMIO.', 'Leandro', '3', 'Arranque con mención a Fernando Torres. 
¡OJO! Este concursante tiene que ir programado antes del #622#.', '23:05', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (621, @jornada_id_168, '2025-09-02', 'FUENLABRADA', 'CARMEN', 45, 'ADMINISTRATIVA', 'NO TIENE', 655, 469, 'X2 SP', 0, '***CUESTIONARIO MUSICAL*** TC IN: 12:17 TC OUT: 13:14
 XUSO VA PASEANDO Y UNA CHICA SE LE ACERCA DICIENDO QUE VERANEA EN LOS ALCÁZARES, EN MURCIA. XUSO LE LLAMA LA ATENCIÓN Y LA INVITA A CONCURSAR. LE TOCA CUESTIONARIO MUSICAL Y NO SUPERA LA PRIMERA, LE SALE EL AL VERRÉS Y TIENE MÁS SUERTE CON UNA SEÑORA QUE ADEMÁS ES CANTANTE, TIENE UN DISCO Y NOS CANTA EN DIRECTO. CARMEN DICE QUE SIEMPRE LE HA GUSTADO VERANEAR EN LOS ALCAZARES Y XUSO ENFATIZA TODAS LAS COSAS BUENAS DE LA REGIÓN A TRAVÉS DE CARMEN. SUPERA SEGUNDA Y TAMBIÉN LA CUARTA GRACIAS A YOLANDA, UNA CHICA QUE VA CON MULETAS Y ES FAN DE XUSO, LE ENCANTA EL FLAMENCO Y NOS DELEITA CON UN TROZO DE UNA CANCIÓN DE CAMARÓN. CARMEN QUIERE EL DINERO PARA COMPRARSE UNA CASA EN LA PLAYA Y PARA UNA ESPALDA NUEVA, YA QUE HA ESTADO CASI TODO EL AÑO DE BAJA. SUPERA LA CUARTA, ES SOBRE JUSTIN BIEBER Y XUSO CUENTA QUE FUE TELONERO Y, LA ELEGIDA, LO ATENDIÓ EN UN HOTEL DE MADRID CUANDO FUE DE VISITA CON SU MADRE. CARMEN DECIDE JUGÁRSELA, LE SALE EL X2 PERO LA CHICA NO LA SABE Y SE VA SIN NADA.', 'Leandro', '2', 'Cuestionario musical. 
Elegidos muy buenos. 
Xuso cuenta que fue telonero de Justin Bieber.', '23:58', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (622, @jornada_id_168, '2025-09-02', 'FUENLABRADA', 'AMPARO', 84, 'JUBILADA', 'NO TIENE', 668, 600, 'TC IN: 13:27 TC OUT: 14:03
 ARRANCAMOS EN AYUNTAMIENTO Y LEANDRO HACE LLAMAMIENTO PARA DAR EL PREGÓN DE SU PUEBLO. XUSO VUELVE A ENCONTRARSE CON AMPARO (APARECE CAPTACIÓN CONCURSANTE 620) Y LE PREGUNTA SI YA HA ECHADO LAS LENTEJAS Y SI PUEDE CONCURSAR AHORA. AHORA SÍ QUE SE 
ANIMA Y DESPUÉS DE MUCHAS RISAS EMPEZAMOS. SUPERA LA PRIMERA CON ÉXITO Y AMPARO NOS CUENTA COMO HA SIDO SU VIDA: EMIGRÓ A 
BÉLGICA CON SU MARIDO, PASARON PENURIAS, SU MARIDO MURIÓ EL DÍA DE SU CUMPLEAÑOS... UN POCO DE TODO. LA SEGUNDA ELEGIDA CONOCE A 
AMPARO Y NOS CUENTA QUE VENDÍA FRUTOS SECOS CUANDO ELLA ERA PEQUEÑA, NO LA SABE Y LA SUPERA. XUSO APROVECHA PARA PREGUNTARLE A 
AMPARO POR EL NEGOCIO QUE ELLA TENÍA POR AQUEL ENTONCES Y NOS CUENTA QUE HAY NIÑOS QUE LE ROBABAN INCLUSO, PERO TODO CON 
MUCHA GRACIA Y DESVARÍO, ELLA NO SE CENTRA EN NINGÚN MOMENTO. PARA LA TERCERA COGE A UNA SEÑORA QUE NO TIENE IDEA Y AMPARO 
LLEGA INCLUSO A CABREARSE, PERO EN LOS XUSOKER SALE EL CONTINUE Y TODO SE ARREGLA. AMPARO QUIERE EL DINERO PARA COMPRARLE UN 
TRICICLO A SU BISNIETO, QUE LA TIENE LOCA Y LE HA DADO MUCHA VIDA. ELIGE A UNA CHICA QUE SABE LA RESPUESTA Y NO CONSIGUE HACER PLENO, 
PERO AMPARO TIENE CLARO QUE SE VA A PLANTAR Y SE METE EL FAJO DE BILLETES ENTRE LOS PECHOS. XUSO SE VA CON ELLA A COMERSE LAS 
LENTEJAS.', 'Leandro', '3+', '¡OJO! Esta concursante aparece en el arranque del #620#. No es indispensable que vayan pegados, pero sí que esta salga en emisión, ya en el mismo programa con otro entre medias, o en otro programa posterior.', '22:48', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion) VALUES (623, @jornada_id_168, '2025-09-02', 'FUENLABRADA', 'JOSE', 34, 'TATUADOR', '@josedonvito', 672, 486, 'X2 SG', 2000, 'TC IN: 16:19   TC OUT: 17:18
 XUSO ARRANCA EN EL MURAL DE LA SIRENA HACIENDO REFERENCIA AL MAUF DE FUENLABRADA Y RECALCA QUE ES DEL MISMO AUTOR DEL MURAL 
QUE VIMOS EN EL PALACIO DE VISTALEGRE. NOS CRUZAMOS CON UN CHICO Y XUSO SE FIJA EN SUS TATUAJES, LE PROPONE CONCURSAR Y ACEPTA. 
ANTES DE ARRANCAR LE PREGUNTA DE NUEVO POR LOS TATUAJES Y JOSE DICE QUE ES TATUADOR. XUSO LLAMA A FELIPE Y RECORDAMOS LA PROMESA 
QUE HIZO DE TATUARSE EL LOGO SI HACÍAMOS UN AÑO DE EMISIÓN (esto está en el concursante #402#) Y EL SONIDISTA ACEPTA TATUARSE DESPUÉS DEL CONCURSO. JOSE SUPERA LA 
PRIMERA CON ÉXITO Y NOS CUENTA SOBRE SU ESTUDIO, ANTES LO TENÍA EL MÓSTOLES Y AHORA SE HAN TRASLADADO A FUENLABRADA, POR LO QUE 
EL DINERO LE VENDRÍA GENIAL. SUPERA TAMBIÉN LA SEGUNDA Y AQUÍ NOS ENSEÑA ALGUNOS DE SUS TATUAJES Y EXPLICA LOS SIGNIFICADOS QUE 
TIENEN PARA ÉL. SUPERA LA TERCERA, NOS CUENTA QUÉ ES LO QUE QUIERE HACER CON EL DINERO Y PARA LA CUARTA ELIGE A UN CHICO QUE PASA 
POR LA OTRA ACERA (CRUZA SIN PASO DE PEATONES, SI HAY PROBLEMA LEGAL QUE CORTEN EL CRUZADO). EL CHICO NO LA SABE Y JOSE HACE PLENO 
DE 1000 EUROS. DECIDE JUGÁRSELA, ABRIMOS SOBRES Y EN UNO DESCARTADO ESTÁ EL X14, Y ÉL HA ELEGIDO EL X2. JOSE SE ENTRISTECE E INCLUSO 
CABREA, PERO LA PREGUNTA ES SOBRE UN FAMOSO QUE SE TATUÓ Y VE POR LA CALLE A UN CHICO TATUADOR, LO ELIGE Y SABE LA RESPUESTA. GANA 
LOS 2000 EUROS Y DE AHÍ NOS VAMOS AL ESTUDIO, VEMOS YA A FELIPE SENTADO Y A JOSE CON LA MÁQUINA PREPARADA, NOS DESPEDIMOS DEL 
COMPAÑERO Y ÉL TAPA LA CÁMARA (IRÁ CRUZADO CON LA RESOLUCIÓN DEL TATUAJE)', 'Leandro', '2+', 'Termina con el arranque del tatuaje de Felipe. Lo descubriremos en el inicio del concursante #635# de Cuenca. Deberán ir seguidos en escaleta.', '24:26');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, duracion, valoracion_final) VALUES (624, @jornada_id_169, '2025-09-03', 'ALCORCÓN', 'SANDRA', 24, 'PERIODISTA', '@sandritagb9', 656, 1000, 'TC IN: 10:02   TC OUT: 10:33
 XUSO HACE REFERENCIA AL MONUMENTO DE LA PATRONA DE ALCORCÓN Y SE PARA A HABLAR CON UN VECINO QUE DICE QUE ESTA CALLE SOLO HAY DETERMINADAS TIENDAS PORQUE HAY MUCHA GENTE MAYOR (ES GRACIOSO, PERO ES QUE NO ME ACUERDO BIEN QUÉ DIJO). SE ENCUENTRA CON SANDRA, TODA UNA DIVA, QUE BROMEA CON XUSO Y SABE QUE ESTAMOS HACIENDO EL PROGRAMA. VIENE DE MERENDAR E IBA A CASA, ASÍ QUE CONCURSA. SUPERA LA PRIMERA PREGUNTA Y NOS CUENTA QUE ES PERIODISTA AUNQUE AHORA BUSCA TRABAJO, Y XUSO LE OFRECE HACER UN ALEGATO A LOS JEFES DE MEDIASET. LEANDRO DICE QUE, SI HAY VACANTE, LA PODEMOS METER AL PROGRAMA. LA SEGUNDA TAMBIÉN LA SUPERA Y XUSO LE PREGUNTA POR SUS HOBBIES. ELLA DICE QUE ES FAN DEL MAQUILLAJE Y SIEMPRE VA MUY BIEN EQUIPADA. SACA DE SU BOLSO UN CEPILLO, LOS POLVOS DE MAQUILLAJE, EL ESPEJO...¡Y HASTA UN ABANICO DE BRILLI-BRILLI! SANDRA SUPERA LA TERCERA Y NOS CONFIESA QUE QUIERE EL DINERO PARA COMPRARSE UNA CASA Y TAMBIÉN PARA HACER UN VIAJE A LA HABANA, UN LUGAR QUE SIEMPRE LE HA LLAMADO LA ATENCIÓN. SANDRA CONSIGUE HACER PLENO DE 1000 EUROS Y DICE QUE PENSABA JUGÁRSELA, PERO CON LOS 1000 EUROS EN LA MANO LO VE DE OTRA MANERA Y SE PLANTA.', 'Leandro', '3', '19:10', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, duracion, valoracion_final) VALUES (625, @jornada_id_169, '2025-09-03', 'ALCORCÓN', 'ISABEL', 60, 'BARRENDERA', 'NO TIENE', 648, 1000, 'TC IN: 10:34   TC OUT: 11:18
 XUSO VA PASEANDO POR LAS CALLES DE ALCORCÓN, SE ACERCA A UNAS CHICAS QUE ESTÁN TRABAJANDO Y NO PUEDEN CONCURSAR PERO SON SÚPER FAN. UNA SEÑORA SE LE ACERCA Y LE DICE QUE ES MÁS GUAPO EN PERSONA. ISABEL IBA CON SUS HIJAS A ACOMPAÑARLAS A TRABAJAR PERO CUANDO XUSO LE HACE LA OFERTA PARA CONCURSAR, NO SE LO PIENSA NI UN SEGUNDO. EMPEZAMOS EL CONCURSO BIEN SUPERANDO LA PRIMERA Y DICE QUE CON ESO TIENE "PARA EL AVIÓN", Y LO DEJA EN ALTO... NOS CUENTA QUE ES BARRENDERA LOS FINES DE SEMANA Y FESTIVOS Y LE ENCANTA SU TRABAJO, AUNQUE DENUNCIA LO POCO CÍVICA QUE ES LA GENTE EN LA CALLE. LA SEGUNDA TAMBIÉN LA SUPERA Y DICE QUE CON ESO TIENE "PARA ALGUNA COMIDA". CON LA TERCERA TAMBIÉN TIENE SUERTE Y LLEGANDO A LA CUARTA, XUSO LE PREGUNTA CUÁL ES EL VIAJE QUE QUIERE HACER Y QUE LE ESTÁ CEBANDO TODO EL RATO. ISABEL RECONOCE QUE ES MUY FAN DE ELVIS Y QUIERE HACER SU RUTA: MENFIS, LAS VEGAS Y HAWAII. ISABEL CONSIGUE HACER PLENO DE SEGUIDO Y CUANDO XUSO LE PREGUNTA QUÉ VA A HACER, ELLA DICE QUE CON 1000 EUROS NO LE DA PARA IR A LAS VEGAS, PERO SÍ PARA REPONERSE DE LAS VACACIONES DE VERANO. ASÍ QUE, SE PLANTA.', 'Leandro', '2+', '16:39', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (626, @jornada_id_169, '2025-09-03', 'ALCORCÓN', 'RICARDO
ALESSANDRO', 'ESTUDIANTES', '@ricardomaatos_
@fantuzziiii', 633, 437, 'X5 SP', 0, 'TC IN: 11:53     TC OUT: 12:34
 XUSO HACE REFERENCIA AL MONUMENTO A LOS ABUELOS Y LA IMPORTANCIA QUE TIENEN. HABLA CON UNOS SEÑORES QUE ESTÁN EN EL BANCO DE AL LADO Y MANDAN SALUDOS A SUS NIETOS. SE ACERCA A DOS CHICOS QUE ESTÁN EN UN BANCO Y LES PREGUNTA SI SON BUENOS NIETOS. ELLOS DICEN QUE SÍ, AUNQUE TIENEN ABUELOS EN VENEZUELA E ITALIA Y NO LOS PUEDEN VER TANTO COMO QUERRÍAN. XUSO LES PREGUNTA QUÉ HACEN Y ELLOS LE RESPONDEN QUE IBAN A LAS FIESTAS UN RATO, PERO LES PROPONE CONCURSAR Y SUS PLANES CAMBIAN. SUPERAN LA PRIMERA Y NOS CUENTAN QUE SON AMIGOS DESDE CASI ANTES DE NACER, QUE SUS FAMILIAS SON AMIGAS Y SE CONOCEN DESDE SIEMPRE. NOS HABLAN DE SUS ORÍGENES Y VUELVEN A HABLAR DE SUS ABUELOS EXTRANJEROS Y LA SITUACIÓN QUE TIENEN ACTUALMENTE (YA SON MAYORES, POCA MOVILIDAD, ETC). LA SEGUNDA TAMBIÉN LA SUPERAN Y XUSO LES PREGUNTA POR ANÉCDOTAS JUNTOS. DICEN QUE TIENEN MIL Y MUCHAS EN MURCIA, PORQUE SUELEN IR A MAZARRÓN. RICARDO DICE QUE LE HACE LA COBERTURA A ALESSANDRO PARA LIGAR, PORQUE ÉL YA TIENE NOVIA. LA TERCERA NO LA SUPERAN, SACAMOS LOS XUSÓKERS Y LES SALE EL CONTINÚE. RICARDO QUIERE EL DINERO PARA PAGAR SUS ESTUDIOS Y ALESSANDRO DICE QUE AÚN ES MUY JOVEN PARA MANEJAR DINERO, ASI QUE DELEGARÍA EN SUS PADRES. SUPERAN LA CUARTA Y, EN EL MOMENTO DE DECIDIR, ALESSANDRO NO QUIERE JUGÁRSELA Y RICARDO SÍ. TRAS UNA LARGA DECISIÓN, DECIDEN JUGARLO A PIEDRA, PAPEL O TIJERA...Y GANA RICARDO. PASAMOS LOS SOBRES Y LES SALE UN X5, ALESSANDRO ESTÁ ATACADO DE LOS NERVIOS. ELIGEN Y ELIGEN MAL, PORQUE LA SEÑORA LO SABÍA Y NO TENÍA QUE SER ASÍ. SE VIENEN ABAJO Y, AUNQUE NO DEBÍA HACERLO, XUSO LES ADVIERTE QUE AQUÍ HACEMOS SEGUNDAS OPORTUNIDADES (LA MERECEN MUCHO)', 'Leandro', '3', 'Candidatos SEGUNDA OPORTUNIDAD.', '23:49', '1');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, duracion, valoracion_final) VALUES (627, @jornada_id_169, '2025-09-03', 'ALCORCÓN', 'ANDRÉS', 63, 'FERROVIARIO', 653, 462, 'X8 N', 2000, 'TC IN: 12:35    TC OUT: 13:22
 XUSO CAMINA Y HABLA CON LOS VECINOS DEL PUEBLO (QUITAR A AMPARO, UNA SEÑORA MAYOR QUE NO FIRMA). SE FIJA EN UN SEÑOR QUE VA CON GAFAS DE SOL Y BROMEA CON ÉL AFIRMANDO QUE PARECE QUE VA DE DETECTIVE. ANDRÉS ESTÁ PASEANDO Y ACEPTA LA OFERTA DE XUSO PARA CONCURSAR, YA QUE ESTÁ PREJUBILADO Y TIENE POCO QUE HACER. EMPEZAMOS CON BUEN PIE SUPERANDO LA PRIMERA Y ANDRÉS NOS CUENTA QUE EN DOS MESES SE VA A JUBILAR, QUE HA TRABAJADO TODA LA VIDA COMO FERROVIARIO Y SE VA A IR A VIVIR A JAÉN, YA QUE SU MUJER ES DE AHÍ, Y EMPEZARÁN OTRA ETAPA DE LA VIDA. LA SEGUNDA TAMBIÉN LA SUPERA Y ANDRÉS NOS HABLA DE LA FAMILIA QUE TIENE, SOBRE TODO DE SU NIETA DE 5 AÑOS QUE ES SU LOCURA Y ESO HARÁ QUE DE ALGUNA MANERA ESTÉ UNIDO A MADRID AUNQUE VIVA EN EL SUR. EN LA TERCERA PINCHA Y TENEMOS QUE USAR LOS XUSÓKER, PERO AFORTUNADAMENTE NOS SALE UN CONTINÚE Y ACUMULA LOS 600 EUROS DIRECTAMENTE. ANDRÉS INVERTIRÍA EL DINERO EN AYUDAR A SUS HIJOS Y, COMO VAN A CAMBIAR DE CASA, UNA PARTE IRÍA TAMBIÉN DEDICADO A REFORMAR EL PISO DE JAÉN. LA CUARTA LA SUPERA GRACIAS A UN SEÑOR MAYOR Y HACE PLENO. ANDRÉS SE LA JUEGA, HACEMOS APERTURA DE SOBRES Y DESCUBRIMOS QUE HEMOS DEJADO PASAR UN X8, ÉL HA COGIDO EL X2. ANDRÉS ELIGE BIEN Y GANA LOS 2000 EUROS.', 'Leandro', '2+', '18:17', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados) VALUES (628, @jornada_id_170, '2025-09-09', 'MADRID', 'JOSÉ
JORGE', 44, 'ADMINISTRATIVOS', '@joseph_mcp
@jorge_candels', 652, 468, 'X9 SP
Abren todos', 0, '16:00 - 16:59. Xuso canta "mírala, mírala, la puerta de Alcalá" y comenta que era una de las puertas de entrada a la ciudad de Madrid y que busca alguien que le 
entre a él por la puerta grande. Aparece una familia que son fans y entra una niña (cortar) y luego entra el padre que se declara muy aficionado al programa, pero no 
puede concursar. Aparecen los gemelos y Xuso se queda loco con lo mucho que se parecen y les hace concursantes. Explicamos mecánica. Comienzan y aparece un 
guiri que se mete en medio del equipo y va igual vestido, y Xuso se queda flipando porque no lo conoce. No tenemos derechos, pero Alberto Durán dice que no pasa 
nada (consultar de nuevo). La primera pregunta les parece fácil y paran a un chico joven, Alexis, que acierta y le dice a Xuso que quiere concursar. Xuso pregunta por 
las peculiaridades de los gemelos, y cuentan que son muy gemelos, que viven juntos y comparten todo. Y que les confunden con mucha frecuencia. Vamos a la 
segunda pregunta y paran a un chico tartamudo, este chico acierta y tenemos que sacar los Xusóquer. Les sale un AL VERRÉS y eligen a un señor maduro, Juan Carlos, 
que responde "igualdad". No ganan los 400. Xuso les pregunta por la leyenda de que los gemelos sienten lo mismo y ellos explican que no es así, pero les pasan cosas 
idénticas con frecuencia. Vamos a la tercera y eligen a un señor maduro que resulta ser de Jerez, como ellos. El señor acierta y ellos se alegran mucho y le dicen su 
dirección en Jerez. Cuentan que el dinero sería para un coche, aunque solo uno conduce, y para llevarse a sus padres de viaje, porque no salen nunca de casa. En la 
cuarta pregunta paran a una chica de 18 años llamada Amalia que está tan asustada que ni piensa y dice "2". Gana los 600 y Xuso les deja debatir. Deciden jugársela. 
Abrimos sobres y justo les sale un x9 (abrimos todos). No saben la respuesta y buscan alguien que lea, ven de lejos a una chica leyendo y luego nos dirá que no. asi 
que regresamos al inicio para la búsqueda (cortar en edición). Eligen a otra chica de Jerez casualmente y ésta no sabe nada de literatura y se van a casa con la 
camiseta.', 'Adriana', '2+', 'Arranque en la Puerta de Alcalá. 
Hermanos gemelos. 
Apertura sobres');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion) VALUES (629, @jornada_id_170, '2025-09-09', 'MADRID', 'ILLANA', 29, 'PRODUCTOR MUSICAL', '@illana_96', 650, 1000, 'CUESTIONARIO MUSICAL ♫
 17:25 - 18:05. Xuso habla sobre los artistas callejeros que regalan su arte en el parque, como un señor que pinta cuadros, y una chica que toca el arpa. Se sienta con ella y ella le hace una masterclass sobre el instrumento, pero reniega de concursar. Sigue y ve a Illana con su amigo Jose, que están cantando. Hay unas señoras que bailan y Xuso va a bailar con una de ellas. Los chicos terminan de cantar y Xuso les invita a concursar. Ellos se lo juegan a piedra, papel y tijera y gana Illana. Arrancan y en la primera pregunta argumenta muy bien el perfil que busca, de músico. Pero lo que encuentra es un chico de Linares que sin pinta de músico, acierta. Illana le canta bamboleo como agradecimiento. Con los primeros 200 nos cuenta que su pasión por la música nace el día que su abuelo le regala una guitarra con 13 años. Después ha tocado en muchos sitios y ahora es productor musical. Vamos a la segunda y como sabe la rspuesta busca a alguien mayor. Coge a Marina, que le va la música de los 70, y no sabe quien es Bad Bunny. Gana los 400 y Xuso le pregunta por el autotune (eliminar) y luego por si tiene pareja y nos habla de que vive con su suegra y que se llevan genial. En la tercera pregunta decide buscar mujeres porque son más emocionales y coge a Carmen, de Tenerife, que canta la canción y acierta. Cristian nos cuenta que con el dinero se haría un viaje porque nunca ha salido de España y también compraría material para el estudio. En la cuarta busca a alguien extranjero, porque igual no conocen la canción y coge a un mexicano que está sentado en un banco con el amigo de Illana. El mexicano dice "casa" e Illana se lleva los mil euros. Consulta a su amigo sobre qué decisión tomar y hay una conversación graciosa, pero al final se planta porque sabe lo que cuesta ganar ese dinero.', 'Adriana', '2', 'Captación músico callejero. 
Cuestionario musical.', '23:36');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, duracion) VALUES (630, @jornada_id_170, '2025-09-09', 'MADRID', 'MARGARITA', 628, 'JUBILADA', 'NO TIENE', 628, 485, 'X2 SP', 0, '18:29 - 19:09. Xuso llama a los que están en las barcas para que concursen, pero nadie le responde y decide buscar por el retiro. Enseguida ve a Margarita, que tiene un look muy potente y ella le cuenta que es de Almería y está paseando con sus nietas por el retiro, de visita. A Xuso le enamora y ella es fan del programa, así que la hace concursante. Explicamos mecánica y arrancamos con la primera pregunta. Ella es lanzada y va eligiendo sin pensar y es un poco caos al inicio porque le vale cualquiera y muchos no se paran. Al final elige a Tania, una gitana que no ha probado en su vida el bacalao al pil pil. Sacamos el XUSÓQUER y le sale un CONTINÚE. Nos cuenta que no le gusta cocinar, que le gustan las manualidades y estar con la familia, que tiene 3 hijos. Un hijo es banderillero y está ahora mismo toreando, lo cual le pone muy nerviosa. Otra hija trabaja en el congreso de los diputados y la tercera es dependienta. Vamos a la segunda pregunta y para a una chica latina que no sabe la respuesta. Gana los 400 y nos cuenta que está viuda, pero tuvo el mejor marido que se puede tener. Da un discurso muy tierno sobre el marido. Vamos a la tercera y nos cuesta mucho encontrar a quién se pare, hasta que damos con Antonio, que responde Iniesta y no super la pregunta. Nos cuenta que el dinero sería para sus nietas y para un viaje. Para la cuarta pregunta para a Adrián, que resulta ser latino, y vendedor de chucherías en Bilbao. Adrián no sabe la respuesta y gana los 600€. Se arriesga y le sale un x2. es muy graciosa porque le pida a Xuso que mienta. No le gusta nada la pregunta que le ha salido y no sabe quién es Marc Anthony. Para a una chica de 18 años que duda entre Reino Unido y EE.UU. y se decanta por la primera, haciendo que Margarita se vaya con la camiseta a tomar un chilipú con Xuso.', 'Adriana', '1', '25:06');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados) VALUES (631, @jornada_id_171, '2025-09-10', 'MADRID', 'CARLOS', 36, 'ASESOR HIPOTECARIO', '@carloszm455', 662, 490, 'X3 SG', 1800, '11:23 - 12:07. Xuso llamando a la puerta del ratoncito Pérez, pero no sale y decide preguntar a la gente que le pedirían. Habla con varios guiris que no 
conocen al ratoncito y aparece Carlos con su chica, que le dice que le pediría cosas para su colmena y Xuso le invita a concursar. Explicamos mecánica. 
Arrancamos con la primera y busca a alguien con ese color en su ropa, aunque  a él le gusta más el rojiblanco del Atleti. Hay varios que le dicen que no y 
al final elige a un señor llamado Enrique que acierta. Nos cuenta que lo de la miel le viene de su abuelo que tenía colmenas en el pueblo y él las ha 
restaurado y le encanta esa mezcla de ciudad y pueblo, ya que su profesión es asesor financiero. Vamos a la segunda y no tiene ni idea, como Eva, que 
tampoco y le hace ganar los 400. Nos cuenta que él no tiene hijos, que lleva cinco años con su chica y están muy enamorados. La pregunta tres se la 
formulamos debajo de una bandera de España, pero él no se da cuenta, creo que Rober tiene el plano. Busca a un hombre de unos cincuenta y lo 
encuentra en Paolo, que no recuerda el Plus Ultra y nos hace ir a los XUSÓQUER. Le sale un CONTINÚE, y nos cuenta que el dinero sería para las 
colmenas. En la tercera para a un chico jovem que no duda y le hace quedarse con 600, pero Carlos se arriesga. Abrimos sobres, pero le sale el alto el 
primero, así que abrimos el elegido en segundo lugar y le sale un x3.Busca a un extranjero, porque cree que no sabrán este dato. Para a uno que luego 
huye sin firmar (cortar) y luego a Doris, que es Venezuela y no lo sabe porque está de turismo. Carlos gana los 1800.', 'Adriana', '2+', 'Arranque puerta Ratoncito Pérez.');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados, duracion, valoracion_final) VALUES (632, @jornada_id_171, '2025-09-10', 'MADRID', 'SERGIO', 34, 'NO TIENE', '@sergi2791.', 664, 600, '12:08 - 13:03. Xuso, con el micro de reportero, decide hacer una broma y decir que está de moda adoptar cucarachas como mascota. Para a varias personas pero nadie tiene gracia. De repente un chico desde la otra acera llama su atención y cruza corriendo y llega a su altura para decirle que quiere concursar. Xuso le hace concursante por su efusividad. Arrancamos y la primera pregunta le parece dificilísima, pero para a Vicente que acierta. Nos cuenta que trabaja mucho de mozo de almacén. Es bastante seco. Vamos a la segunda y elige a un latino que le da una lección de historia tremenda, contando la historia de los apaches. Aunque duda en su respuesta porque se lía y tenemos que leerle varias veces la pregunta, pero finalmente acierta. Nos vamos a XUSÓQUER y le sale RECICLA. Encuentra a una muchacha que no lo sabe. Ojo, la captación se repite porque la acompañante es menor. Sergio nos habla de su chica, y de sus planes de comprar un piso. Vamos a la tercera, y lo sabe, elige a un chico que nos está haciendo una foto y éste falla. A Sergio le sienta fatal. Nos saltamos la tercera pregunta, aunque caminamos para alejarnos de una obra de la calle y formulamos la cuarta, en la que para a una señora estupenda que no sabe la respuesta. Sergio se planta con 600.', 'Adriana', '1-', 'Acción de EN BOCA DE XUSO: ¿Qué le parece la moda de adoptar cucarachas como mascota?', '18:18', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados) VALUES (633, @jornada_id_171, '2025-09-10', 'MADRID', 'JOSÉ', 64, 'JUBILADO', 'NO TIENE', 642, 0, 'CUESTIONARIO MUSICAL ♫
 13:08 - 14:00. Xuso en la plaza Raffaella Carrá de Madrid quiere hacer homenaje a la italiana y saca a Lola para que haga el movimiento de cabeza. Lola 
lo borda y empieza a buscar alguien que lo haga. Un señor le llama y le dice que es de Murcia, y contra todo pronóstico le hace el movieminto de cabeza 
estupendamente, así que Xuso le invita a concursar. El señor va con su pareja, pero éste no quiere salir. Arrancamos y en la primera coge a Eugenia que 
no se acuerda de "Como una ola". Sacamos XUSÓQUER, sale el AL VERRÉS, y la chica a la que para, Sheila, que va a una entrevista de trabajo, acierta. Nos 
cuenta que lleva 42 años con su pareja y que ya no vive en Murcia, aunque va mucho porque su madre tiene alzhéimer. En la segunda nos cuenta que es 
eurofan desde pequeño, y que recuerda ver ganar a Massiel. Para a un señor mayor que acierta a boleo. José nos cuenta que ha sido cocinero y hace 
buenos arroces murcianos. Vamos a la tercera y José no tiene ni idea. Para a un chico muy joven que responde "Britney Spears". José nos dice que 
necesita el dinero para reformar su casa. En la cuarta pregunta elige a una chica joven, que también acierta, así que José se va a 0€ con un abrazo de 
todo el equipo.', 'Adriana', '1+', 'Cuestionario musical. 
PLENO DE "NO SUPERADAS".');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, ocupacion, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista) VALUES (634, @jornada_id_171, '2025-09-10', 'MADRID', 'ANDREA
ESTHER', 'MAESTRA;
ADMINISTRATIVA', 670, 497, 'X4 SG', 4000, '16:16 - 17:10. Xuso quiere que la gente aproveche para mandar mensajes a sus familias y para a varias personas muy majas que mandan mensajes 
bonitos. Aparecen Esther y Andrea, y son muy tiernas mandándose mensajes entre ellas. Xuso las convierte en concursantes y arrancamos con la 
primera, en la que paran a una joven de 18 años llamada Sofía que acierta. Andrea nos cuenta que es maestra y su madre relata que desde pequeña 
ponía a los muñecos en fila para darles clase. Esther habla de que trabaja en una clínica dental. Xuso les pregunta por un tatuaje que tienen y cuentan 
que lo tienen juntas y es la palabra "siempre"porque con esa palabra ellas se dicen"te quiero"En la segunda paran a una señora argentina que responde 
"la piel" y Xuso aclara que está preguntando por la longitud y que por lo tanto es incorrecta la respuesta. Nos hablan del padre de Andrea y Esther le 
manda un mensaje de amor precioso.  Vamos a la tercera y ellas lo saben bien, pero el chico al que paran no, así que sacamos XUSÓQUER y les sale AL 
VERRÉS. Paran a Xavi, un australiano que habla perfecto español, pero que responde Galicia argumentando bien que ha pensado en las comunidades con 
más quesos. Xavi manda un mensaje a su familia australiana, pero se lía bastante. Madre e hija nos cuentan que el dinero lo invertirían en un crucero con 
las abuelas que se lo merecen mucho. En la cuarta paran a un obrero de la construcción que no sabe la respuesta. Lo celebran y deciden arriesgarse. Les 
sale un x4 y paran a un señor que desde el principio dice que no va a acertar y les hace ganar los 4000€', 'Adriana', '3');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados) VALUES (635, @jornada_id_172, '2025-09-09', 'CUENCA', 'JOSEDU', 40, 'BOMBERO FORESTAL', '@josedu_ar', 680, 447, 'X3 SP', 0, 'REC 11:21 - 11:56 // COMENZAMOS COMENTANDO EL TATUAJE DE FELIPE. XUSO LE PREGUNTA CÓMO HAN REACCIONADO EN CASA Y SI AHORA ESTÁ 
LIGANDO MÁS. FELIPE NOS CONFIESA QUE ESTÁ ENAMORADO DE UNA CHICA QUE SE LLAMA NATALIA, ASÍ QUE APROVECHA PARA ENVIARLE UN 
MENSAJE A SUS SUEGROS, QUE SON SEGUIDORES DEL PROGRAMA. COMO SE HA TATUADO EL LOGO DEL PROGRAMA, XUSO LE DICE QUE TENDRÁ EL 
PRIVILEGIO DE ELEGIR AL SIGUIENTE CONCURSANTE Y FELIPE SE PROPONE ENCONTRAR A ALGUIEN DE SU ESTILO. SE FIJA EN JOSÉ EDUARDO, LO 
CAPTAMOS Y MICROFONAMOS. EN LA PRIMERA PREGUNTA, LA ELEGIDA ES UNA CHICA RUMANA QUE FALLA LA PREGUNTA, SACAMOS LOS XUSÓKER Y 
SALE EL CONTINÚE. JOSÉ EDUARDO NOS CUENTA QUE ES BOMBERO FORESTAL Y XUSO LE PREGUNTA CÓMO HA VIVIDO ESTE VERANO PORQUE HA SIDO 
EL PEOR AÑO DE INCENDIOS DE LAS ÚLTIMAS DÉCADAS. NOS CUENTA QUE EN CUENCA TAMBIÉN HUBO INCENDIOS, PERO NO TAN GRAVES COMO EN 
OTRAS ZONAS Y APROVECHA PARA REIVINDICAR MEJORES CONDICIONES PARA EL CUERPO DE BOMBEROS Y MAYOR PREVENCIÓN EN EL TERRENO. 
SUPERA LA SEGUNDA Y LA TERCERA PREGUNTA. PARA CELEBRARLO, NOS CANTA UNA BREVE CANCIÓN SOBRE PALESTINA DE SU GRUPO DE PUNK 
"EXPOLIKES" Y EXPLICA QUE INVERTIRÍA EL PREMIO EN SU BANDA. SUPERA LA CUARTA PREGUNTA Y DECIDE JUGAR. EN LA QUINTA PREGUNTA, LA 
PERSONA ELEGIDA SABÍA LA RESPUESTA ASÍ QUE SE MARCHA CON LA CAMISETA DEL PROGRAMA.', 'Cristina', '1+', 'Este concursante hay que ponerlo después del #623#, que es cuando Felipe entra a hacerse el tatuaje que muestra en este inicio.');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados) VALUES (636, @jornada_id_172, '2025-09-09', 'CUENCA', 'JORGE DAVID', 38, 'AUXILIAR DE ENFERMERÍA', '@curiosidosis', 626, 500, 'X7 SP', 0, 'REC 12:38 - 13:01 // ARRANCAMOS CON XUSO SALIENDO DE LA CONFITERÍA RUIZ CON UN ALAJÚ EN LA MANO. NOS EXPLICA LA HISTORIA DE ESTE 
DULCE TÍPICO DE CUENCA Y LO REPARTE ENTRE LOS MIEMBROS DEL EQUIPO. COMIENZA A ANDAR Y SE FIJA EN UN CHICO QUE ACOMPAÑABA AL 
ELEGIDO DE LA QUINTA PREGUNTA DEL CONCURSANTE #635 (JORGE APARECE BREVEMENTE Y NO TIENE NINGUNA INTERVENCIÓN. SIMPLEMENTE 
ESTABA ANDANDO JUNTO AL ELEGIDO). JORGE ESTÁ DANDO UN PASEO CON SUS PADRES, Y SU MADRE NOS CUENTA QUE ACABA DE SER PADRE, ASÍ 
QUE LO CAPTAMOS Y MICROFONAMOS. EXPLICAMOS LA MECÁNICA Y SUPERA LA PRIMERA PREGUNTA. NOS EXPLICA QUE TRABAJA COMO AUXILIAR DE 
ENFERMERÍA Y QUE TIENE UN BEBÉ DE 50 DÍAS. EN LA SEGUNDA PREGUNTA, ELIGE A UNA MUJER QUE NO SE QUIERE PARAR Y JUSTO NOS INTERRUMPE 
OTRA SEÑORA MAYOR QUE QUIERE UNA FOTO, ASÍ QUE JORGE ELIGE A ESTA SEGUNDA SEÑORA. XUSO, JORGE Y ELLA SE HACEN UNA FOTO (PEDIR A 
PRODUCCIÓN) Y JORGE SUPERA LA SEGUNDA PREGUNTA. TRAS SUPERAR LA TERCERA PREGUNTA, NOS CUENTA QUE CON EL DINERO PAGARÍA EL 
BAUTIZO DE LA HIJA. SI TIENE BUEN CORTE, LEVANTAR CUANDO XUSO PREGUNTA CUÁNTO CUESTA UN BAUTIZO. NO ES RELEVANTE. SUPERA LA CUARTA 
PREGUNTA Y DECIDE JUGAR. LA QUINTA ELEGIDA NO SUPRA LA PREGUNTA Y JORGE SE MARCHA CON LA CAMISETA. (DURANTE LA DESPEDIDA DE LA 
ELEGIDA, PASA UN CURA POR DETRÁS Y SEGURAMENTE HUBIESE SABIDO LA RESPUESTA. A VER SI PODEMOS ENCONTRAR ESE MOMENTO EN LA 
CÁMARA DE NACHO).', 'Cristina', '2-', 'Arranque Xuso probando "alajú". 
El concursante es el acompañante del quinto elegido del concursante #635#');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados) VALUES (637, @jornada_id_172, '2025-09-09', 'CUENCA', 'ISABEL', 38, 'HOSTELERA', '@isahuete', 658, 484, 'X3 SG', 1800, 'CUESTIONARIO MUSICAL ♫
 REC 13:37 - 14:19 // ARRANCAMOS CON XUSO HABLANDO SOBRE LA GASTRONOMÍA MANCHEGA MIENTRAS EL RESTO DEL EQUIPO LE ESPERA SENTADO 
EN UNA MESA DEL MESÓN EL BODEGÓN. (PREVIAMENTE, GRABAMOS INSERTOS DE CHETE LLAMANDO A XUSO CON LA MANO). XUSO LLEGA, SE SIENTA 
EN LA MESA Y COMENTAN QUE VAN A PROBAR "EL MORTERO". LLEGA EL CAMARERO, LES SIRVE EL MORTERUELO Y LES EXPLICA EN QUÉ CONSISTE ESTE 
PLATO. LO PRUEBAN Y XUSO LE DICE AL CAMARERO SI QUIERE VENIR A CONCURSAR, PERO NOS DICE QUE NO PUEDE Y QUE MEJOR SU HERMANA. 
CONOCEMOS A ISABEL, LA CAPTAMOS Y MICROFONAMOS. (GRABAMOS RECURSOS DEL EQUIPO PROBANDO EL MORTERUELO). NO SUPERA LA PRIMERA 
PREGUNTA, SACAMOS LOS XUSÓKER Y NOS VAMOS A LA LLAMADA DE EMERGENCIA. ISABEL DECIDE LLAMAR A SU PAREJA, PERO NOS DA LA 
RESPUESTA FUERA DE TIEMPO. NOS CUENTA QUE SE CONOCIERON EN EL FESTIVAL DE LOS MONEGROS. SE VIERON UN AÑO, PERO NO SE 
INTERCAMBIARON LOS TELÉFONOS Y SE VOLVIERON A ENCONTRAR EN EL MISMO SITIO UN AÑO DESPUÉS ENTRE MÁS DE 60.000 PERSONAS. DESDE 
ENTONCES LLEVAN CASI VEINTE AÑOS JUNTOS. SUPERA LA SEGUNDA Y LA TERCERA PREGUNTA. CON EL DINERO LE GUSTARÍA AYUDAR A SUS PADRES 
CON EL NEGOCIO FAMILIAR PARA PODER VIVIR TRANQUILA. NOS CONFIESA QUE HA ESTADO DOS AÑOS "EN CAMA" POR UNA DEPRESIÓN FRUTO DE LAS 
PREOCUPACIONES ECONÓMICAS Y APROVECHA PARA REIVINDICAR UNA MEJOR SANIDAD PÚBLICA SIN ESPERAS TAN LARGAS. SUPERA LA CUARTA 
PREGUNTA Y DECIDE JUGAR. LA QUINTA ELEGIDA NO SABÍA QUIÉN ERA FANGORIA E ISABEL SE LLEVA 1.800 EUROS.', 'Cristina', '1+', 'Acting cata de morteruelo. 
Cuestionario musical.');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados) VALUES (638, @jornada_id_172, '2025-09-09', 'CUENCA', 'JESSICA', 38, 'MAESTRA', 'NO TIENE', 665, 494, 'X3 SG', 3000, 'REC 16:08 - 16:49
 *ESTA CONCURSANTE COMIENZA CON LA ENTRADILLA SOBRE EL PUENTE DE SAN PABLO CON LAS CASAS COLGADAS DE FONDO, PERO HEMOS GRABADO 
PRIMERO LA CONCURSANTE Y DESPUÉS LA ENTRADILLA). 
COMENZAMOS POR TRANSI EN LA CALLE CARRETERÍA. XUSO SALUDA A UN PAR DE PERSONAS; PASA POR DELANTE DE UNA HELADERÍA, PRUEBA UN 
YOGUER HELADO Y FINALMENTE SE FIJA EN JESSICA Y EN SU PADRE QUE ESTÁN SENTADOS EN UNA TERRAZA. CAPTAMOS A JESSICA Y MICROFONAMOS. 
NO SUPERA LA PRIMERA PREGUNTA, SACAMOS LOS XUSÓKER Y SALE EL CONTINÚE. JESSICA CUENTA QUE ES PROFESORA DE INGLÉS EN UN COLEGIO 
RURAL Y QUE SOLO TIENE OCHO ALUMNOS DE DIFERENTES EDADES. NOS CUENTA QUE TARDA MUCHO EN LLEGAR A TRABAJAR PORQUE EL COLEGIO 
ESTÁ A 115 KILÓMETROS DE SU CASA. (SI TIENE BUEN CORTE, LEVANTARÍA TODA LA PARTE SOBRE LAS CARRETERAS Y RETOMARÍA EN LA PREGUNTA 
"¿QUÉ DIFERENCIAS HAY ENTRE UN COLEGIO DE UNA CIUDAD Y UN COLEGIO RURAL?"). SUPERA LA SEGUNDA Y LA TERCERA PREGUNTA Y NOS CUENTA 
QUE CON EL DINERO SE COMPRARÍA UN COCHE. (SI TIENE BUEN CORTE, LEVANTAR LOS COMENTARIOS SOBRE LOS COCHES HÍBRIDOS/ELÉCTRICOS, NO 
ES RELEVANTE). SUPERA LA CUARTA PREGUNTA Y DECIDE JUGAR. ABRIMOS SOBRES MULTIPLICADORES Y COMO EL PRIMER SOBRE CONTIENE LA CIFRA 
MÁS ELEVADA, NO ABRIMOS LOS OTROS. SUPERA LA QUINTA PREGUNTA Y SE MARCHA MUY EMOCIONADA CON 3.000 EUROS.  // GRABAMOS 
ENTRADILLA SOBRE EL PUENTE DE SAN PABLO Y NOS VAMOS POR TRANSICIÓN.', 'Cristina', '2-', 'Arranque Xuso en el Puente de San Pablo con casas colgadas al fondo.');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, factor_x, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados) VALUES (639, @jornada_id_173, '2025-09-10', 'CUENCA', 'FERNANDO', 36, 'TÉCNICO DE EMERGENCIAS SANITARIAS', '@f.diazmartinez', 675, 422, 'X3 SP
X24 N', 0, 'REC 9:57 - 10:34 // ARRANCAMOS JUNTO AL MONUMENTO AL NAZARENO DE CUENCA Y XUSO NOS CUENTA QUE LA SEMANA SANTA DE CUENCA ESTÁ 
DECLARADA FIESTA DE INTERÉS TURÍSTICO INTERNACIONAL. SEGUIDAMENTE, BROMEA CON FELIPE PORQUE LA ESCULTURA RECUERDA A FELIPE 
PORTANDO LA NUTRIA Y HACEMOS TRANSICIÓN A LA CALLE CARRETERÍA PORQUE EL MONUMENTO ESTÁ RODEADO POR DOS CARRETERAS. UNA VEZ EN 
LA CALLE, LE PREGUNTA A UN PAR DE PERSONAS POR QUÉ ES TAN ESPECIAL LA SEMANA SANTA EN CUENCA. (LEVANTAR AL PRIMER HOMBRE PORQUE 
ES DE TOLEDO). NOS ENCONTRAMOS CON FRAN Y NOS CUENTA QUE EMPEZÓ A ANDAR JUSTO CUANDO PASABA UNA PROCESIÓN POR DELANTE, ASÍ 
QUE LO CAPTAMOS Y MICROFONAMOS. NO SUPERA LA PRIMERA PREGUNTA, SACAMOS LOS XUSÓKER Y SALE UN CONTINÚE. NOS CUENTA QUE ES 
TÉCNICO DE EMERGENCIAS SANITARIAS Y QUE EN SU CENTRO DE SALUD EN MIRA (CUENCA) TAMBIÉN SE VIERON AFECTADOS POR LA DANA Y QUE 
TUVIERON QUE SALTAR POR LA VENTANA CUANDO EMPEZÓ A SUBIR EL AGUA. (LEVANTAR CUANDO XUSO PREGUNTA SI ALLÍ AFECTÓ TANTO COMO EN 
VALENCIA Y CUANDO FERNANDO DICE QUE "SOLO MURIÓ UNA PERSONA". RETOMAMOS EN LA PREGUNTA SOBRE SI EL CENTRO DE SALUD YA ESTÁ 
FUNCIONANDO CON NORMALIDAD). SUPERA LA SEGUNDA Y LA TERCERA PREGUNTA Y NOS CUENTA QUE CON EL DINERO LE GUSTARÍA AYUDAR A SU 
MADRE Y CUMPLIR EL SUEÑO DE SU PADRE, YA FALLECIDO, DE TENER UNA CASITA CON HUERTO. NO SUPERA LA CUARTA PREGUNTA Y DECIDE JUGAR. 
ABRIMOS SOBRES MULTIPLICADORES Y DESVELAMOS EL X24, PERO FERNANDO JUEGA X3. NO SUPERA LA QUINTA PREGUNTA Y SE MARCHA CON LA 
CAMISETA. GRABAMOS DOS SALIDAS: UNA EN LA QUE SE VAN DE PLANO Y OTRA EN LA QUE SE MARCHAN HABLANDO.', 'Cristina', '1+', 'Arranque en monumento al nazareno.');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista) VALUES (640, @jornada_id_173, '2025-09-10', 'CUENCA', 'ALBERTO', 45, 'CONDUCTOR Y AGRICULTOR', 'NO TIENE', 654, 1000, 'REC 10:55 - 11:27 // ARRANCAMOS EN LA CALLE CARRETERÍA Y XUSO SE PROPONE ENCONTRAR A UN BUEN MANCHEGO O MANCHEGA, Y 
APROVECHANDO QUE TENEMOS A UNA EN EL EQUIPO, XUSO LE PREGUNTA A ROSA CÓMO SON LOS MANCHEGOS (SIMPÁTICOS, HUMILDES, 
CAMPECHANOS, ETC.). (GRAFISMO: COMO SUGERENCIA, PODRÍAMOS ANOTAR LOS ADJETIVOS EN LA SILUETA DE LA PROVINCIA E IR SUMANDO LOS 
SIGUIENTES ADJETIVOS). ECHAMOS A ANDAR Y XUSO HABLA CON OTRO SEÑOR QUE DICE QUE LOS MANCHEGOS TAMBIÉN SON GENEROSOS. SEGUIMOS 
ANDANDO Y NOS ENCONTRAMOS CON ALBERTO, QUE NOS ENGANCHA POR SU ACENTO Y LO CAPTAMOS. EXPLICAMOS MECÁNICA Y ALBERTO SUPERA 
LA PRIMERA PREGUNTA. NOS CUENTA QUE ES AGRICULTOR Y QUE CULTIVA CEBADA, LENTEJAS, TRIGO, Y QUE TAMBIÉN TIENE GALLINAS. (SI TIENE BUEN 
CORTE, LEVANTAR LA PREGUNTA DE XUSO SOBRE SI TIENE MÁS ANIMALES Y RETOMAR EN LA PREGUNTA "¿CÓMO ES UN BUEN ALMUERZO 
MANCHEGO?"). SUPERA LA SEGUNDA PREGUNTA Y XUSO LE PREGUNTA QUÉ TAL VA DE AMORES. NOS CUENTA QUE ESTÁ SOLTERO Y QUE NO QUIERE 
LÍOS, SOLO AMIGAS CON DERECHO A ROCE. (GRAFISMO: XUSO LE PIDE A LOS GRAFISTAS QUE LE PONGAN UN FONDO TIPO "GRANJERO BUSCA ESPOSA" 
Y LE PREGUNTA A ALBERTO CÓMO LE GUSTARÍA QUE FUESE SU PAREJA). NO SUPERA LA TERCERA PREGUNTA, SACAMOS LOS XUSÓKER Y SALE EL 
CONTINÚE.  NOS CUENTA QUE CON EL DINERO LE GUSTARÍA COMPRARSE UN TRACTOR PORQUE PUEDEN LLEGAR A COSTAR 150.000 EUROS. SUPERA LA 
CUARTA PREGUNTA Y DECIDE PLANTARSE.', 'Cristina', '2');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, combo_id, resultado, notas_grabacion, guionista, valoracion_guionista, momentos_destacados) VALUES (641, @jornada_id_173, '2025-09-10', 'CUENCA', 'LUCÍA', 25, 'ESTUDIANTE', '@lucia_rv24', 671, 491, 0, 'CUESTIONARIO MUSICAL ♫ // REC 11:58 - 12:45
 ARRANCAMOS EN EL PARQUE SAN JULIÁN CON XUSO PREGUNTANDO A LA GENTE QUÉ OTROS LUGARES NOS RECOMIENDAN DE LA PROVINCIA DE 
CUENCA. SI TIENE BUEN CORTE, LEVANTARÍA AL HOMBRE QUE ESTÁ SENTADO EN EL BANCO, QUE DICE QUE HA HABLADO CONMIGO Y QUE "CUENCA LA 
HIZO DIOS"). XUSO HABLA CON UN PAR DE SEÑORAS Y SE ENCUENTRA CON LUCÍA, UNA CHICA MUY PIZPIRETA QUE LE RECOMIENDA LA SEMANA SANTA 
Y EL NACIMIENTO DEL RÍO CUERVO. LA CAPTAMOS Y MICROFONAMOS. NO SUPERA LA PRIMERA PREGUNTA, SACAMOS LOS XUSÓKER Y SALE EL AL 
VERRÉS. CORTAR CUANDO XUSO DICE "LENGUAJE DE SIGNOS" Y RETOMAR EN EL SALUDO A BEATRIZ ROMERO. SUPERA LA PRIMERA PREGUNTA Y NOS 
CUENTA QUE ACABA DE ACABAR LA CARRERA Y QUE ESTÁ EN UN MOMENTO DE IMPASSE PORQUE NO SABE QUÉ HACER CON SU VIDA (ESTUDIAR UN 
MÁSTER, OPOSITAR, TRABAJAR, ETC.). SUPERA LA SEGUNDA PREGUNTA Y FALLA LA TERCERA. NOS CUENTA QUE CON EL DINERO LE GUSTARÍA 
REGALARLE UN VIAJE A VIENA A SUS PADRES PORQUE ESE FUE EL DESTINO DE SU LUNA DE MIEL HACE 25 AÑOS. SUPERA LA CUARTA PREGUNTA Y 
DECIDE JUGAR. EN LA QUINTA PREGUNTA, ELIGE A UNA CHICA JOVEN QUE NO SABE LA RESPUESTA Y LUCÍA SE MARCHA CON LA CAMISETA.', 'Cristina', '1+', 'Cuestionario musical.');
INSERT INTO concursantes (numero_concursante, jornada_id, dia_grabacion, lugar, nombre, edad, ocupacion, redes_sociales, cuestionario_id, resultado, notas_grabacion, guionista, valoracion_guionista) VALUES (642, @jornada_id_173, '2025-09-10', 'CUENCA', 'ADRIÁN', 20, 'ESTUDIANTE Y MAGO', '@magicoman1', 676, 1000, 'REC 13:13 - 13:52
 *CUESTIONARIO ARRASTRADO DE LA JORNADA 172_CUENCA*
 ARRANCAMOS EN LA CALLE SAN FRANCISCO Y XUSO APROVECHA QUE HEMOS VENIDO A CUENCA PARA SALUDAR A ÁNGEL, UN CONCURSANTE QUE SE 
LLEVÓ 5.000 EUROS EN LA ÚLTIMA VISITA A CUENCA (DEJAMOS ESPACIO PARA FLASBACK). SALUDAMOS A ÁNGEL, NOS CUENTA QUÉ TAL LE HA IDO EN 
ESTE TIEMPO Y NOS HACE UNA DEMOSTRACIÓN DE SU FAMOSO "BANZAI". SEGUIMOS ANDANDO Y XUSO VE A UN CHICO QUE VA MEDIO VESTIDO DE 
CABALLERO MEDIEVAL. ÁNGEL SE ACERCA A ÉL Y LO SORPRENDE CON EL GRITO DE "BANZAI". ADRIÁN SE LLEVA UN SUSTO DE MUERTE Y XUSO SE PARTE 
DE LA RISA. NOS CUENTA QUE VA VESTIDO ASÍ PORQUE SON LAS FIESTAS DE SAN MATEO Y ESTÁ DE ENSAYOS CON SU PEÑA. NOS FIJAMOS EN QUE 
LLEVA UNA ESPADA DE MENTIRA Y NOS HACE UNA PEQUEÑA DEMOSTRACIÓN CON LA ESPADA, PERO CASI DECAPITA A LA NUTRIA. CAPTAMOS A 
ADRIÁN, SE DESPIDE DE SU NOVIA Y COMENZAMOS EL CONCURSO. SUPERA LA PRIMERA PREGUNTA Y NOS CUENTA QUE ESTÁ ESTUDIANDO 
MAGISTERIO Y QUE ES MAGO, ASÍ QUE NOS HACE UN TRUCO DE MAGIA. SUPERA LA SEGUNDA Y LA TERCERA PREGUNTA. REPETIMOS LA PREGUNTA DEL 
DINERO PORQUE HABÍA NIÑOS DETRÁS Y NOS CUENTA QUE INVERTIRÍA EL PREMIO EN LA MAGIA. FALLA LA CUARTA PREGUNTA, SACAMOS LOS 
XUSÓKER Y SALE EL RECICLA. REPETIMOS LA PREGUNTA, LA SUPERA Y SE PLANTA CON 1.000 EUROS.', 'Cristina', '2+');

-- Búsqueda de cuestionarios en la base de datos

-- ========================================
-- JORNADA: Jornada 88 (Var: @jornada_id_88)
-- ========================================

-- Buscar cuestionario que contenga alguna de las preguntas del cuestionario 310
SET @cuestionario_id = (
    SELECT DISTINCT c.id
    FROM cuestionarios c
    INNER JOIN cuestionarios_preguntas cp ON c.id = cp.cuestionario_id
    INNER JOIN preguntas p ON cp.pregunta_id = p.id
    WHERE (
        p.pregunta = '¿Qué pescado es la estrella de la gastronomía portuguesa?' COLLATE utf8mb4_unicode_ci
        OR p.pregunta = '¿De qué tres colores son las franjas de la bandera de Paraguay? #PreguntaMolona de @arzamendia61928 por Instagram.' COLLATE utf8mb4_unicode_ci
        OR p.pregunta = 'En el contexto de la aviación, ¿qué significan las siglas TCP?' COLLATE utf8mb4_unicode_ci
        OR p.pregunta = 'En el parchís, ¿cuántas casillas puedes avanzar en un solo turno si consigues comerle la ficha a un rival?' COLLATE utf8mb4_unicode_ci
    )
    LIMIT 1
);

-- Mostrar resultado de la búsqueda
SELECT IF(@cuestionario_id IS NULL, 
    CONCAT('ERROR: No se encontró el cuestionario 310'), 
    CONCAT('Cuestionario encontrado con ID: ', @cuestionario_id)) AS mensaje;

-- Insertar relación jornada-cuestionario (evitar duplicados)
INSERT INTO jornadas_cuestionarios (jornada_id, cuestionario_id) 
SELECT @jornada_id_88, @cuestionario_id
WHERE @cuestionario_id IS NOT NULL
AND NOT EXISTS (
  SELECT 1 FROM jornadas_cuestionarios jc
  WHERE jc.jornada_id = @jornada_id_88 AND jc.cuestionario_id = @cuestionario_id
);

-- Actualizar estado del cuestionario a adjudicado
UPDATE cuestionarios SET estado = 'adjudicado' WHERE id = @cuestionario_id;

