        OR p.pregunta = 'Entre los casi doscientos países reconocidos por la ONU, ¿cuál es el único que empieza por la letra “O”?' COLLATE utf8mb4_unicode_ci
        OR p.pregunta = '¿Qué actor fue Terminator y Conan el Bárbaro en el cine y gobernador de California en la vida real?' COLLATE utf8mb4_unicode_ci
        OR p.pregunta = '¿Cómo se llama la hermana de Hansel en el famoso cuento infantil de origen alemán?' COLLATE utf8mb4_unicode_ci
    )
