    FROM cuestionarios c
    INNER JOIN cuestionarios_preguntas cp ON c.id = cp.cuestionario_id
    INNER JOIN preguntas p ON cp.pregunta_id = p.id
    WHERE (
        p.pregunta = 'En los noventa, la artista Rebeca cantaba "Tú siempre fuiste duro de…" ¿De qué?' COLLATE utf8mb4_unicode_ci
        OR p.pregunta = '¿Quién es la artista que ostenta el récord Guinness como la solista femenina con mayores ventas de todos los tiempos?' COLLATE utf8mb4_unicode_ci
        OR p.pregunta = '¿Cuál es el nombre de pila del cantante C. Tangana?' COLLATE utf8mb4_unicode_ci
        OR p.pregunta = '¿Qué instumento de percusión característico del flamenco introdujo Paco de Lucía en España tras un viaje a Perú?' COLLATE utf8mb4_unicode_ci
    )
    LIMIT 1
);

