-- Buscar cuestionario que contenga alguna de las preguntas del cuestionario 184
SET @cuestionario_id = (
    SELECT DISTINCT c.id
    FROM cuestionarios c
    INNER JOIN cuestionarios_preguntas cp ON c.id = cp.cuestionario_id
    INNER JOIN preguntas p ON cp.pregunta_id = p.id
    WHERE (
        p.pregunta = '¿Cómo se llama la única hembra fértil de una colmena de abejas?' COLLATE utf8mb4_unicode_ci
        OR p.pregunta = '¿En qué año entró en vigor definitivamente el "Brexit"?' COLLATE utf8mb4_unicode_ci
        OR p.pregunta = '¿Qué palabra define la RAE como una imagen, por lo general distorsionada con fines cómicos, que se difunde a través de internet?' COLLATE utf8mb4_unicode_ci
        OR p.pregunta = 'En la mítica escena de "Braveheart", el protagonista exclama: "Puede que nos quiten la vida, pero jamás nos quitarán…" ¿El qué?' COLLATE utf8mb4_unicode_ci
    )
    LIMIT 1
);

-- Mostrar resultado de la búsqueda
SELECT IF(@cuestionario_id IS NULL, 
    CONCAT('ERROR: No se encontró el cuestionario 184'), 
    CONCAT('Cuestionario encontrado con ID: ', @cuestionario_id)) AS mensaje;

-- Insertar relación jornada-cuestionario (evitar duplicados)
INSERT INTO jornadas_cuestionarios (jornada_id, cuestionario_id) 
SELECT @jornada_id_55, @cuestionario_id
WHERE @cuestionario_id IS NOT NULL
AND NOT EXISTS (
  SELECT 1 FROM jornadas_cuestionarios jc
  WHERE jc.jornada_id = @jornada_id_55 AND jc.cuestionario_id = @cuestionario_id
);

