-- ========================================
-- VERIFICACIONES POST-IMPORTACIÓN
-- ========================================

-- Verificar que las jornadas se importaron correctamente
SELECT COUNT(*) as total_jornadas FROM jornadas;

-- Verificar relaciones jornada-cuestionario
SELECT j.nombre, COUNT(jc.cuestionario_id) as total_cuestionarios
FROM jornadas j
LEFT JOIN jornadas_cuestionarios jc ON j.id = jc.jornada_id
GROUP BY j.id, j.nombre;

-- Verificar relaciones jornada-combo
SELECT j.nombre, COUNT(jco.combo_id) as total_combos
FROM jornadas j
LEFT JOIN jornadas_combos jco ON j.id = jco.jornada_id
GROUP BY j.id, j.nombre;

-- Verificar concursantes importados
SELECT COUNT(*) as total_concursantes FROM concursantes;

-- Verificar concursantes por jornada
SELECT j.nombre, COUNT(c.id) as total_concursantes
FROM jornadas j
LEFT JOIN concursantes c ON j.id = c.jornada_id
GROUP BY j.id, j.nombre;

-- Verificar programas importados
SELECT COUNT(*) as total_programas FROM programas;

-- Verificar concursantes por programa
SELECT p.id as programa_id, COUNT(c.id) as total_concursantes
FROM programas p
LEFT JOIN concursantes c ON p.id = c.numero_programa
GROUP BY p.id
ORDER BY p.id;

-- Mostrar detalles de las jornadas
SELECT j.id, j.nombre, j.fecha_jornada, j.lugar, j.estado,
       GROUP_CONCAT(DISTINCT jc.cuestionario_id) as cuestionarios,
       GROUP_CONCAT(DISTINCT jco.combo_id) as combos
FROM jornadas j
LEFT JOIN jornadas_cuestionarios jc ON j.id = jc.jornada_id
LEFT JOIN jornadas_combos jco ON j.id = jco.jornada_id
GROUP BY j.id, j.nombre, j.fecha_jornada, j.lugar, j.estado;

USE lsnls;
-- 1) Ampliar temporalmente el ENUM para permitir antiguos y nuevos
ALTER TABLE jornadas
  MODIFY estado ENUM('preparacion','lista','en_grabacion','completada','archivada',
                     'borrador','completa','grabada') NOT NULL;

-- 2) Mapear valores antiguos → nuevos
UPDATE jornadas SET estado = 'borrador'  WHERE estado = 'preparacion';
UPDATE jornadas SET estado = 'completa'  WHERE estado IN ('lista','completada');
UPDATE jornadas SET estado = 'grabada'   WHERE estado IN ('en_grabacion','archivada');

-- 3) Estrechar el ENUM a solo los nuevos + default
ALTER TABLE jornadas
  MODIFY estado ENUM('borrador','completa','grabada') NOT NULL DEFAULT 'borrador';

USE lsnls;
-- Poner 'borrador' a jornadas sin estado o con estado inválido
UPDATE jornadas
SET estado = 'borrador'
WHERE estado IS NULL
   OR estado = ''
   OR estado NOT IN ('borrador','completa','grabada');

-- 4) Verificar
SELECT estado, COUNT(*) FROM jornadas GROUP BY estado;


-- 1) Marcar como usadas las que estén en cuestionarios o combos
UPDATE preguntas p
JOIN (
  SELECT pregunta_id FROM cuestionarios_preguntas
  UNION
  SELECT pregunta_id FROM combos_preguntas
) r ON r.pregunta_id = p.id
SET p.estado_disponibilidad = 'usada';
-- 2) Las que estaban usadas pero ya no están en ninguna relación -> liberada
UPDATE preguntas p
LEFT JOIN (
  SELECT pregunta_id FROM cuestionarios_preguntas
  UNION
  SELECT pregunta_id FROM combos_preguntas
) r ON r.pregunta_id = p.id
SET p.estado_disponibilidad = 'liberada'
WHERE r.pregunta_id IS NULL
  AND p.estado = 'usada';
  -- 3) El resto (no usadas y sin relación) -> disponible
UPDATE preguntas p
LEFT JOIN (
  SELECT pregunta_id FROM cuestionarios_preguntas
  UNION
  SELECT pregunta_id FROM combos_preguntas
) r ON r.pregunta_id = p.id
SET p.estado_disponibilidad = 'disponible'
WHERE r.pregunta_id IS NULL
  AND p.estado <> 'usada';
